  ('warsh-55-73', 'warsh', 55, 73, 'لَمْ يَطْمِثْهُنَّ إِنسࣱ قَبْلَهُمْ وَلَا جَآنࣱّ࣌', 'لم يطمثهن إنس قبلهم ولا جان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-74', 'warsh', 55, 74, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-75', 'warsh', 55, 75, 'مُتَّكِـِٕينَ عَلَىٰ رَفْرَفٍ خُضْرࣲ وَعَبْقَرِيٍّ حِسَانࣲ࣌', 'متكين على رفرف خضر وعبقري حسان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-76', 'warsh', 55, 76, 'فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ࣌', 'فبأي ءالاء ربكما تكذبان࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-55-77', 'warsh', 55, 77, 'تَبَٰرَكَ ࡰٜسْمُ رَبِّكَ ذِے ࡴ۬لْجَلَٰلِ وَالِاكْرَامِ࣌', 'تبرك ࡰسم ربك ذے ࡴلجلل والاكرام࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-1', 'warsh', 56, 1, 'إِذَا وَقَعَتِ ࡴ۬لْوَاقِعَةُ', 'إذا وقعت ࡴلواقعة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-2', 'warsh', 56, 2, 'لَيْسَ لِوَقْعَتِهَا كَٰذِبَةٌ࣌', 'ليس لوقعتها كذبة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-3', 'warsh', 56, 3, 'خَافِضَةࣱ رَّافِعَةٌ', 'خافضة رافعة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-4', 'warsh', 56, 4, 'ࡴذَا رُجَّتِ ࡴ۬لَارْضُ رَجّاࣰ', 'ࡴذا رجت ࡴلارض رجا', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-5', 'warsh', 56, 5, 'وَبُسَّتِ ࡴ۬لْجِبَالُ بَسّاࣰ', 'وبست ࡴلجبال بسا', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-6', 'warsh', 56, 6, 'فَكَانَتْ هَبَآءࣰ مُّنۢبَثّاࣰ', 'فكانت هباء منبثا', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-7', 'warsh', 56, 7, 'وَكُنتُمُۥٓ أَزْوَٰجاࣰ ثَلَٰثَةࣰ࣌', 'وكنتم أزوجا ثلثة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-8', 'warsh', 56, 8, 'فَأَصْحَٰبُ ࡲ۬لْمَيْمَنَةِ', 'فأصحب ࡲلميمنة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-9', 'warsh', 56, 9, 'مَآ أَصْحَٰبُ ࡲ۬لْمَيْمَنَةِ࣌', 'ما أصحب ࡲلميمنة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-10', 'warsh', 56, 10, 'وَأَصْحَٰبُ ࡲ۬لْمَشْـَٔمَةِ', 'وأصحب ࡲلمشمة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-11', 'warsh', 56, 11, 'مَآ أَصْحَٰبُ ࡲ۬لْمَشْـَٔمَةِ࣌', 'ما أصحب ࡲلمشمة࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-12', 'warsh', 56, 12, 'وَالسَّٰبِقُونَ ࡰ۬لسَّٰبِقُونَ࣌', 'والسبقون ࡰلسبقون࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-13', 'warsh', 56, 13, 'أُوْلَٰٓئِكَ ࡰ۬لْمُقَرَّبُونَ', 'أولئك ࡰلمقربون', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-14', 'warsh', 56, 14, 'فِے جَنَّٰتِ ࡴ۬لنَّعِيمِ࣌', 'فے جنت ࡴلنعيم࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-15', 'warsh', 56, 15, 'ثُلَّةࣱ مِّنَ ࡰ۬لَاوَّلِينَ', 'ثلة من ࡰلاولين', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-16', 'warsh', 56, 16, 'وَقَلِيلࣱ مِّنَ ࡰ۬لَاخِرِينَ', 'وقليل من ࡰلاخرين', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-17', 'warsh', 56, 17, 'عَلَىٰ سُرُرࣲ مَّوْضُونَةࣲ', 'على سرر موضونة', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-18', 'warsh', 56, 18, 'مُّتَّكِـِٕينَ عَلَيْهَا مُتَقَٰبِلِينَ࣌', 'متكين عليها متقبلين࣌', NULL, 534, 'local:warsh-text.json'),
  ('warsh-56-19', 'warsh', 56, 19, 'يَطُوفُ عَلَيْهِمْ وِلْدَٰنࣱ مُّخَلَّدُونَ', 'يطوف عليهم ولدن مخلدون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-20', 'warsh', 56, 20, 'بِأَكْوَابࣲ وَأَبَارِيقَ', 'بأكواب وأباريق', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-21', 'warsh', 56, 21, 'وَكَأْسࣲ مِّن مَّعِينࣲ', 'وكأس من معين', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-22', 'warsh', 56, 22, 'لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزَفُونَ', 'لا يصدعون عنها ولا ينزفون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-23', 'warsh', 56, 23, 'وَفَٰكِهَةࣲ مِّمَّا يَتَخَيَّرُونَ', 'وفكهة مما يتخيرون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-24', 'warsh', 56, 24, 'وَلَحْمِ طَيْرࣲ مِّمَّا يَشْتَهُونَ࣌', 'ولحم طير مما يشتهون࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-25', 'warsh', 56, 25, 'وَحُورٌ عِينࣱ كَأَمْثَٰلِ ࡴ۬للُّؤْلُوِٕ ࡴ۬لْمَكْنُونِ', 'وحور عين كأمثل ࡴللؤلو ࡴلمكنون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-26', 'warsh', 56, 26, 'جَزَآءَۢ بِمَا كَانُواْ يَعْمَلُونَ࣌', 'جزاء بما كانوا يعملون࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-27', 'warsh', 56, 27, 'لَا يَسْمَعُونَ فِيهَا لَغْواࣰ وَلَا تَاثِيماً࣌', 'لا يسمعون فيها لغوا ولا تاثيما࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-28', 'warsh', 56, 28, 'ࡴلَّا قِيلاࣰ سَلَٰماࣰ سَلَٰماࣰ࣌', 'ࡴلا قيلا سلما سلما࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-29', 'warsh', 56, 29, 'وَأَصْحَٰبُ ࡲ۬لْيَمِينِ مَآ أَصْحَٰبُ ࡲ۬لْيَمِينِ࣌', 'وأصحب ࡲليمين ما أصحب ࡲليمين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-30', 'warsh', 56, 30, 'فِے سِدْرࣲ مَّخْضُودࣲ', 'فے سدر مخضود', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-31', 'warsh', 56, 31, 'وَطَلْحࣲ مَّنضُودࣲ', 'وطلح منضود', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-32', 'warsh', 56, 32, 'وَظِلࣲّ مَّمْدُودࣲ', 'وظل ممدود', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-33', 'warsh', 56, 33, 'وَمَآءࣲ مَّسْكُوبࣲ', 'وماء مسكوب', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-34', 'warsh', 56, 34, 'وَفَٰكِهَةࣲ كَثِيرَةࣲ', 'وفكهة كثيرة', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-35', 'warsh', 56, 35, 'لَّا مَقْطُوعَةࣲ وَلَا مَمْنُوعَةࣲ', 'لا مقطوعة ولا ممنوعة', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-36', 'warsh', 56, 36, 'وَفُرُشࣲ مَّرْفُوعَةٍ࣌', 'وفرش مرفوعة࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-37', 'warsh', 56, 37, 'ࡴنَّآ أَنشَأْنَٰهُنَّ إِنشَآءࣰ', 'ࡴنا أنشأنهن إنشاء', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-38', 'warsh', 56, 38, 'فَجَعَلْنَٰهُنَّ أَبْكَاراً', 'فجعلنهن أبكارا', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-39', 'warsh', 56, 39, 'عُرُباً ࡰتْرَاباࣰ', 'عربا ࡰترابا', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-40', 'warsh', 56, 40, 'لِّأَصْحَٰبِ ࡴ۬لْيَمِينِ࣌', 'لأصحب ࡴليمين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-41', 'warsh', 56, 41, 'ثُلَّةࣱ مِّنَ ࡰ۬لَاوَّلِينَ', 'ثلة من ࡰلاولين', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-42', 'warsh', 56, 42, 'وَثُلَّةࣱ مِّنَ ࡰ۬لَاخِرِينَ࣌', 'وثلة من ࡰلاخرين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-43', 'warsh', 56, 43, 'وَأَصْحَٰبُ ࡲ۬لشِّمَالِ', 'وأصحب ࡲلشمال', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-44', 'warsh', 56, 44, 'مَآ أَصْحَٰبُ ࡲ۬لشِّمَالِ࣌', 'ما أصحب ࡲلشمال࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-45', 'warsh', 56, 45, 'فِے سَمُومࣲ وَحَمِيمࣲ', 'فے سموم وحميم', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-46', 'warsh', 56, 46, 'وَظِلࣲّ مِّنْ يَّحْمُومࣲ', 'وظل من يحموم', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-47', 'warsh', 56, 47, 'لَّا بَارِدࣲ وَلَا كَرِيمٍ࣌', 'لا بارد ولا كريم࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-48', 'warsh', 56, 48, 'ࡴنَّهُمْ كَانُواْ قَبْلَ ذَٰلِكَ مُتْرَفِينَ࣌', 'ࡴنهم كانوا قبل ذلك مترفين࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-49', 'warsh', 56, 49, 'وَكَانُواْ يُصِرُّونَ عَلَى ࡰ۬لْحِنثِ ࡴ۬لْعَظِيمِ࣌', 'وكانوا يصرون على ࡰلحنث ࡴلعظيم࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-50', 'warsh', 56, 50, 'وَكَانُواْ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَاباࣰ وَعِظَٰماً ࡴنَّا لَمَبْعُوثُونَ', 'وكانوا يقولون أئذا متنا وكنا ترابا وعظما ࡴنا لمبعوثون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-51', 'warsh', 56, 51, 'أَوَءَابَآؤُنَا ࡰ۬لَاوَّلُونَ࣌', 'أوءاباؤنا ࡰلاولون࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-52', 'warsh', 56, 52, '۞ قُلِ ࡴنَّ ࡰ۬لَاوَّلِينَ وَالَاخِرِينَ لَمَجْمُوعُونَ', 'قل ࡴن ࡰلاولين والاخرين لمجموعون', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-53', 'warsh', 56, 53, 'إِلَىٰ مِيقَٰتِ يَوْمࣲ مَّعْلُومࣲ࣌', 'إلى ميقت يوم معلوم࣌', NULL, 535, 'local:warsh-text.json'),
  ('warsh-56-54', 'warsh', 56, 54, 'ثُمَّ إِنَّكُمُۥٓ أَيُّهَا ࡰ۬لضَّآلُّونَ ࡰ۬لْمُكَذِّبُونَ', 'ثم إنكم أيها ࡰلضالون ࡰلمكذبون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-55', 'warsh', 56, 55, 'لَأٓكِلُونَ مِن شَجَرࣲ مِّن زَقُّومࣲ', 'لأكلون من شجر من زقوم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-56', 'warsh', 56, 56, 'فَمَالِـُٔونَ مِنْهَا ࡰ۬لْبُطُونَ', 'فمالون منها ࡰلبطون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-57', 'warsh', 56, 57, 'فَشَٰرِبُونَ عَلَيْهِ مِنَ ࡰ۬لْحَمِيمِ', 'فشربون عليه من ࡰلحميم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-58', 'warsh', 56, 58, 'فَشَٰرِبُونَ شُرْبَ ࡰ۬لْهِيمِ࣌', 'فشربون شرب ࡰلهيم࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-59', 'warsh', 56, 59, 'هَٰذَا نُزُلُهُمْ يَوْمَ ࡰ۬لدِّينِ࣌', 'هذا نزلهم يوم ࡰلدين࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-60', 'warsh', 56, 60, 'نَحْنُ خَلَقْنَٰكُمْ࣌ فَلَوْلَا تُصَدِّقُونَ࣌', 'نحن خلقنكم࣌ فلولا تصدقون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-61', 'warsh', 56, 61, 'أَفَرَٰٓيْتُم مَّا تُمْنُونَ', 'أفريتم ما تمنون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-62', 'warsh', 56, 62, 'ءَآنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ࡲ۬لْخَٰلِقُونَ࣌', 'ءانتم تخلقونه أم نحن ࡲلخلقون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-63', 'warsh', 56, 63, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ࡲ۬لْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'نحن قدرنا بينكم ࡲلموت وما نحن بمسبوقين', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-64', 'warsh', 56, 64, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِے مَا لَا تَعْلَمُونَ࣌', 'على أن نبدل أمثلكم وننشئكم فے ما لا تعلمون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-65', 'warsh', 56, 65, 'وَلَقَدْ عَلِمْتُمُ ࡲ۬لنَّشْأَةَ ࡰ۬لُاولٜىٰ࣌ فَلَوْلَا تَذَّكَّرُونَ࣌', 'ولقد علمتم ࡲلنشأة ࡰلاولى࣌ فلولا تذكرون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-66', 'warsh', 56, 66, 'أَفَرَٰٓيْتُم مَّا تَحْرُثُونَ', 'أفريتم ما تحرثون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-67', 'warsh', 56, 67, 'ءَآنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ࡲ۬لزَّٰرِعُونَ࣌', 'ءانتم تزرعونه أم نحن ࡲلزرعون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-68', 'warsh', 56, 68, 'لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰماࣰ فَظَلْتُمْ تَفَكَّهُونَ', 'لو نشاء لجعلنه حطما فظلتم تفكهون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-69', 'warsh', 56, 69, 'إِنَّا لَمُغْرَمُونَ', 'إنا لمغرمون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-70', 'warsh', 56, 70, 'بَلْ نَحْنُ مَحْرُومُونَ࣌', 'بل نحن محرومون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-71', 'warsh', 56, 71, 'أَفَرَٰٓيْتُمُ ࡲ۬لْمَآءَ ࡰ۬لذِے تَشْرَبُونَ', 'أفريتم ࡲلماء ࡰلذے تشربون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-72', 'warsh', 56, 72, 'ءَآنتُمُۥٓ أَنزَلْتُمُوهُ مِنَ ࡰ۬لْمُزْنِ أَمْ نَحْنُ ࡲ۬لْمُنزِلُونَ࣌', 'ءانتم أنزلتموه من ࡰلمزن أم نحن ࡲلمنزلون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-73', 'warsh', 56, 73, 'لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجاࣰ࣌ فَلَوْلَا تَشْكُرُونَ࣌', 'لو نشاء جعلنه أجاجا࣌ فلولا تشكرون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-74', 'warsh', 56, 74, 'أَفَرَٰٓيْتُمُ ࡲ۬لنَّارَ ࡰ۬لتِے تُورُونَ', 'أفريتم ࡲلنار ࡰلتے تورون', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-75', 'warsh', 56, 75, 'ءَآنتُمُۥٓ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ࡲ۬لْمُنشِـُٔونَ࣌', 'ءانتم أنشأتم شجرتها أم نحن ࡲلمنشون࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-76', 'warsh', 56, 76, 'نَحْنُ جَعَلْنَٰهَا تَذْكِرَةࣰ وَمَتَٰعاࣰ لِّلْمُقْوِينَ࣌', 'نحن جعلنها تذكرة ومتعا للمقوين࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-77', 'warsh', 56, 77, 'فَسَبِّحْ بِاسْمِ رَبِّكَ ࡰ۬لْعَظِيمِ࣌', 'فسبح باسم ربك ࡰلعظيم࣌', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-78', 'warsh', 56, 78, '۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ࡴ۬لنُّجُومِ', 'فلا أقسم بموقع ࡴلنجوم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-79', 'warsh', 56, 79, 'وَإِنَّهُۥ لَقَسَمࣱ لَّوْ تَعْلَمُونَ عَظِيمٌ', 'وإنه لقسم لو تعلمون عظيم', NULL, 536, 'local:warsh-text.json'),
  ('warsh-56-80', 'warsh', 56, 80, 'ࡴنَّهُۥ لَقُرْءَانࣱ كَرِيمࣱ', 'ࡴنه لقرءان كريم', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-81', 'warsh', 56, 81, 'فِے كِتَٰبࣲ مَّكْنُونࣲ', 'فے كتب مكنون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-82', 'warsh', 56, 82, 'لَّا يَمَسُّهُۥٓ إِلَّا ࡰ۬لْمُطَهَّرُونَ࣌', 'لا يمسه إلا ࡰلمطهرون࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-83', 'warsh', 56, 83, 'تَنزِيلࣱ مِّن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'تنزيل من رب ࡴلعلمين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-84', 'warsh', 56, 84, 'أَفَبِهَٰذَا ࡰ۬لْحَدِيثِ أَنتُم مُّدْهِنُونَ', 'أفبهذا ࡰلحديث أنتم مدهنون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-85', 'warsh', 56, 85, 'وَتَجْعَلُونَ رِزْقَكُمُۥٓ أَنَّكُمْ تُكَذِّبُونَ࣌', 'وتجعلون رزقكم أنكم تكذبون࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-86', 'warsh', 56, 86, 'فَلَوْلَآ إِذَا بَلَغَتِ ࡴ۬لْحُلْقُومَ', 'فلولا إذا بلغت ࡴلحلقوم', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-87', 'warsh', 56, 87, 'وَأَنتُمْ حِينَئِذࣲ تَنظُرُونَ', 'وأنتم حينئذ تنظرون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-88', 'warsh', 56, 88, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ', 'ونحن أقرب إليه منكم ولكن لا تبصرون', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-89', 'warsh', 56, 89, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', 'فلولا إن كنتم غير مدينين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-90', 'warsh', 56, 90, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ترجعونها إن كنتم صدقين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-91', 'warsh', 56, 91, 'فَأَمَّآ إِن كَانَ مِنَ ࡰ۬لْمُقَرَّبِينَ', 'فأما إن كان من ࡰلمقربين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-92', 'warsh', 56, 92, 'فَرَوْحࣱ وَرَيْحَانࣱ وَجَنَّتُ نَعِيمࣲ࣌', 'فروح وريحان وجنت نعيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-93', 'warsh', 56, 93, 'وَأَمَّآ إِن كَانَ مِنَ ࡰصْحَٰبِ ࡴ۬لْيَمِينِ', 'وأما إن كان من ࡰصحب ࡴليمين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-94', 'warsh', 56, 94, 'فَسَلَٰمࣱ لَّكَ مِنَ ࡰصْحَٰبِ ࡴ۬لْيَمِينِ࣌', 'فسلم لك من ࡰصحب ࡴليمين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-95', 'warsh', 56, 95, 'وَأَمَّآ إِن كَانَ مِنَ ࡰ۬لْمُكَذِّبِينَ ࡰ۬لضَّآلِّينَ', 'وأما إن كان من ࡰلمكذبين ࡰلضالين', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-96', 'warsh', 56, 96, 'فَنُزُلࣱ مِّنْ حَمِيمࣲ', 'فنزل من حميم', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-97', 'warsh', 56, 97, 'وَتَصْلِيَةُ جَحِيمٍ࣌', 'وتصلية جحيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-98', 'warsh', 56, 98, 'ࡴنَّ هَٰذَا لَهُوَ حَقُّ ࡲ۬لْيَقِينِ࣌', 'ࡴن هذا لهو حق ࡲليقين࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-56-99', 'warsh', 56, 99, 'فَسَبِّحْ بِاسْمِ رَبِّكَ ࡰ۬لْعَظِيمِ࣌', 'فسبح باسم ربك ࡰلعظيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-1', 'warsh', 57, 1, 'سَبَّحَ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'سبح لله ما فے ࡴلسموت والارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-2', 'warsh', 57, 2, 'لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ يُحْيِۦ وَيُمِيتُ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'له ملك ࡲلسموت والارض يحي ويميت࣌ وهو على كل شےء قدير࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-3', 'warsh', 57, 3, 'هُوَ ࡰ۬لَاوَّلُ وَالَاخِرُ وَالظَّٰهِرُ وَالْبَاطِنُ࣌ وَهُوَ بِكُلِّ شَےْءٍ عَلِيمٌ࣌', 'هو ࡰلاول والاخر والظهر والباطن࣌ وهو بكل شےء عليم࣌', NULL, 537, 'local:warsh-text.json'),
  ('warsh-57-4', 'warsh', 57, 4, 'هُوَ ࡰ۬لذِے خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ فِے سِتَّةِ أَيَّامࣲ ثُمَّ ࡰٜسْتَوٜىٰ عَلَى ࡰ۬لْعَرْشِ࣌ يَعْلَمُ مَا يَلِجُ فِے ࡴ۬لَارْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ࡰ۬لسَّمَآءِ وَمَا يَعْرُجُ فِيهَا࣌ وَهُوَ مَعَكُمُۥٓ أَيْنَ مَا كُنتُمْ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'هو ࡰلذے خلق ࡰلسموت والارض فے ستة أيام ثم ࡰستوى على ࡰلعرش࣌ يعلم ما يلج فے ࡴلارض وما يخرج منها وما ينزل من ࡰلسماء وما يعرج فيها࣌ وهو معكم أين ما كنتم࣌ والله بما تعملون بصير࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-5', 'warsh', 57, 5, 'لَّهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَإِلَى ࡰ۬للَّهِ تُرْجَعُ ࡲ۬لُامُورُ࣌', 'له ملك ࡲلسموت والارض࣌ وإلى ࡰلله ترجع ࡲلامور࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-6', 'warsh', 57, 6, 'يُولِجُ ࡲ۬ليْلَ فِے ࡴ۬لنَّهٜارِ وَيُولِجُ ࡲ۬لنَّهَارَ فِے ࡴ۬ليْلِ࣌ وَهُوَ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'يولج ࡲليل فے ࡴلنهار ويولج ࡲلنهار فے ࡴليل࣌ وهو عليم بذات ࡴلصدور࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-7', 'warsh', 57, 7, '۞ ءَامِنُواْ بِاللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ࣌ فَالذِينَ ءَامَنُواْ مِنكُمْ وَأَنفَقُواْ لَهُمُۥٓ أَجْرࣱ كَبِيرࣱ࣌', 'ءامنوا بالله ورسوله وأنفقوا مما جعلكم مستخلفين فيه࣌ فالذين ءامنوا منكم وأنفقوا لهم أجر كبير࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-8', 'warsh', 57, 8, 'وَمَا لَكُمْ لَا تُومِنُونَ بِاللَّهِ وَالرَّسُولُ يَدْعُوكُمْ لِتُومِنُواْ بِرَبِّكُمْ وَقَدَ ࡰخَذَ مِيثَٰقَكُمُۥٓ إِن كُنتُم مُّومِنِينَ࣌', 'وما لكم لا تومنون بالله والرسول يدعوكم لتومنوا بربكم وقد ࡰخذ ميثقكم إن كنتم مومنين࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-9', 'warsh', 57, 9, 'هُوَ ࡰ۬لذِے يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتِۢ بَيِّنَٰتࣲ لِّيُخْرِجَكُم مِّنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ࣌ وَإِنَّ ࡰ۬للَّهَ بِكُمْ لَرَءُوفࣱ رَّحِيمࣱ࣌', 'هو ࡰلذے ينزل على عبده ءايت بينت ليخرجكم من ࡰلظلمت إلى ࡰلنور࣌ وإن ࡰلله بكم لرءوف رحيم࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-10', 'warsh', 57, 10, 'وَمَا لَكُمُۥٓ أَلَّا تُنفِقُواْ فِے سَبِيلِ ࡴ۬للَّهِ وَلِلهِ مِيرَٰثُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ لَا يَسْتَوِے مِنكُم مَّنَ ࡰنفَقَ مِن قَبْلِ ࡴ۬لْفَتْحِ وَقَٰتَلَ࣌ أُوْلَٰٓئِكَ أَعْظَمُ دَرَجَةࣰ مِّنَ ࡰ۬لذِينَ أَنفَقُواْ مِنۢ بَعْدُ وَقَٰتَلُواْ࣌ وَكُلّاࣰ وَعَدَ ࡰ۬للَّهُ ࡲ۬لْحُسْنٜىٰ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'وما لكم ألا تنفقوا فے سبيل ࡴلله ولله ميرث ࡲلسموت والارض࣌ لا يستوے منكم من ࡰنفق من قبل ࡴلفتح وقتل࣌ أولئك أعظم درجة من ࡰلذين أنفقوا من بعد وقتلوا࣌ وكلا وعد ࡰلله ࡲلحسنى࣌ والله بما تعملون خبير࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-11', 'warsh', 57, 11, 'مَّن ذَا ࡰ۬لذِے يُقْرِضُ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ فَيُضَٰعِفُهُۥ لَهُۥ وَلَهُۥٓ أَجْرࣱ كَرِيمࣱ࣌', 'من ذا ࡰلذے يقرض ࡲلله قرضا حسنا فيضعفه له وله أجر كريم࣌', NULL, 538, 'local:warsh-text.json'),
  ('warsh-57-12', 'warsh', 57, 12, 'يَوْمَ تَرَى ࡰ۬لْمُومِنِينَ وَالْمُومِنَٰتِ يَسْعٜىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم࣌ بُشْرٜيٰكُمُ ࡲ۬لْيَوْمَ جَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ ذَٰلِكَ هُوَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'يوم ترى ࡰلمومنين والمومنت يسعى نورهم بين أيديهم وبأيمنهم࣌ بشريكم ࡲليوم جنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ ذلك هو ࡰلفوز ࡲلعظيم࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-13', 'warsh', 57, 13, 'يَوْمَ يَقُولُ ࡲ۬لْمُنَٰفِقُونَ وَالْمُنَٰفِقَٰتُ لِلذِينَ ءَامَنُواْ ࡲ࢈نظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ࡰٜرْجِعُواْ وَرَآءَكُمْ فَالْتَمِسُواْ نُوراࣰ࣌ فَضُرِبَ بَيْنَهُم بِسُورࣲ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ࡴ۬لرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ࡴ۬لْعَذَابُ࣌ يُنَادُونَهُمُۥٓ أَلَمْ نَكُن مَّعَكُمْ࣌ قَالُواْ بَلٜىٰ وَلَٰكِنَّكُمْ فَتَنتُمُۥٓ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغَرَّتْكُمُ ࡲ۬لَامَانِيُّ حَتَّىٰ جَآءَ امْرُ ࡲ۬للَّهِ وَغَرَّكُم بِاللَّهِ ࡴ۬لْغَرُورُ࣌', 'يوم يقول ࡲلمنفقون والمنفقت للذين ءامنوا ࡲ࢈نظرونا نقتبس من نوركم قيل ࡰرجعوا وراءكم فالتمسوا نورا࣌ فضرب بينهم بسور له باب باطنه فيه ࡴلرحمة وظهره من قبله ࡴلعذاب࣌ ينادونهم ألم نكن معكم࣌ قالوا بلى ولكنكم فتنتم أنفسكم وتربصتم وارتبتم وغرتكم ࡲلاماني حتى جاء امر ࡲلله وغركم بالله ࡴلغرور࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-14', 'warsh', 57, 14, 'فَالْيَوْمَ لَا يُوخَذُ مِنكُمْ فِدْيَةࣱ وَلَا مِنَ ࡰ۬لذِينَ كَفَرُواْ مَأْوٜيٰكُمُ ࡲ۬لنَّارُ هِيَ مَوْلٜيٰكُمْ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'فاليوم لا يوخذ منكم فدية ولا من ࡰلذين كفروا مأويكم ࡲلنار هي موليكم࣌ وبيس ࡰلمصير࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-15', 'warsh', 57, 15, '۞ أَلَمْ يَانِ لِلذِينَ ءَامَنُوٓاْ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ࡴ۬للَّهِ وَمَا نَزَلَ مِنَ ࡰ۬لْحَقِّ࣌ وَلَا يَكُونُواْ كَالذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ࡲ۬لَامَدُ فَقَسَتْ قُلُوبُهُمْ࣌ وَكَثِيرࣱ مِّنْهُمْ فَٰسِقُونَ࣌', 'ألم يان للذين ءامنوا أن تخشع قلوبهم لذكر ࡴلله وما نزل من ࡰلحق࣌ ولا يكونوا كالذين أوتوا ࡲلكتب من قبل فطال عليهم ࡲلامد فقست قلوبهم࣌ وكثير منهم فسقون࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-16', 'warsh', 57, 16, 'ࡰٜعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ يُحْيِ ࡴ۬لَارْضَ بَعْدَ مَوْتِهَا࣌ قَدْ بَيَّنَّا لَكُمُ ࡲ۬لَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ࣌', 'ࡰعلموا أن ࡰلله يحي ࡴلارض بعد موتها࣌ قد بينا لكم ࡲلايت لعلكم تعقلون࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-17', 'warsh', 57, 17, 'إِنَّ ࡰ۬لْمُصَّدِّقِينَ وَالْمُصَّدِّقَٰتِ وَأَقْرَضُواْ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ يُضَٰعَفُ لَهُمْ وَلَهُمُۥٓ أَجْرࣱ كَرِيمࣱ࣌', 'إن ࡰلمصدقين والمصدقت وأقرضوا ࡲلله قرضا حسنا يضعف لهم ولهم أجر كريم࣌', NULL, 539, 'local:warsh-text.json'),
  ('warsh-57-18', 'warsh', 57, 18, 'وَالذِينَ ءَامَنُواْ بِاللَّهِ وَرُسُلِهِۦٓ أُوْلَٰٓئِكَ هُمُ ࡲ۬لصِّدِّيقُونَ࣌ وَالشُّهَدَآءُ عِندَ رَبِّهِمْ࣌ لَهُمُۥٓ أَجْرُهُمْ وَنُورُهُمْ࣌ وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْجَحِيمِ࣌', 'والذين ءامنوا بالله ورسله أولئك هم ࡲلصديقون࣌ والشهداء عند ربهم࣌ لهم أجرهم ونورهم࣌ والذين كفروا وكذبوا بايتنا أولئك أصحب ࡲلجحيم࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-19', 'warsh', 57, 19, 'ࡴٜعْلَمُوٓاْ أَنَّمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜا لَعِبࣱ وَلَهْوࣱ وَزِينَةࣱ وَتَفَاخُرُۢ بَيْنَكُمْ وَتَكَاثُرࣱ فِے ࡴ۬لَامْوَٰلِ وَالَاوْلَٰدِ كَمَثَلِ غَيْثٍ ࡰعْجَبَ ࡰ۬لْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرٜيٰهُ مُصْفَرّاࣰ ثُمَّ يَكُونُ حُطَٰماࣰ࣌ وَفِے ࡴ۬لَاخِرَةِ عَذَابࣱ شَدِيدࣱ وَمَغْفِرَةࣱ مِّنَ ࡰ۬للَّهِ وَرِضْوَٰنࣱ࣌ وَمَا ࡰ۬لْحَيَوٰةُ ࡲ۬لدُّنْيٜآ إِلَّا مَتَٰعُ ࡲ۬لْغُرُورِ࣌', 'ࡴعلموا أنما ࡰلحيوة ࡲلدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر فے ࡴلامول والاولد كمثل غيث ࡰعجب ࡰلكفار نباته ثم يهيج فتريه مصفرا ثم يكون حطما࣌ وفے ࡴلاخرة عذاب شديد ومغفرة من ࡰلله ورضون࣌ وما ࡰلحيوة ࡲلدنيا إلا متع ࡲلغرور࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-20', 'warsh', 57, 20, 'سَابِقُوٓاْ إِلَىٰ مَغْفِرَةࣲ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ࡴ۬لسَّمَآءِ وَالَارْضِ أُعِدَّتْ لِلذِينَ ءَامَنُواْ بِاللَّهِ وَرُسُلِهِۦ࣌ ذَٰلِكَ فَضْلُ ࡲ۬للَّهِ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'سابقوا إلى مغفرة من ربكم وجنة عرضها كعرض ࡴلسماء والارض أعدت للذين ءامنوا بالله ورسله࣌ ذلك فضل ࡲلله يوتيه من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-21', 'warsh', 57, 21, '۞ مَآ أَصَابَ مِن مُّصِيبَةࣲ فِے ࡴ۬لَارْضِ وَلَا فِےٓ أَنفُسِكُمُۥٓ إِلَّا فِے كِتَٰبࣲ مِّن قَبْلِ أَن نَّبْرَأَهَآ࣌ إِنَّ ذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيرࣱ', 'ما أصاب من مصيبة فے ࡴلارض ولا فے أنفسكم إلا فے كتب من قبل أن نبرأها࣌ إن ذلك على ࡰلله يسير', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-22', 'warsh', 57, 22, 'لِّكَيْلَا تَاسَوْاْ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُواْ بِمَآ ءَاتٜيٰكُمْ࣌ وَاللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالࣲ فَخُورٍ࣌', 'لكيلا تاسوا على ما فاتكم ولا تفرحوا بما ءاتيكم࣌ والله لا يحب كل مختال فخور࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-23', 'warsh', 57, 23, 'ࡴ۬لذِينَ يَبْخَلُونَ وَيَامُرُونَ ࡰ۬لنَّاسَ بِالْبُخْلِ࣌ وَمَنْ يَّتَوَلَّ فَإِنَّ ࡰ۬للَّهَ ࡰ۬لْغَنِيُّ ࡲ۬لْحَمِيدُ࣌', 'ࡴلذين يبخلون ويامرون ࡰلناس بالبخل࣌ ومن يتول فإن ࡰلله ࡰلغني ࡲلحميد࣌', NULL, 540, 'local:warsh-text.json'),
  ('warsh-57-24', 'warsh', 57, 24, 'لَقَدَ ࡰرْسَلْنَا رُسُلَنَا بِالْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ࡲ۬لْكِتَٰبَ وَالْمِيزَانَ لِيَقُومَ ࡰ۬لنَّاسُ بِالْقِسْطِ࣌ وَأَنزَلْنَا ࡰ۬لْحَدِيدَ فِيهِ بَأْسࣱ شَدِيدࣱ وَمَنَٰفِعُ لِلنَّاسِ࣌ وَلِيَعْلَمَ ࡰ۬للَّهُ مَنْ يَّنصُرُهُۥ وَرُسُلَهُۥ بِالْغَيْبِ࣌ إِنَّ ࡰ۬للَّهَ قَوِيٌّ عَزِيزࣱ࣌', 'لقد ࡰرسلنا رسلنا بالبينت وأنزلنا معهم ࡲلكتب والميزان ليقوم ࡰلناس بالقسط࣌ وأنزلنا ࡰلحديد فيه بأس شديد ومنفع للناس࣌ وليعلم ࡰلله من ينصره ورسله بالغيب࣌ إن ࡰلله قوي عزيز࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-25', 'warsh', 57, 25, 'وَلَقَدَ ࡰرْسَلْنَا نُوحاࣰ وَإِبْرَٰهِيمَ وَجَعَلْنَا فِے ذُرِّيَّتِهِمَا ࡰ۬لنُّبُوٓءَةَ وَالْكِتَٰبَ࣌ فَمِنْهُم مُّهْتَدࣲ࣌ وَكَثِيرࣱ مِّنْهُمْ فَٰسِقُونَ࣌', 'ولقد ࡰرسلنا نوحا وإبرهيم وجعلنا فے ذريتهما ࡰلنبوءة والكتب࣌ فمنهم مهتد࣌ وكثير منهم فسقون࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-26', 'warsh', 57, 26, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثٜـٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ࡰٜبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ࡲ۬لِانجِيلَ࣌ وَجَعَلْنَا فِے قُلُوبِ ࡴ۬لذِينَ ࡰٜتَّبَعُوهُ رَأْفَةࣰ وَرَحْمَةࣰ وَرَهْبَانِيَّةً ࡴٜبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمُۥٓ إِلَّا ࡰٜبْتِغَآءَ رِضْوَٰنِ ࡴ۬للَّهِ࣌ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا࣌ فَـَٔاتَيْنَا ࡰ۬لذِينَ ءَامَنُواْ مِنْهُمُۥٓ أَجْرَهُمْ࣌ وَكَثِيرࣱ مِّنْهُمْ فَٰسِقُونَ࣌', 'ثم قفينا على ءاثرهم برسلنا وقفينا بعيسى ࡰبن مريم وءاتينه ࡲلانجيل࣌ وجعلنا فے قلوب ࡴلذين ࡰتبعوه رأفة ورحمة ورهبانية ࡴبتدعوها ما كتبنها عليهم إلا ࡰبتغاء رضون ࡴلله࣌ فما رعوها حق رعايتها࣌ فاتينا ࡰلذين ءامنوا منهم أجرهم࣌ وكثير منهم فسقون࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-27', 'warsh', 57, 27, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُوتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُوراࣰ تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله وءامنوا برسوله يوتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم࣌ والله غفور رحيم', NULL, 541, 'local:warsh-text.json'),
  ('warsh-57-28', 'warsh', 57, 28, 'لِّيَ۬لَّا يَعْلَمَ أَهْلُ ࡲ۬لْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَےْءࣲ مِّن فَضْلِ ࡴ۬للَّهِ وَأَنَّ ࡰ۬لْفَضْلَ بِيَدِ ࡴ۬للَّهِ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'ليلا يعلم أهل ࡲلكتب ألا يقدرون على شےء من فضل ࡴلله وأن ࡰلفضل بيد ࡴلله يوتيه من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 541, 'local:warsh-text.json'),
  ('warsh-58-1', 'warsh', 58, 1, 'قَدْ سَمِعَ ࡰ۬للَّهُ قَوْلَ ࡰ۬لتِے تُجَٰدِلُكَ فِے زَوْجِهَا وَتَشْتَكِےٓ إِلَى ࡰ۬للَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ࣌ إِنَّ ࡰ۬للَّهَ سَمِيعُۢ بَصِيرٌ࣌', 'قد سمع ࡰلله قول ࡰلتے تجدلك فے زوجها وتشتكے إلى ࡰلله والله يسمع تحاوركما࣌ إن ࡰلله سميع بصير࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-2', 'warsh', 58, 2, 'ࡴ۬لذِينَ يَظَّهَّرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمُۥٓ࣌ إِنُ ࡳمَّهَٰتُهُمُۥٓ إِلَّا ࡰ۬لٜےْ وَلَدْنَهُمْ࣌ وَإِنَّهُمْ لَيَقُولُونَ مُنكَراࣰ مِّنَ ࡰ۬لْقَوْلِ وَزُوراࣰ࣌ وَإِنَّ ࡰ۬للَّهَ لَعَفُوٌّ غَفُورࣱ࣌', 'ࡴلذين يظهرون منكم من نسائهم ما هن أمهتهم࣌ إن ࡳمهتهم إلا ࡰلے ولدنهم࣌ وإنهم ليقولون منكرا من ࡰلقول وزورا࣌ وإن ࡰلله لعفو غفور࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-3', 'warsh', 58, 3, 'وَالذِينَ يَظَّهَّرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحْرِيرُ رَقَبَةࣲ مِّن قَبْلِ أَنْ يَّتَمَآسَّا࣌ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'والذين يظهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل أن يتماسا࣌ ذلكم توعظون به࣌ والله بما تعملون خبير࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-4', 'warsh', 58, 4, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَنْ يَّتَمَآسَّا࣌ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِيناࣰ࣌ ذَٰلِكَ لِتُومِنُواْ بِاللَّهِ وَرَسُولِهِۦ࣌ وَتِلْكَ حُدُودُ ࡲ۬للَّهِ࣌ وَلِلْكٜـٰفِرِينَ عَذَابٌ ࡰلِيمٌ࣌', 'فمن لم يجد فصيام شهرين متتابعين من قبل أن يتماسا࣌ فمن لم يستطع فإطعام ستين مسكينا࣌ ذلك لتومنوا بالله ورسوله࣌ وتلك حدود ࡲلله࣌ وللكفرين عذاب ࡰليم࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-5', 'warsh', 58, 5, 'ࡴنَّ ࡰ۬لذِينَ يُحَآدُّونَ ࡰ۬للَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ وَقَدَ ࡰنزَلْنَآ ءَايَٰتِۢ بَيِّنَٰتࣲ࣌ وَلِلْكٜـٰفِرِينَ عَذَابࣱ مُّهِينࣱ࣌', 'ࡴن ࡰلذين يحادون ࡰلله ورسوله كبتوا كما كبت ࡰلذين من قبلهم࣌ وقد ࡰنزلنا ءايت بينت࣌ وللكفرين عذاب مهين࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-6', 'warsh', 58, 6, 'يَوْمَ يَبْعَثُهُمُ ࡲ۬للَّهُ جَمِيعاࣰ فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْ࣌ أَحْصٜيٰهُ ࡲ۬للَّهُ وَنَسُوهُ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدٌ࣌', 'يوم يبعثهم ࡲلله جميعا فينبئهم بما عملوا࣌ أحصيه ࡲلله ونسوه࣌ والله على كل شےء شهيد࣌', NULL, 542, 'local:warsh-text.json'),
  ('warsh-58-7', 'warsh', 58, 7, 'ࡰلَمْ تَرَ أَنَّ ࡰ۬للَّهَ يَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ مَا يَكُونُ مِن نَّجْوٜىٰ ثَلَٰثَةٍ ࡴلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ ࡴلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنٜىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمُۥٓ أَيْنَ مَا كَانُواْ࣌ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوْمَ ࡰ۬لْقِيَٰمَةِ࣌ إِنَّ ࡰ۬للَّهَ بِكُلِّ شَےْءٍ عَلِيمٌ࣌', 'ࡰلم تر أن ࡰلله يعلم ما فے ࡴلسموت وما فے ࡴلارض࣌ ما يكون من نجوى ثلثة ࡴلا هو رابعهم ولا خمسة ࡴلا هو سادسهم ولا أدنى من ذلك ولا أكثر إلا هو معهم أين ما كانوا࣌ ثم ينبئهم بما عملوا يوم ࡰلقيمة࣌ إن ࡰلله بكل شےء عليم࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-8', 'warsh', 58, 8, '۞ ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ نُهُواْ عَنِ ࡴ۬لنَّجْوٜىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنْهُ وَيَتَنَٰجَوْنَ بِالِاثْمِ وَالْعُدْوَٰنِ وَمَعْصِيَتِ ࡴ۬لرَّسُولِ࣌ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ࡴ۬للَّهُ وَيَقُولُونَ فِےٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ࡰ۬للَّهُ بِمَا نَقُولُ࣌ حَسْبُهُمْ جَهَنَّمُ࣌ يَصْلَوْنَهَا࣌ فَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'ࡰلم تر إلى ࡰلذين نهوا عن ࡴلنجوى ثم يعودون لما نهوا عنه ويتنجون بالاثم والعدون ومعصيت ࡴلرسول࣌ وإذا جاءوك حيوك بما لم يحيك به ࡴلله ويقولون فے أنفسهم لولا يعذبنا ࡰلله بما نقول࣌ حسبهم جهنم࣌ يصلونها࣌ فبيس ࡰلمصير࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-9', 'warsh', 58, 9, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْاْ بِالِاثْمِ وَالْعُدْوَٰنِ وَمَعْصِيَتِ ࡴ۬لرَّسُولِ࣌ وَتَنَٰجَوْاْ بِالْبِرِّ وَالتَّقْوٜىٰ࣌ وَاتَّقُواْ ࡲ۬للَّهَ ࡰ۬لذِےٓ إِلَيْهِ تُحْشَرُونَ࣌', 'يأيها ࡰلذين ءامنوا إذا تنجيتم فلا تتنجوا بالاثم والعدون ومعصيت ࡴلرسول࣌ وتنجوا بالبر والتقوى࣌ واتقوا ࡲلله ࡰلذے إليه تحشرون࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-10', 'warsh', 58, 10, 'إِنَّمَا ࡰ۬لنَّجْوٜىٰ مِنَ ࡰ۬لشَّيْطَٰنِ لِيُحْزِنَ ࡰ۬لذِينَ ءَامَنُواْ وَلَيْسَ بِضَآرِّهِمْ شَيْـٔاً ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'إنما ࡰلنجوى من ࡰلشيطن ليحزن ࡰلذين ءامنوا وليس بضارهم شيا ࡴلا بإذن ࡴلله࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-11', 'warsh', 58, 11, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمْ تَفَسَّحُواْ فِے ࡴ۬لْمَجْلِسِ فَافْسَحُواْ يَفْسَحِ ࡴ۬للَّهُ لَكُمْ࣌ وَإِذَا قِيلَ ࡸَنشُزُواْ فَانشُزُواْ يَرْفَعِ ࡴ۬للَّهُ ࡲ۬لذِينَ ءَامَنُواْ مِنكُمْ وَالذِينَ أُوتُواْ ࡲ۬لْعِلْمَ دَرَجَٰتࣲ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'يأيها ࡰلذين ءامنوا إذا قيل لكم تفسحوا فے ࡴلمجلس فافسحوا يفسح ࡴلله لكم࣌ وإذا قيل ࡸنشزوا فانشزوا يرفع ࡴلله ࡲلذين ءامنوا منكم والذين أوتوا ࡲلعلم درجت࣌ والله بما تعملون خبير࣌', NULL, 543, 'local:warsh-text.json'),
  ('warsh-58-12', 'warsh', 58, 12, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيْتُمُ ࡲ۬لرَّسُولَ فَقَدِّمُواْ بَيْنَ يَدَےْ نَجْوٜيٰكُمْ صَدَقَةࣰ࣌ ذَٰلِكَ خَيْرࣱ لَّكُمْ وَأَطْهَرُ࣌ فَإِن لَّمْ تَجِدُواْ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'يأيها ࡰلذين ءامنوا إذا نجيتم ࡲلرسول فقدموا بين يدے نجويكم صدقة࣌ ذلك خير لكم وأطهر࣌ فإن لم تجدوا فإن ࡰلله غفور رحيم࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-13', 'warsh', 58, 13, 'آٓشْفَقْتُمُۥٓ أَن تُقَدِّمُواْ بَيْنَ يَدَےْ نَجْوٜيٰكُمْ صَدَقَٰتࣲ࣌ فَإِذْ لَمْ تَفْعَلُواْ وَتَابَ ࡰ۬للَّهُ عَلَيْكُمْ فَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَأَطِيعُواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ وَاللَّهُ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'آشفقتم أن تقدموا بين يدے نجويكم صدقت࣌ فإذ لم تفعلوا وتاب ࡰلله عليكم فأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ وأطيعوا ࡲلله ورسوله࣌ والله خبير بما تعملون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-14', 'warsh', 58, 14, '۞ أَلَمْ تَرَ إِلَى ࡰ۬لذِينَ تَوَلَّوْاْ قَوْماً غَضِبَ ࡰ۬للَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ࡰ۬لْكَذِبِ وَهُمْ يَعْلَمُونَ࣌', 'ألم تر إلى ࡰلذين تولوا قوما غضب ࡰلله عليهم ما هم منكم ولا منهم ويحلفون على ࡰلكذب وهم يعلمون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-15', 'warsh', 58, 15, 'أَعَدَّ ࡰ۬للَّهُ لَهُمْ عَذَاباࣰ شَدِيداً࣌ ࡴنَّهُمْ سَآءَ مَا كَانُواْ يَعْمَلُونَ࣌', 'أعد ࡰلله لهم عذابا شديدا࣌ ࡴنهم ساء ما كانوا يعملون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-16', 'warsh', 58, 16, 'ࡰٜتَّخَذُوٓاْ أَيْمَٰنَهُمْ جُنَّةࣰ فَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ فَلَهُمْ عَذَابࣱ مُّهِينࣱ࣌', 'ࡰتخذوا أيمنهم جنة فصدوا عن سبيل ࡴلله فلهم عذاب مهين࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-17', 'warsh', 58, 17, 'لَّن تُغْنِيَ عَنْهُمُۥٓ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ࡰ۬للَّهِ شَيْـٔاً࣌ ࡳوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ هُمْ فِيهَا خَٰلِدُونَ࣌', 'لن تغني عنهم أمولهم ولا أولدهم من ࡰلله شيا࣌ ࡳولئك أصحب ࡲلنار هم فيها خلدون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-18', 'warsh', 58, 18, 'يَوْمَ يَبْعَثُهُمُ ࡲ۬للَّهُ جَمِيعاࣰ فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسِبُونَ أَنَّهُمْ عَلَىٰ شَےْءٍ࣌ ࡰلَآ إِنَّهُمْ هُمُ ࡲ۬لْكَٰذِبُونَ࣌', 'يوم يبعثهم ࡲلله جميعا فيحلفون له كما يحلفون لكم ويحسبون أنهم على شےء࣌ ࡰلا إنهم هم ࡲلكذبون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-19', 'warsh', 58, 19, 'ࡰٜسْتَحْوَذَ عَلَيْهِمُ ࡲ۬لشَّيْطَٰنُ فَأَنسٜيٰهُمْ ذِكْرَ ࡰ۬للَّهِ࣌ أُوْلَٰٓئِكَ حِزْبُ ࡲ۬لشَّيْطَٰنِ࣌ أَلَآ إِنَّ حِزْبَ ࡰ۬لشَّيْطَٰنِ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'ࡰستحوذ عليهم ࡲلشيطن فأنسيهم ذكر ࡰلله࣌ أولئك حزب ࡲلشيطن࣌ ألا إن حزب ࡰلشيطن هم ࡲلخسرون࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-20', 'warsh', 58, 20, 'إِنَّ ࡰ۬لذِينَ يُحَآدُّونَ ࡰ۬للَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِے ࡴ۬لَاذَلِّينَ࣌ كَتَبَ ࡰ۬للَّهُ لَأَغْلِبَنَّ أَنَا وَرُسُلِيَ࣌ إِنَّ ࡰ۬للَّهَ قَوِيٌّ عَزِيزࣱ࣌', 'إن ࡰلذين يحادون ࡰلله ورسوله أولئك فے ࡴلاذلين࣌ كتب ࡰلله لأغلبن أنا ورسلي࣌ إن ࡰلله قوي عزيز࣌', NULL, 544, 'local:warsh-text.json'),
  ('warsh-58-21', 'warsh', 58, 21, 'لَّا تَجِدُ قَوْماࣰ يُومِنُونَ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ࡰ۬للَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓاْ ءَابَآءَهُمُۥٓ أَوَ ࡰبْنَآءَهُمُۥٓ أَوِ ࡴخْوَٰنَهُمُۥٓ أَوْ عَشِيرَتَهُمُۥٓ࣌ أُوْلَٰٓئِكَ كَتَبَ فِے قُلُوبِهِمُ ࡲ۬لِايمَٰنَ وَأَيَّدَهُم بِرُوحࣲ مِّنْهُ وَيُدْخِلُهُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَا࣌ رَضِيَ ࡰ۬للَّهُ عَنْهُمْ وَرَضُواْ عَنْهُ࣌ أُوْلَٰٓئِكَ حِزْبُ ࡲ۬للَّهِ࣌ أَلَآ إِنَّ حِزْبَ ࡰ۬للَّهِ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'لا تجد قوما يومنون بالله واليوم ࡴلاخر يوادون من حاد ࡰلله ورسوله ولو كانوا ءاباءهم أو ࡰبناءهم أو ࡴخونهم أو عشيرتهم࣌ أولئك كتب فے قلوبهم ࡲلايمن وأيدهم بروح منه ويدخلهم جنت تجرے من تحتها ࡰلانهر خلدين فيها࣌ رضي ࡰلله عنهم ورضوا عنه࣌ أولئك حزب ࡲلله࣌ ألا إن حزب ࡰلله هم ࡲلمفلحون࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-1', 'warsh', 59, 1, 'سَبَّحَ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'سبح لله ما فے ࡴلسموت وما فے ࡴلارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-2', 'warsh', 59, 2, 'هُوَ ࡰ۬لذِےٓ أَخْرَجَ ࡰ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ مِن دِيٜـٰرِهِمْ لِأَوَّلِ ࡴ۬لْحَشْرِ࣌ مَا ظَنَنتُمُۥٓ أَنْ يَّخْرُجُواْ࣌ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ࡰ۬للَّهِ࣌ فَأَتٜيٰهُمُ ࡲ۬للَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُواْ࣌ ۞ وَقَذَفَ فِے قُلُوبِهِمُ ࡲ۬لرُّعْبَ࣌ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِے ࡴ۬لْمُومِنِينَ࣌ فَاعْتَبِرُواْ يَٰٓأُوْلِے ࡴ۬لَابْصٜـٰرِ࣌', 'هو ࡰلذے أخرج ࡰلذين كفروا من ࡰهل ࡴلكتب من ديرهم لأول ࡴلحشر࣌ ما ظننتم أن يخرجوا࣌ وظنوا أنهم مانعتهم حصونهم من ࡰلله࣌ فأتيهم ࡲلله من حيث لم يحتسبوا࣌  وقذف فے قلوبهم ࡲلرعب࣌ يخربون بيوتهم بأيديهم وأيدے ࡴلمومنين࣌ فاعتبروا يأولے ࡴلابصر࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-3', 'warsh', 59, 3, 'وَلَوْلَآ أَن كَتَبَ ࡰ۬للَّهُ عَلَيْهِمُ ࡲ۬لْجَلَآءَ لَعَذَّبَهُمْ فِے ࡴ۬لدُّنْيٜا࣌ وَلَهُمْ فِے ࡴ۬لَاخِرَةِ عَذَابُ ࡲ۬لنّٜارِ࣌', 'ولولا أن كتب ࡰلله عليهم ࡲلجلاء لعذبهم فے ࡴلدنيا࣌ ولهم فے ࡴلاخرة عذاب ࡲلنار࣌', NULL, 545, 'local:warsh-text.json'),
  ('warsh-59-4', 'warsh', 59, 4, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّواْ ࡲ۬للَّهَ وَرَسُولَهُۥ࣌ وَمَنْ يُّشَآقِّ ࡴ۬للَّهَ فَإِنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'ذلك بأنهم شاقوا ࡲلله ورسوله࣌ ومن يشاق ࡴلله فإن ࡰلله شديد ࡲلعقاب࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-5', 'warsh', 59, 5, 'مَا قَطَعْتُم مِّن لِّينَةٍ ࡰوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ࡴ۬للَّهِ وَلِيُخْزِيَ ࡰ۬لْفَٰسِقِينَ࣌', 'ما قطعتم من لينة ࡰو تركتموها قائمة على أصولها فبإذن ࡴلله وليخزي ࡰلفسقين࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-6', 'warsh', 59, 6, 'وَمَآ أَفَآءَ ࡰ۬للَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلࣲ وَلَا رِكَابࣲ࣌ وَلَٰكِنَّ ࡰ۬للَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَنْ يَّشَآءُ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'وما أفاء ࡰلله على رسوله منهم فما أوجفتم عليه من خيل ولا ركاب࣌ ولكن ࡰلله يسلط رسله على من يشاء࣌ والله على كل شےء قدير࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-7', 'warsh', 59, 7, 'مَّآ أَفَآءَ ࡰ۬للَّهُ عَلَىٰ رَسُولِهِۦ مِنَ ࡰهْلِ ࡴ۬لْقُرٜىٰ فَلِلهِ وَلِلرَّسُولِ وَلِذِے ࡴ۬لْقُرْبٜىٰ وَالْيَتَٰمٜىٰ وَالْمَسَٰكِينِ وَابْنِ ࡴ۬لسَّبِيلِ كَےْ لَا يَكُونَ دُولَةَۢ بَيْنَ ࡰ۬لَاغْنِيَآءِ مِنكُمْ࣌ وَمَآ ءَاتٜيٰكُمُ ࡲ۬لرَّسُولُ فَخُذُوهُ࣌ وَمَا نَهٜيٰكُمْ عَنْهُ فَانتَهُواْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ شَدِيدُ ࡲ۬لْعِقَابِ࣌', 'ما أفاء ࡰلله على رسوله من ࡰهل ࡴلقرى فلله وللرسول ولذے ࡴلقربى واليتمى والمسكين وابن ࡴلسبيل كے لا يكون دولة بين ࡰلاغنياء منكم࣌ وما ءاتيكم ࡲلرسول فخذوه࣌ وما نهيكم عنه فانتهوا࣌ واتقوا ࡲلله࣌ إن ࡰلله شديد ࡲلعقاب࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-8', 'warsh', 59, 8, 'لِلْفُقَرَآءِ ࡴ۬لْمُهَٰجِرِينَ ࡰ۬لذِينَ أُخْرِجُواْ مِن دِيٜـٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلاࣰ مِّنَ ࡰ۬للَّهِ وَرِضْوَٰناࣰ وَيَنصُرُونَ ࡰ۬للَّهَ وَرَسُولَهُۥٓ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لصَّٰدِقُونَ࣌', 'للفقراء ࡴلمهجرين ࡰلذين أخرجوا من ديرهم وأمولهم يبتغون فضلا من ࡰلله ورضونا وينصرون ࡰلله ورسوله࣌ أولئك هم ࡲلصدقون࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-9', 'warsh', 59, 9, 'وَالذِينَ تَبَوَّءُو ࡲ۬لدَّارَ وَالِايمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِے صُدُورِهِمْ حَاجَةࣰ مِّمَّآ أُوتُواْ وَيُوثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةࣱ࣌ وَمَنْ يُّوقَ شُحَّ نَفْسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'والذين تبوءو ࡲلدار والايمن من قبلهم يحبون من هاجر إليهم ولا يجدون فے صدورهم حاجة مما أوتوا ويوثرون على أنفسهم ولو كان بهم خصاصة࣌ ومن يوق شح نفسه فأولئك هم ࡲلمفلحون࣌', NULL, 546, 'local:warsh-text.json'),
  ('warsh-59-10', 'warsh', 59, 10, 'وَالذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ࡰٜغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ࡰ۬لذِينَ سَبَقُونَا بِالِايمَٰنِ وَلَا تَجْعَلْ فِے قُلُوبِنَا غِلّاࣰ لِّلذِينَ ءَامَنُواْ࣌ رَبَّنَآ إِنَّكَ رَءُوفࣱ رَّحِيمٌ࣌', 'والذين جاءو من بعدهم يقولون ربنا ࡰغفر لنا ولإخوننا ࡰلذين سبقونا بالايمن ولا تجعل فے قلوبنا غلا للذين ءامنوا࣌ ربنا إنك رءوف رحيم࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-11', 'warsh', 59, 11, '۞ ࡰلَمْ تَرَ إِلَى ࡰ۬لذِينَ نَافَقُواْ يَقُولُونَ لِإِخْوَٰنِهِمُ ࡲ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ لَئِنُ ࡳخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمُۥٓ أَحَداً ࡰبَداࣰ وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ࣌ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ࣌', 'ࡰلم تر إلى ࡰلذين نافقوا يقولون لإخونهم ࡲلذين كفروا من ࡰهل ࡴلكتب لئن ࡳخرجتم لنخرجن معكم ولا نطيع فيكم أحدا ࡰبدا وإن قوتلتم لننصرنكم࣌ والله يشهد إنهم لكذبون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-12', 'warsh', 59, 12, 'لَئِنُ ࡳخْرِجُواْ لَا يَخْرُجُونَ مَعَهُمْ࣌ وَلَئِن قُوتِلُواْ لَا يَنصُرُونَهُمْ࣌ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ࡰ۬لَادْبَٰرَ ثُمَّ لَا يُنصَرُونَ࣌', 'لئن ࡳخرجوا لا يخرجون معهم࣌ ولئن قوتلوا لا ينصرونهم࣌ ولئن نصروهم ليولن ࡰلادبر ثم لا ينصرون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-13', 'warsh', 59, 13, 'لَأَنتُمُۥٓ أَشَدُّ رَهْبَةࣰ فِے صُدُورِهِم مِّنَ ࡰ۬للَّهِ࣌ ذَٰلِكَ بِأَنَّهُمْ قَوْمࣱ لَّا يَفْقَهُونَ࣌', 'لأنتم أشد رهبة فے صدورهم من ࡰلله࣌ ذلك بأنهم قوم لا يفقهون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-14', 'warsh', 59, 14, 'لَا يُقَٰتِلُونَكُمْ جَمِيعاً ࡴلَّا فِے قُرىࣰ مُّحَصَّنَةٍ ࡰوْ مِنْ وَّرَآءِ جُدُرِۢ࣌ بَأْسُهُم بَيْنَهُمْ شَدِيدࣱ࣌ تَحْسِبُهُمْ جَمِيعاࣰ وَقُلُوبُهُمْ شَتّٜىٰ࣌ ذَٰلِكَ بِأَنَّهُمْ قَوْمࣱ لَّا يَعْقِلُونَ࣌', 'لا يقتلونكم جميعا ࡴلا فے قرى محصنة ࡰو من وراء جدر࣌ بأسهم بينهم شديد࣌ تحسبهم جميعا وقلوبهم شتى࣌ ذلك بأنهم قوم لا يعقلون࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-15', 'warsh', 59, 15, 'كَمَثَلِ ࡴ۬لذِينَ مِن قَبْلِهِمْ قَرِيباࣰ࣌ ذَاقُواْ وَبَالَ أَمْرِهِمْ࣌ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'كمثل ࡴلذين من قبلهم قريبا࣌ ذاقوا وبال أمرهم࣌ ولهم عذاب ࡰليم࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-16', 'warsh', 59, 16, 'كَمَثَلِ ࡴ۬لشَّيْطَٰنِ إِذْ قَالَ لِلِانسَٰنِ ࡴ࢈كْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّے بَرِےٓءࣱ مِّنكَ إِنِّيَ أَخَافُ ࡲ۬للَّهَ رَبَّ ࡰ۬لْعَٰلَمِينَ࣌', 'كمثل ࡴلشيطن إذ قال للانسن ࡴ࢈كفر فلما كفر قال إنے برےء منك إني أخاف ࡲلله رب ࡰلعلمين࣌', NULL, 547, 'local:warsh-text.json'),
  ('warsh-59-17', 'warsh', 59, 17, 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِے ࡴ۬لنّٜارِ خَالِدَيْنِ فِيهَا࣌ وَذَٰلِكَ جَزَٰٓؤُاْ ࡲ۬لظَّٰلِمِينَ࣌', 'فكان عقبتهما أنهما فے ࡴلنار خالدين فيها࣌ وذلك جزؤا ࡲلظلمين࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-18', 'warsh', 59, 18, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ ࡲٜتَّقُواْ ࡲ۬للَّهَ وَلْتَنظُرْ نَفْسࣱ مَّا قَدَّمَتْ لِغَدࣲ࣌ وَاتَّقُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'يأيها ࡰلذين ءامنوا ࡲتقوا ࡲلله ولتنظر نفس ما قدمت لغد࣌ واتقوا ࡲلله࣌ إن ࡰلله خبير بما تعملون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-19', 'warsh', 59, 19, 'وَلَا تَكُونُواْ كَالذِينَ نَسُواْ ࡲ۬للَّهَ فَأَنسٜيٰهُمُۥٓ أَنفُسَهُمُۥٓ࣌ أُوْلَٰٓئِكَ هُمُ ࡲ۬لْفَٰسِقُونَ࣌', 'ولا تكونوا كالذين نسوا ࡲلله فأنسيهم أنفسهم࣌ أولئك هم ࡲلفسقون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-20', 'warsh', 59, 20, 'لَا يَسْتَوِےٓ أَصْحَٰبُ ࡲ۬لنّٜارِ وَأَصْحَٰبُ ࡲ۬لْجَنَّةِ࣌ أَصْحَٰبُ ࡲ۬لْجَنَّةِ هُمُ ࡲ۬لْفَآئِزُونَ࣌', 'لا يستوے أصحب ࡲلنار وأصحب ࡲلجنة࣌ أصحب ࡲلجنة هم ࡲلفائزون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-21', 'warsh', 59, 21, 'لَوَ ࡰنزَلْنَا هَٰذَا ࡰ۬لْقُرْءَانَ عَلَىٰ جَبَلࣲ لَّرَأَيْتَهُۥ خَٰشِعاࣰ مُّتَصَدِّعاࣰ مِّنْ خَشْيَةِ ࡴ۬للَّهِ࣌ وَتِلْكَ ࡰ۬لَامْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ࣌', 'لو ࡰنزلنا هذا ࡰلقرءان على جبل لرأيته خشعا متصدعا من خشية ࡴلله࣌ وتلك ࡰلامثل نضربها للناس لعلهم يتفكرون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-22', 'warsh', 59, 22, 'هُوَ ࡰ۬للَّهُ ࡲ۬لذِے لَآ إِلَٰهَ إِلَّا هُوَ࣌ عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ࣌ هُوَ ࡰ۬لرَّحْمَٰنُ ࡲ۬لرَّحِيمُ࣌', 'هو ࡰلله ࡲلذے لا إله إلا هو࣌ علم ࡲلغيب والشهدة࣌ هو ࡰلرحمن ࡲلرحيم࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-23', 'warsh', 59, 23, 'هُوَ ࡰ۬للَّهُ ࡲ۬لذِے لَآ إِلَٰهَ إِلَّا هُوَ ࡰ۬لْمَلِكُ ࡲ۬لْقُدُّوسُ ࡲ۬لسَّلَٰمُ ࡲ۬لْمُومِنُ ࡲ۬لْمُهَيْمِنُ ࡲ۬لْعَزِيزُ ࡲ۬لْجَبَّارُ ࡲ۬لْمُتَكَبِّرُ࣌ سُبْحَٰنَ ࡰ۬للَّهِ عَمَّا يُشْرِكُونَ࣌', 'هو ࡰلله ࡲلذے لا إله إلا هو ࡰلملك ࡲلقدوس ࡲلسلم ࡲلمومن ࡲلمهيمن ࡲلعزيز ࡲلجبار ࡲلمتكبر࣌ سبحن ࡰلله عما يشركون࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-59-24', 'warsh', 59, 24, 'هُوَ ࡰ۬للَّهُ ࡲ۬لْخَٰلِقُ ࡲ۬لْبَارِۓُ ࡲ۬لْمُصَوِّرُ࣌ لَهُ ࡲ۬لَاسْمَآءُ ࡲ۬لْحُسْنٜىٰ࣌ يُسَبِّحُ لَهُۥ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'هو ࡰلله ࡲلخلق ࡲلبارے ࡲلمصور࣌ له ࡲلاسماء ࡲلحسنى࣌ يسبح له ما فے ࡴلسموت والارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 548, 'local:warsh-text.json'),
  ('warsh-60-1', 'warsh', 60, 1, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّے وَعَدُوَّكُمُۥٓ أَوْلِيَآءَ࣌ تُلْقُونَ إِلَيْهِم بِالْمَوَدَّةِ وَقَدْ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ࡰ۬لْحَقِّ࣌ يُخْرِجُونَ ࡰ۬لرَّسُولَ وَإِيَّاكُمُۥٓ أَن تُومِنُواْ بِاللَّهِ رَبِّكُمُۥٓ࣌ إِن كُنتُمْ خَرَجْتُمْ جِهَٰداࣰ فِے سَبِيلِے وَابْتِغَآءَ مَرْضَاتِے تُسِرُّونَ إِلَيْهِم بِالْمَوَدَّةِ وَأَنَآ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ࣌ وَمَنْ يَّفْعَلْهُ مِنكُمْ فَقَد ضَّلَّ سَوَآءَ ࡰ۬لسَّبِيلِ࣌', 'يأيها ࡰلذين ءامنوا لا تتخذوا عدوے وعدوكم أولياء࣌ تلقون إليهم بالمودة وقد كفروا بما جاءكم من ࡰلحق࣌ يخرجون ࡰلرسول وإياكم أن تومنوا بالله ربكم࣌ إن كنتم خرجتم جهدا فے سبيلے وابتغاء مرضاتے تسرون إليهم بالمودة وأنا أعلم بما أخفيتم وما أعلنتم࣌ ومن يفعله منكم فقد ضل سواء ࡰلسبيل࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-2', 'warsh', 60, 2, 'إِنْ يَّثْقَفُوكُمْ يَكُونُواْ لَكُمُۥٓ أَعْدَآءࣰ وَيَبْسُطُوٓاْ إِلَيْكُمُۥٓ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِالسُّوٓءِ࣌ وَوَدُّواْ لَوْ تَكْفُرُونَ࣌', 'إن يثقفوكم يكونوا لكم أعداء ويبسطوا إليكم أيديهم وألسنتهم بالسوء࣌ وودوا لو تكفرون࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-3', 'warsh', 60, 3, 'لَن تَنفَعَكُمُۥٓ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ࣌ يَوْمَ ࡰ۬لْقِيَٰمَةِ يُفْصَلُ بَيْنَكُمْ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرࣱ࣌', 'لن تنفعكم أرحامكم ولا أولدكم࣌ يوم ࡰلقيمة يفصل بينكم࣌ والله بما تعملون بصير࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-4', 'warsh', 60, 4, 'قَدْ كَانَتْ لَكُمُۥٓ إِسْوَةٌ حَسَنَةࣱ فِےٓ إِبْرَٰهِيمَ وَالذِينَ مَعَهُۥٓ إِذْ قَالُواْ لِقَوْمِهِمُۥٓ إِنَّا بُرَءَٰٓؤُاْ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ࡴ۬للَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ࡲ۬لْعَدَٰوَةُ وَالْبَغْضَآءُ ࡶَبَداً حَتَّىٰ تُومِنُواْ بِاللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ࡰ۬للَّهِ مِن شَےْءࣲ࣌ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ࡰ۬لْمَصِيرُ࣌', 'قد كانت لكم إسوة حسنة فے إبرهيم والذين معه إذ قالوا لقومهم إنا برءؤا منكم ومما تعبدون من دون ࡴلله كفرنا بكم وبدا بيننا وبينكم ࡲلعدوة والبغضاء ࡶبدا حتى تومنوا بالله وحده إلا قول إبرهيم لأبيه لأستغفرن لك وما أملك لك من ࡰلله من شےء࣌ ربنا عليك توكلنا وإليك أنبنا وإليك ࡰلمصير࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-5', 'warsh', 60, 5, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةࣰ لِّلذِينَ كَفَرُواْ࣌ وَاغْفِرْ لَنَا رَبَّنَآ࣌ إِنَّكَ أَنتَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'ربنا لا تجعلنا فتنة للذين كفروا࣌ واغفر لنا ربنا࣌ إنك أنت ࡰلعزيز ࡲلحكيم࣌', NULL, 549, 'local:warsh-text.json'),
  ('warsh-60-6', 'warsh', 60, 6, 'لَقَدْ كَانَ لَكُمْ فِيهِمُۥٓ إِسْوَةٌ حَسَنَةࣱ لِّمَن كَانَ يَرْجُواْ ࡲ۬للَّهَ وَالْيَوْمَ ࡰ۬لَاخِرَ࣌ وَمَنْ يَّتَوَلَّ فَإِنَّ ࡰ۬للَّهَ هُوَ ࡰ۬لْغَنِيُّ ࡲ۬لْحَمِيدُ࣌', 'لقد كان لكم فيهم إسوة حسنة لمن كان يرجوا ࡲلله واليوم ࡰلاخر࣌ ومن يتول فإن ࡰلله هو ࡰلغني ࡲلحميد࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-7', 'warsh', 60, 7, '۞ عَسَى ࡰ۬للَّهُ أَنْ يَّجْعَلَ بَيْنَكُمْ وَبَيْنَ ࡰ۬لذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةࣰ࣌ وَاللَّهُ قَدِيرࣱ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'عسى ࡰلله أن يجعل بينكم وبين ࡰلذين عاديتم منهم مودة࣌ والله قدير࣌ والله غفور رحيم࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-8', 'warsh', 60, 8, 'لَّا يَنْهٜيٰكُمُ ࡲ۬للَّهُ عَنِ ࡴ۬لذِينَ لَمْ يُقَٰتِلُوكُمْ فِے ࡴ۬لدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيٜـٰرِكُمُۥٓ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓاْ إِلَيْهِمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لْمُقْسِطِينَ࣌', 'لا ينهيكم ࡲلله عن ࡴلذين لم يقتلوكم فے ࡴلدين ولم يخرجوكم من ديركم أن تبروهم وتقسطوا إليهم࣌ إن ࡰلله يحب ࡲلمقسطين࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-9', 'warsh', 60, 9, 'إِنَّمَا يَنْهٜيٰكُمُ ࡲ۬للَّهُ عَنِ ࡴ۬لذِينَ قَٰتَلُوكُمْ فِے ࡴ۬لدِّينِ وَأَخْرَجُوكُم مِّن دِيٜـٰرِكُمْ وَظَٰهَرُواْ عَلَىٰٓ إِخْرَاجِكُمُۥٓ أَن تَوَلَّوْهُمْ࣌ وَمَنْ يَّتَوَلَّهُمْ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لظَّٰلِمُونَ࣌', 'إنما ينهيكم ࡲلله عن ࡴلذين قتلوكم فے ࡴلدين وأخرجوكم من ديركم وظهروا على إخراجكم أن تولوهم࣌ ومن يتولهم فأولئك هم ࡲلظلمون࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-10', 'warsh', 60, 10, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ࡲ۬لْمُومِنَٰتُ مُهَٰجِرَٰتࣲ فَامْتَحِنُوهُنَّ࣌ ࡰ۬للَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ࣌ فَإِنْ عَلِمْتُمُوهُنَّ مُومِنَٰتࣲ فَلَا تَرْجِعُوهُنَّ إِلَى ࡰ۬لْكُفّٜارِ࣌ لَا هُنَّ حِلࣱّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ࣌ وَءَاتُوهُم مَّآ أَنفَقُواْ࣌ وَلَا جُنَاحَ عَلَيْكُمُۥٓ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ࣌ وَلَا تُمْسِكُواْ بِعِصَمِ ࡴ۬لْكَوَافِرِ࣌ وَسْـَٔلُواْ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُواْ مَآ أَنفَقُواْ࣌ ذَٰلِكُمْ حُكْمُ ࡲ۬للَّهِ يَحْكُمُ بَيْنَكُمْ࣌ وَاللَّهُ عَلِيمٌ حَكِيمࣱ࣌', 'يأيها ࡰلذين ءامنوا إذا جاءكم ࡲلمومنت مهجرت فامتحنوهن࣌ ࡰلله أعلم بإيمنهن࣌ فإن علمتموهن مومنت فلا ترجعوهن إلى ࡰلكفار࣌ لا هن حل لهم ولا هم يحلون لهن࣌ وءاتوهم ما أنفقوا࣌ ولا جناح عليكم أن تنكحوهن إذا ءاتيتموهن أجورهن࣌ ولا تمسكوا بعصم ࡴلكوافر࣌ وسلوا ما أنفقتم وليسلوا ما أنفقوا࣌ ذلكم حكم ࡲلله يحكم بينكم࣌ والله عليم حكيم࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-11', 'warsh', 60, 11, 'وَإِن فَاتَكُمْ شَےْءࣱ مِّنَ ࡰزْوَٰجِكُمُۥٓ إِلَى ࡰ۬لْكُفّٜارِ فَعَاقَبْتُمْ فَـَٔاتُواْ ࡲ۬لذِينَ ذَهَبَتَ ࡰزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُواْ࣌ وَاتَّقُواْ ࡲ۬للَّهَ ࡰ۬لذِےٓ أَنتُم بِهِۦ مُومِنُونَ࣌', 'وإن فاتكم شےء من ࡰزوجكم إلى ࡰلكفار فعاقبتم فاتوا ࡲلذين ذهبت ࡰزوجهم مثل ما أنفقوا࣌ واتقوا ࡲلله ࡰلذے أنتم به مومنون࣌', NULL, 550, 'local:warsh-text.json'),
  ('warsh-60-12', 'warsh', 60, 12, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ ࡹِذَا جَآءَكَ ࡰ۬لْمُومِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِاللَّهِ شَيْـٔاࣰ وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَاتِينَ بِبُهْتَٰنࣲ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِے مَعْرُوفࣲ فَبَايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ ࡰ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'يأيها‏ ࡰلنبےء ࡹذا جاءك ࡰلمومنت يبايعنك على أن لا يشركن بالله شيا ولا يسرقن ولا يزنين ولا يقتلن أولدهن ولا ياتين ببهتن يفترينه بين أيديهن وأرجلهن ولا يعصينك فے معروف فبايعهن واستغفر لهن ࡰلله࣌ إن ࡰلله غفور رحيم࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-60-13', 'warsh', 60, 13, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تَتَوَلَّوْاْ قَوْماً غَضِبَ ࡰ۬للَّهُ عَلَيْهِمْ قَدْ يَئِسُواْ مِنَ ࡰ۬لَاخِرَةِ كَمَا يَئِسَ ࡰ۬لْكُفَّارُ مِنَ ࡰصْحَٰبِ ࡴ۬لْقُبُورِ࣌', 'يأيها ࡰلذين ءامنوا لا تتولوا قوما غضب ࡰلله عليهم قد يئسوا من ࡰلاخرة كما يئس ࡰلكفار من ࡰصحب ࡴلقبور࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-1', 'warsh', 61, 1, 'سَبَّحَ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'سبح لله ما فے ࡴلسموت وما فے ࡴلارض࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-2', 'warsh', 61, 2, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ࣌', 'يأيها ࡰلذين ءامنوا لم تقولون ما لا تفعلون࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-3', 'warsh', 61, 3, 'كَبُرَ مَقْتاً عِندَ ࡰ۬للَّهِ أَن تَقُولُواْ مَا لَا تَفْعَلُونَ࣌', 'كبر مقتا عند ࡰلله أن تقولوا ما لا تفعلون࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-4', 'warsh', 61, 4, 'إِنَّ ࡰ۬للَّهَ يُحِبُّ ࡲ۬لذِينَ يُقَٰتِلُونَ فِے سَبِيلِهِۦ صَفّاࣰ كَأَنَّهُم بُنْيَٰنࣱ مَّرْصُوصࣱ࣌', 'إن ࡰلله يحب ࡲلذين يقتلون فے سبيله صفا كأنهم بنين مرصوص࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-5', 'warsh', 61, 5, 'وَإِذْ قَالَ مُوسٜىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُوذُونَنِے وَقَد تَّعْلَمُونَ أَنِّے رَسُولُ ࡲ۬للَّهِ إِلَيْكُمْ࣌ فَلَمَّا زَاغُوٓاْ أَزَاغَ ࡰ۬للَّهُ قُلُوبَهُمْ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْفَٰسِقِينَ࣌', 'وإذ قال موسى لقومه يقوم لم توذوننے وقد تعلمون أنے رسول ࡲلله إليكم࣌ فلما زاغوا أزاغ ࡰلله قلوبهم࣌ والله لا يهدے ࡴلقوم ࡰلفسقين࣌', NULL, 551, 'local:warsh-text.json'),
  ('warsh-61-6', 'warsh', 61, 6, 'وَإِذْ قَالَ عِيسَى ࡰٜبْنُ مَرْيَمَ يَٰبَنِےٓ إِسْرَآءِيلَ إِنِّے رَسُولُ ࡲ۬للَّهِ إِلَيْكُم مُّصَدِّقاࣰ لِّمَا بَيْنَ يَدَيَّ مِنَ ࡰ۬لتَّوْرٜيٰةِ وَمُبَشِّراَۢ بِرَسُولࣲ يَاتِے مِنۢ بَعْدِيَ ࡰٜسْمُهُۥٓ أَحْمَدُ࣌ فَلَمَّا جَآءَهُم بِالْبَيِّنَٰتِ قَالُواْ هَٰذَا سِحْرࣱ مُّبِينࣱ࣌', 'وإذ قال عيسى ࡰبن مريم يبنے إسراءيل إنے رسول ࡲلله إليكم مصدقا لما بين يدي من ࡰلتورية ومبشرا برسول ياتے من بعدي ࡰسمه أحمد࣌ فلما جاءهم بالبينت قالوا هذا سحر مبين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-7', 'warsh', 61, 7, 'وَمَنَ ࡰظْلَمُ مِمَّنِ ࡴٜفْتَرٜىٰ عَلَى ࡰ۬للَّهِ ࡴ۬لْكَذِبَ وَهُوَ يُدْعٜىٰٓ إِلَى ࡰ۬لِاسْلَٰمِ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'ومن ࡰظلم ممن ࡴفترى على ࡰلله ࡴلكذب وهو يدعى إلى ࡰلاسلم࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-8', 'warsh', 61, 8, 'يُرِيدُونَ لِيُطْفِـُٔواْ نُورَ ࡰ۬للَّهِ بِأَفْوَٰهِهِمْ وَاللَّهُ مُتِمࣱّ نُّورَهُۥ وَلَوْ كَرِهَ ࡰ۬لْكَٰفِرُونَ࣌', 'يريدون ليطفوا نور ࡰلله بأفوههم والله متم نوره ولو كره ࡰلكفرون࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-9', 'warsh', 61, 9, 'هُوَ ࡰ۬لذِےٓ أَرْسَلَ رَسُولَهُۥ بِالْهُدٜىٰ وَدِينِ ࡴ۬لْحَقِّ لِيُظْهِرَهُۥ عَلَى ࡰ۬لدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ࡰ۬لْمُشْرِكُونَ࣌', 'هو ࡰلذے أرسل رسوله بالهدى ودين ࡴلحق ليظهره على ࡰلدين كله ولو كره ࡰلمشركون࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-10', 'warsh', 61, 10, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ هَلَ ࡰدُلُّكُمْ عَلَىٰ تِجَٰرَةࣲ تُنجِيكُم مِّنْ عَذَابٍ ࡰلِيمࣲ', 'يأيها ࡰلذين ءامنوا هل ࡰدلكم على تجرة تنجيكم من عذاب ࡰليم', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-11', 'warsh', 61, 11, 'تُومِنُونَ بِاللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِے سَبِيلِ ࡴ۬للَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ذَٰلِكُمْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ', 'تومنون بالله ورسوله وتجهدون فے سبيل ࡴلله بأمولكم وأنفسكم ذلكم خير لكم إن كنتم تعلمون', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-12', 'warsh', 61, 12, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ وَمَسَٰكِنَ طَيِّبَةࣰ فِے جَنَّٰتِ عَدْنࣲ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'يغفر لكم ذنوبكم ويدخلكم جنت تجرے من تحتها ࡰلانهر ومسكن طيبة فے جنت عدن࣌ ذلك ࡰلفوز ࡲلعظيم࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-13', 'warsh', 61, 13, 'وَأُخْرٜىٰ تُحِبُّونَهَا نَصْرࣱ مِّنَ ࡰ۬للَّهِ وَفَتْحࣱ قَرِيبࣱ࣌ وَبَشِّرِ ࡴ۬لْمُومِنِينَ࣌', 'وأخرى تحبونها نصر من ࡰلله وفتح قريب࣌ وبشر ࡴلمومنين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-61-14', 'warsh', 61, 14, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَاراࣰ لِّلهِ كَمَا قَالَ عِيسَى ࡰٜبْنُ مَرْيَمَ لِلْحَوَارِيِّۑنَ مَنَ ࡰنصَارِيَ إِلَى ࡰ۬للَّهِ࣌ قَالَ ࡰ۬لْحَوَارِيُّونَ نَحْنُ أَنصَارُ ࡲ۬للَّهِ࣌ فَـَٔامَنَت طَّآئِفَةࣱ مِّنۢ بَنِےٓ إِسْرَآءِيلَ وَكَفَرَت طَّآئِفَةࣱ࣌ فَأَيَّدْنَا ࡰ۬لذِينَ ءَامَنُواْ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُواْ ظَٰهِرِينَ࣌', 'يأيها ࡰلذين ءامنوا كونوا أنصارا لله كما قال عيسى ࡰبن مريم للحواريۑن من ࡰنصاري إلى ࡰلله࣌ قال ࡰلحواريون نحن أنصار ࡲلله࣌ فامنت طائفة من بنے إسراءيل وكفرت طائفة࣌ فأيدنا ࡰلذين ءامنوا على عدوهم فأصبحوا ظهرين࣌', NULL, 552, 'local:warsh-text.json'),
  ('warsh-62-1', 'warsh', 62, 1, 'يُسَبِّحُ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ ࡴ۬لْمَلِكِ ࡴ۬لْقُدُّوسِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَكِيمِ࣌', 'يسبح لله ما فے ࡴلسموت وما فے ࡴلارض ࡴلملك ࡴلقدوس ࡴلعزيز ࡴلحكيم࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-2', 'warsh', 62, 2, 'هُوَ ࡰ۬لذِے بَعَثَ فِے ࡴ۬لُامِّيِّۑنَ رَسُولاࣰ مِّنْهُمْ يَتْلُواْ عَلَيْهِمُۥٓ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ࡲ۬لْكِتَٰبَ وَالْحِكْمَةَ وَإِن كَانُواْ مِن قَبْلُ لَفِے ضَلَٰلࣲ مُّبِينࣲ', 'هو ࡰلذے بعث فے ࡴلاميۑن رسولا منهم يتلوا عليهم ءايته ويزكيهم ويعلمهم ࡲلكتب والحكمة وإن كانوا من قبل لفے ضلل مبين', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-3', 'warsh', 62, 3, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُواْ بِهِمْ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'وءاخرين منهم لما يلحقوا بهم࣌ وهو ࡰلعزيز ࡲلحكيم࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-4', 'warsh', 62, 4, 'ذَٰلِكَ فَضْلُ ࡲ۬للَّهِ يُوتِيهِ مَنْ يَّشَآءُ࣌ وَاللَّهُ ذُو ࡲ۬لْفَضْلِ ࡴ۬لْعَظِيمِ࣌', 'ذلك فضل ࡲلله يوتيه من يشاء࣌ والله ذو ࡲلفضل ࡴلعظيم࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-5', 'warsh', 62, 5, 'مَثَلُ ࡲ۬لذِينَ حُمِّلُواْ ࡲ۬لتَّوْرٜيٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ࡴ۬لْحِمٜارِ يَحْمِلُ أَسْفَاراَۢ࣌ بِيسَ مَثَلُ ࡲ۬لْقَوْمِ ࡴ۬لذِينَ كَذَّبُواْ بِـَٔايَٰتِ ࡴ۬للَّهِ࣌ وَاللَّهُ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لظَّٰلِمِينَ࣌', 'مثل ࡲلذين حملوا ࡲلتورية ثم لم يحملوها كمثل ࡴلحمار يحمل أسفارا࣌ بيس مثل ࡲلقوم ࡴلذين كذبوا بايت ࡴلله࣌ والله لا يهدے ࡴلقوم ࡰلظلمين࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-6', 'warsh', 62, 6, 'قُلْ يَٰٓأَيُّهَا ࡰ۬لذِينَ هَادُوٓاْ إِن زَعَمْتُمُۥٓ أَنَّكُمُۥٓ أَوْلِيَآءُ لِلهِ مِن دُونِ ࡴ۬لنَّاسِ فَتَمَنَّوُاْ ࡲ۬لْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ࣌', 'قل يأيها ࡰلذين هادوا إن زعمتم أنكم أولياء لله من دون ࡴلناس فتمنوا ࡲلموت إن كنتم صدقين࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-7', 'warsh', 62, 7, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَداَۢ بِمَا قَدَّمَتَ ࡰيْدِيهِمْ࣌ وَاللَّهُ عَلِيمُۢ بِالظَّٰلِمِينَ࣌', 'ولا يتمنونه أبدا بما قدمت ࡰيديهم࣌ والله عليم بالظلمين࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-8', 'warsh', 62, 8, 'قُلِ ࡴنَّ ࡰ۬لْمَوْتَ ࡰ۬لذِے تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ࡴ۬لْغَيْبِ وَالشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'قل ࡴن ࡰلموت ࡰلذے تفرون منه فإنه ملقيكم ثم تردون إلى علم ࡴلغيب والشهدة فينبئكم بما كنتم تعملون࣌', NULL, 553, 'local:warsh-text.json'),
  ('warsh-62-9', 'warsh', 62, 9, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِنْ يَّوْمِ ࡴ۬لْجُمُعَةِ فَاسْعَوِاْ ࡴلَىٰ ذِكْرِ ࡴ۬للَّهِ وَذَرُواْ ࡲ۬لْبَيْعَ࣌ ذَٰلِكُمْ خَيْرࣱ لَّكُمُۥٓ إِن كُنتُمْ تَعْلَمُونَ࣌', 'يأيها ࡰلذين ءامنوا إذا نودي للصلوة من يوم ࡴلجمعة فاسعوا ࡴلى ذكر ࡴلله وذروا ࡲلبيع࣌ ذلكم خير لكم إن كنتم تعلمون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-62-10', 'warsh', 62, 10, 'فَإِذَا قُضِيَتِ ࡴ۬لصَّلَوٰةُ فَانتَشِرُواْ فِے ࡴ۬لَارْضِ وَابْتَغُواْ مِن فَضْلِ ࡴ۬للَّهِ وَاذْكُرُواْ ࡲ۬للَّهَ كَثِيراࣰ لَّعَلَّكُمْ تُفْلِحُونَ࣌', 'فإذا قضيت ࡴلصلوة فانتشروا فے ࡴلارض وابتغوا من فضل ࡴلله واذكروا ࡲلله كثيرا لعلكم تفلحون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-62-11', 'warsh', 62, 11, 'وَإِذَا رَأَوْاْ تِجَٰرَةً ࡰوْ لَهْواً ࡴٜنفَضُّوٓاْ إِلَيْهَا وَتَرَكُوكَ قَآئِماࣰ࣌ قُلْ مَا عِندَ ࡰ۬للَّهِ خَيْرࣱ مِّنَ ࡰ۬للَّهْوِ وَمِنَ ࡰ۬لتِّجَٰرَةِ࣌ وَاللَّهُ خَيْرُ ࡲ۬لرَّٰزِقِينَ࣌', 'وإذا رأوا تجرة ࡰو لهوا ࡴنفضوا إليها وتركوك قائما࣌ قل ما عند ࡰلله خير من ࡰللهو ومن ࡰلتجرة࣌ والله خير ࡲلرزقين࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-1', 'warsh', 63, 1, 'إِذَا جَآءَكَ ࡰ۬لْمُنَٰفِقُونَ قَالُواْ نَشْهَدُ إِنَّكَ لَرَسُولُ ࡲ۬للَّهِ࣌ وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ࣌ وَاللَّهُ يَشْهَدُ إِنَّ ࡰ۬لْمُنَٰفِقِينَ لَكَٰذِبُونَ࣌', 'إذا جاءك ࡰلمنفقون قالوا نشهد إنك لرسول ࡲلله࣌ والله يعلم إنك لرسوله࣌ والله يشهد إن ࡰلمنفقين لكذبون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-2', 'warsh', 63, 2, 'ࡰٜتَّخَذُوٓاْ أَيْمَٰنَهُمْ جُنَّةࣰ فَصَدُّواْ عَن سَبِيلِ ࡴ۬للَّهِ࣌ إِنَّهُمْ سَآءَ مَا كَانُواْ يَعْمَلُونَ࣌', 'ࡰتخذوا أيمنهم جنة فصدوا عن سبيل ࡴلله࣌ إنهم ساء ما كانوا يعملون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-3', 'warsh', 63, 3, 'ذَٰلِكَ بِأَنَّهُمُۥٓ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ࣌', 'ذلك بأنهم ءامنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-4', 'warsh', 63, 4, 'وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ࣌ وَإِنْ يَّقُولُواْ تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبࣱ مُّسَنَّدَةࣱ࣌ يَحْسِبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ࣌ هُمُ ࡲ۬لْعَدُوُّ࣌ فَاحْذَرْهُمْ࣌ قَٰتَلَهُمُ ࡲ۬للَّهُ࣌ أَنّٜىٰ يُوفَكُونَ࣌', 'وإذا رأيتهم تعجبك أجسامهم࣌ وإن يقولوا تسمع لقولهم كأنهم خشب مسندة࣌ يحسبون كل صيحة عليهم࣌ هم ࡲلعدو࣌ فاحذرهم࣌ قتلهم ࡲلله࣌ أنى يوفكون࣌', NULL, 554, 'local:warsh-text.json'),
  ('warsh-63-5', 'warsh', 63, 5, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْاْ يَسْتَغْفِرْ لَكُمْ رَسُولُ ࡲ۬للَّهِ لَوَوْاْ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ࣌', 'وإذا قيل لهم تعالوا يستغفر لكم رسول ࡲلله لووا رءوسهم ورأيتهم يصدون وهم مستكبرون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-6', 'warsh', 63, 6, 'سَوَآءٌ عَلَيْهِمُۥٓ أَسْتَغْفَرْتَ لَهُمُۥٓ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ࣌ لَنْ يَّغْفِرَ ࡰ۬للَّهُ لَهُمُۥٓ࣌ إِنَّ ࡰ۬للَّهَ لَا يَهْدِے ࡴ۬لْقَوْمَ ࡰ۬لْفَٰسِقِينَ࣌', 'سواء عليهم أستغفرت لهم أم لم تستغفر لهم࣌ لن يغفر ࡰلله لهم࣌ إن ࡰلله لا يهدے ࡴلقوم ࡰلفسقين࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-7', 'warsh', 63, 7, 'هُمُ ࡲ۬لذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنْ عِندَ رَسُولِ ࡴ۬للَّهِ حَتَّىٰ يَنفَضُّواْ࣌ وَلِلهِ خَزَآئِنُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَلَٰكِنَّ ࡰ۬لْمُنَٰفِقِينَ لَا يَفْقَهُونَ࣌', 'هم ࡲلذين يقولون لا تنفقوا على من عند رسول ࡴلله حتى ينفضوا࣌ ولله خزائن ࡲلسموت والارض࣌ ولكن ࡰلمنفقين لا يفقهون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-8', 'warsh', 63, 8, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ࡰ۬لْمَدِينَةِ لَيُخْرِجَنَّ ࡰ۬لَاعَزُّ مِنْهَا ࡰ۬لَاذَلَّ࣌ وَلِلهِ ࡴ۬لْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُومِنِينَ࣌ وَلَٰكِنَّ ࡰ۬لْمُنَٰفِقِينَ لَا يَعْلَمُونَ࣌', 'يقولون لئن رجعنا إلى ࡰلمدينة ليخرجن ࡰلاعز منها ࡰلاذل࣌ ولله ࡴلعزة ولرسوله وللمومنين࣌ ولكن ࡰلمنفقين لا يعلمون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-9', 'warsh', 63, 9, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ لَا تُلْهِكُمُۥٓ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ࡴ۬للَّهِ࣌ وَمَنْ يَّفْعَلْ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْخَٰسِرُونَ࣌', 'يأيها ࡰلذين ءامنوا لا تلهكم أمولكم ولا أولدكم عن ذكر ࡴلله࣌ ومن يفعل ذلك فأولئك هم ࡲلخسرون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-10', 'warsh', 63, 10, 'وَأَنفِقُواْ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَنْ يَّاتِيَ أَحَدَكُمُ ࡲ۬لْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِےٓ إِلَىٰٓ أَجَلࣲ قَرِيبࣲ فَأَصَّدَّقَ وَأَكُن مِّنَ ࡰ۬لصَّٰلِحِينَ࣌', 'وأنفقوا من ما رزقنكم من قبل أن ياتي أحدكم ࡲلموت فيقول رب لولا أخرتنے إلى أجل قريب فأصدق وأكن من ࡰلصلحين࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-63-11', 'warsh', 63, 11, 'وَلَنْ يُّوَ۬خِّرَ ࡰ۬للَّهُ نَفْساً ࡴذَا جَآءَ اجَلُهَا࣌ وَاللَّهُ خَبِيرُۢ بِمَا تَعْمَلُونَ࣌', 'ولن يوخر ࡰلله نفسا ࡴذا جاء اجلها࣌ والله خبير بما تعملون࣌', NULL, 555, 'local:warsh-text.json'),
  ('warsh-64-1', 'warsh', 64, 1, 'يُسَبِّحُ لِلهِ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَمَا فِے ࡴ۬لَارْضِ࣌ لَهُ ࡲ۬لْمُلْكُ وَلَهُ ࡲ۬لْحَمْدُ࣌ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'يسبح لله ما فے ࡴلسموت وما فے ࡴلارض࣌ له ࡲلملك وله ࡲلحمد࣌ وهو على كل شےء قدير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-2', 'warsh', 64, 2, 'هُوَ ࡰ۬لذِے خَلَقَكُمْ فَمِنكُمْ كَافِرࣱ وَمِنكُم مُّومِنࣱ࣌ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ࣌', 'هو ࡰلذے خلقكم فمنكم كافر ومنكم مومن࣌ والله بما تعملون بصير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-3', 'warsh', 64, 3, 'خَلَقَ ࡰ۬لسَّمَٰوَٰتِ وَالَارْضَ بِالْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ࣌ وَإِلَيْهِ ࡴ۬لْمَصِيرُ࣌', 'خلق ࡰلسموت والارض بالحق وصوركم فأحسن صوركم࣌ وإليه ࡴلمصير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-4', 'warsh', 64, 4, 'يَعْلَمُ مَا فِے ࡴ۬لسَّمَٰوَٰتِ وَالَارْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ࣌ وَاللَّهُ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'يعلم ما فے ࡴلسموت والارض ويعلم ما تسرون وما تعلنون࣌ والله عليم بذات ࡴلصدور࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-5', 'warsh', 64, 5, 'أَلَمْ يَاتِكُمْ نَبَؤُاْ ࡲ۬لذِينَ كَفَرُواْ مِن قَبْلُ فَذَاقُواْ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'ألم ياتكم نبؤا ࡲلذين كفروا من قبل فذاقوا وبال أمرهم ولهم عذاب ࡰليم࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-6', 'warsh', 64, 6, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّاتِيهِمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرࣱ يَهْدُونَنَا࣌ فَكَفَرُواْ وَتَوَلَّواْ وَّاسْتَغْنَى ࡰ۬للَّهُ࣌ وَاللَّهُ غَنِيٌّ حَمِيدࣱ࣌', 'ذلك بأنه كانت تاتيهم رسلهم بالبينت فقالوا أبشر يهدوننا࣌ فكفروا وتولوا واستغنى ࡰلله࣌ والله غني حميد࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-7', 'warsh', 64, 7, '۞ زَعَمَ ࡰ۬لذِينَ كَفَرُوٓاْ أَن لَّنْ يُّبْعَثُواْ࣌ قُلْ بَلٜىٰ وَرَبِّے لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ࣌ وَذَٰلِكَ عَلَى ࡰ۬للَّهِ يَسِيرࣱ࣌', 'زعم ࡰلذين كفروا أن لن يبعثوا࣌ قل بلى وربے لتبعثن ثم لتنبؤن بما عملتم࣌ وذلك على ࡰلله يسير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-8', 'warsh', 64, 8, 'فَـَٔامِنُواْ بِاللَّهِ وَرَسُولِهِۦ وَالنُّورِ ࡴ۬لذِےٓ أَنزَلْنَا࣌ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرࣱ࣌', 'فامنوا بالله ورسوله والنور ࡴلذے أنزلنا࣌ والله بما تعملون خبير࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-9', 'warsh', 64, 9, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ࡴ۬لْجَمْعِ ذَٰلِكَ يَوْمُ ࡲ۬لتَّغَابُنِ࣌ وَمَنْ يُّومِنۢ بِاللَّهِ وَيَعْمَلْ صَٰلِحاࣰ نُّكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَنُدْخِلْهُ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْعَظِيمُ࣌', 'يوم يجمعكم ليوم ࡴلجمع ذلك يوم ࡲلتغابن࣌ ومن يومن بالله ويعمل صلحا نكفر عنه سياته وندخله جنت تجرے من تحتها ࡰلانهر خلدين فيها أبدا࣌ ذلك ࡰلفوز ࡲلعظيم࣌', NULL, 556, 'local:warsh-text.json'),
  ('warsh-64-10', 'warsh', 64, 10, 'وَالذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لنّٜارِ خَٰلِدِينَ فِيهَا࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'والذين كفروا وكذبوا بايتنا أولئك أصحب ࡲلنار خلدين فيها࣌ وبيس ࡰلمصير࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-11', 'warsh', 64, 11, 'مَآ أَصَابَ مِن مُّصِيبَةٍ ࡴلَّا بِإِذْنِ ࡴ۬للَّهِ࣌ وَمَنْ يُّومِنۢ بِاللَّهِ يَهْدِ قَلْبَهُۥ࣌ وَاللَّهُ بِكُلِّ شَےْءٍ عَلِيمࣱ࣌', 'ما أصاب من مصيبة ࡴلا بإذن ࡴلله࣌ ومن يومن بالله يهد قلبه࣌ والله بكل شےء عليم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-12', 'warsh', 64, 12, 'وَأَطِيعُواْ ࡲ۬للَّهَ وَأَطِيعُواْ ࡲ۬لرَّسُولَ࣌ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ࡰ۬لْبَلَٰغُ ࡲ۬لْمُبِينُ࣌', 'وأطيعوا ࡲلله وأطيعوا ࡲلرسول࣌ فإن توليتم فإنما على رسولنا ࡰلبلغ ࡲلمبين࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-13', 'warsh', 64, 13, 'ࡲ۬للَّهُ لَآ إِلَٰهَ إِلَّا هُوَ࣌ وَعَلَى ࡰ۬للَّهِ فَلْيَتَوَكَّلِ ࡴ۬لْمُومِنُونَ࣌', 'ࡲلله لا إله إلا هو࣌ وعلى ࡰلله فليتوكل ࡴلمومنون࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-14', 'warsh', 64, 14, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُوٓاْ إِنَّ مِنَ ࡰزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوّاࣰ لَّكُمْ فَاحْذَرُوهُمْ࣌ وَإِن تَعْفُواْ وَتَصْفَحُواْ وَتَغْفِرُواْ فَإِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمٌ࣌', 'يأيها ࡰلذين ءامنوا إن من ࡰزوجكم وأولدكم عدوا لكم فاحذروهم࣌ وإن تعفوا وتصفحوا وتغفروا فإن ࡰلله غفور رحيم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-15', 'warsh', 64, 15, 'ࡴنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةࣱ࣌ وَاللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمࣱ࣌', 'ࡴنما أمولكم وأولدكم فتنة࣌ والله عنده أجر عظيم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-16', 'warsh', 64, 16, 'فَاتَّقُواْ ࡲ۬للَّهَ مَا ࡰٜسْتَطَعْتُمْ وَاسْمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيْراࣰ لِّأَنفُسِكُمْ࣌ وَمَنْ يُّوقَ شُحَّ نَفْسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْمُفْلِحُونَ࣌', 'فاتقوا ࡲلله ما ࡰستطعتم واسمعوا وأطيعوا وأنفقوا خيرا لأنفسكم࣌ ومن يوق شح نفسه فأولئك هم ࡲلمفلحون࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-17', 'warsh', 64, 17, 'إِن تُقْرِضُواْ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ࣌ وَاللَّهُ شَكُورٌ حَلِيمٌ࣌', 'إن تقرضوا ࡲلله قرضا حسنا يضعفه لكم ويغفر لكم࣌ والله شكور حليم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-64-18', 'warsh', 64, 18, 'عَٰلِمُ ࡲ۬لْغَيْبِ وَالشَّهَٰدَةِ࣌ ࡴ۬لْعَزِيزُ ࡲ۬لْحَكِيمُ࣌', 'علم ࡲلغيب والشهدة࣌ ࡴلعزيز ࡲلحكيم࣌', NULL, 557, 'local:warsh-text.json'),
  ('warsh-65-1', 'warsh', 65, 1, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ ࡹِذَا طَلَّقْتُمُ ࡲ۬لنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُواْ ࡲ۬لْعِدَّةَ࣌ وَاتَّقُواْ ࡲ۬للَّهَ رَبَّكُمْ࣌ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ࣌ وَلَا يَخْرُجْنَ إِلَّآ أَنْ يَّاتِينَ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲ࣌ وَتِلْكَ حُدُودُ ࡲ۬للَّهِ࣌ وَمَنْ يَّتَعَدَّ حُدُودَ ࡰ۬للَّهِ فَقَد ظَّلَمَ نَفْسَهُۥ࣌ لَا تَدْرِے لَعَلَّ ࡰ۬للَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْراࣰ࣌', 'يأيها‏ ࡰلنبےء ࡹذا طلقتم ࡲلنساء فطلقوهن لعدتهن وأحصوا ࡲلعدة࣌ واتقوا ࡲلله ربكم࣌ لا تخرجوهن من بيوتهن࣌ ولا يخرجن إلا أن ياتين بفحشة مبينة࣌ وتلك حدود ࡲلله࣌ ومن يتعد حدود ࡰلله فقد ظلم نفسه࣌ لا تدرے لعل ࡰلله يحدث بعد ذلك أمرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-2', 'warsh', 65, 2, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ ࡰوْ فَارِقُوهُنَّ بِمَعْرُوفࣲ࣌ وَأَشْهِدُواْ ذَوَےْ عَدْلࣲ مِّنكُمْ࣌ وَأَقِيمُواْ ࡲ۬لشَّهَٰدَةَ لِلهِ࣌ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُومِنُ بِاللَّهِ وَالْيَوْمِ ࡴ۬لَاخِرِ࣌ وَمَنْ يَّتَّقِ ࡴ۬للَّهَ يَجْعَل لَّهُۥ مَخْرَجاࣰ', 'فإذا بلغن أجلهن فأمسكوهن بمعروف ࡰو فارقوهن بمعروف࣌ وأشهدوا ذوے عدل منكم࣌ وأقيموا ࡲلشهدة لله࣌ ذلكم يوعظ به من كان يومن بالله واليوم ࡴلاخر࣌ ومن يتق ࡴلله يجعل له مخرجا', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-3', 'warsh', 65, 3, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ࣌ وَمَنْ يَّتَوَكَّلْ عَلَى ࡰ۬للَّهِ فَهُوَ حَسْبُهُۥٓ࣌ إِنَّ ࡰ۬للَّهَ بَٰلِغٌ ࡰمْرَهُۥ࣌ قَدْ جَعَلَ ࡰ۬للَّهُ لِكُلِّ شَےْءࣲ قَدْراࣰ࣌', 'ويرزقه من حيث لا يحتسب࣌ ومن يتوكل على ࡰلله فهو حسبه࣌ إن ࡰلله بلغ ࡰمره࣌ قد جعل ࡰلله لكل شےء قدرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-4', 'warsh', 65, 4, 'وَالٜےْ يَئِسْنَ مِنَ ࡰ۬لْمَحِيضِ مِن نِّسَآئِكُمُۥٓ إِنِ ࡴٜرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرࣲ وَالٜےْ لَمْ يَحِضْنَ࣌ وَأُوْلَٰتُ ࡲ۬لَاحْمَالِ أَجَلُهُنَّ أَنْ يَّضَعْنَ حَمْلَهُنَّ࣌ وَمَنْ يَّتَّقِ ࡴ۬للَّهَ يَجْعَل لَّهُۥ مِنَ ࡰمْرِهِۦ يُسْراࣰ࣌', 'والے يئسن من ࡰلمحيض من نسائكم إن ࡴرتبتم فعدتهن ثلثة أشهر والے لم يحضن࣌ وأولت ࡲلاحمال أجلهن أن يضعن حملهن࣌ ومن يتق ࡴلله يجعل له من ࡰمره يسرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-5', 'warsh', 65, 5, 'ذَٰلِكَ أَمْرُ ࡲ۬للَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ࣌ وَمَنْ يَّتَّقِ ࡴ۬للَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْراً࣌', 'ذلك أمر ࡲلله أنزله إليكم࣌ ومن يتق ࡴلله يكفر عنه سياته ويعظم له أجرا࣌', NULL, 558, 'local:warsh-text.json'),
  ('warsh-65-6', 'warsh', 65, 6, 'ࡰسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّنْ وُّجْدِكُمْ࣌ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ عَلَيْهِنَّ࣌ وَإِن كُنَّ أُوْلَٰتِ حَمْلࣲ فَأَنفِقُواْ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ࣌ فَإِنَ ࡰرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَاتَمِرُواْ بَيْنَكُم بِمَعْرُوفࣲ࣌ ۞ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرٜىٰ࣌', 'ࡰسكنوهن من حيث سكنتم من وجدكم࣌ ولا تضاروهن لتضيقوا عليهن࣌ وإن كن أولت حمل فأنفقوا عليهن حتى يضعن حملهن࣌ فإن ࡰرضعن لكم فاتوهن أجورهن واتمروا بينكم بمعروف࣌  وإن تعاسرتم فسترضع له أخرى࣌', NULL, 559, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-65-7', 'warsh', 65, 7, 'لِيُنفِقْ ذُو سَعَةࣲ مِّن سَعَتِهِۦ࣌ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتٜيٰهُ ࡲ۬للَّهُ࣌ لَا يُكَلِّفُ ࡲ۬للَّهُ نَفْساً ࡴلَّا مَآ ءَاتٜيٰهَا࣌ سَيَجْعَلُ ࡲ۬للَّهُ بَعْدَ عُسْرࣲ يُسْراࣰ࣌', 'لينفق ذو سعة من سعته࣌ ومن قدر عليه رزقه فلينفق مما ءاتيه ࡲلله࣌ لا يكلف ࡲلله نفسا ࡴلا ما ءاتيها࣌ سيجعل ࡲلله بعد عسر يسرا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-8', 'warsh', 65, 8, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنَ ࡰمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَاباࣰ شَدِيداࣰ وَعَذَّبْنَٰهَا عَذَاباࣰ نُّكُراࣰ', 'وكأين من قرية عتت عن ࡰمر ربها ورسله فحاسبنها حسابا شديدا وعذبنها عذابا نكرا', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-9', 'warsh', 65, 9, 'فَذَاقَتْ وَبَالَ أَمْرِهَا࣌ وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْراً࣌', 'فذاقت وبال أمرها࣌ وكان عقبة أمرها خسرا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-10', 'warsh', 65, 10, 'ࡰعَدَّ ࡰ۬للَّهُ لَهُمْ عَذَاباࣰ شَدِيداࣰ࣌ فَاتَّقُواْ ࡲ۬للَّهَ يَٰٓأُوْلِے ࡴ۬لَالْبَٰبِ࣌ ࡴ۬لذِينَ ءَامَنُواْ قَدَ ࡰنزَلَ ࡰ۬للَّهُ إِلَيْكُمْ ذِكْراࣰ࣌', 'ࡰعد ࡰلله لهم عذابا شديدا࣌ فاتقوا ࡲلله يأولے ࡴلالبب࣌ ࡴلذين ءامنوا قد ࡰنزل ࡰلله إليكم ذكرا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-11', 'warsh', 65, 11, 'رَّسُولاࣰ يَتْلُواْ عَلَيْكُمُۥٓ ءَايَٰتِ ࡴ۬للَّهِ مُبَيَّنَٰتࣲ لِّيُخْرِجَ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ مِنَ ࡰ۬لظُّلُمَٰتِ إِلَى ࡰ۬لنُّورِ࣌ وَمَنْ يُّومِنۢ بِاللَّهِ وَيَعْمَلْ صَٰلِحاࣰ نُّدْخِلْهُ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ قَدَ ࡰحْسَنَ ࡰ۬للَّهُ لَهُۥ رِزْقاً࣌', 'رسولا يتلوا عليكم ءايت ࡴلله مبينت ليخرج ࡰلذين ءامنوا وعملوا ࡲلصلحت من ࡰلظلمت إلى ࡰلنور࣌ ومن يومن بالله ويعمل صلحا ندخله جنت تجرے من تحتها ࡰلانهر خلدين فيها أبدا قد ࡰحسن ࡰلله له رزقا࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-65-12', 'warsh', 65, 12, 'ࡴ۬للَّهُ ࡲ۬لذِے خَلَقَ سَبْعَ سَمَٰوَٰتࣲ وَمِنَ ࡰ۬لَارْضِ مِثْلَهُنَّ࣌ يَتَنَزَّلُ ࡲ۬لَامْرُ بَيْنَهُنَّ لِتَعْلَمُوٓاْ أَنَّ ࡰ۬للَّهَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ وَأَنَّ ࡰ۬للَّهَ قَدَ ࡰحَاطَ بِكُلِّ شَےْءٍ عِلْماࣰ࣌', 'ࡴلله ࡲلذے خلق سبع سموت ومن ࡰلارض مثلهن࣌ يتنزل ࡲلامر بينهن لتعلموا أن ࡰلله على كل شےء قدير وأن ࡰلله قد ࡰحاط بكل شےء علما࣌', NULL, 559, 'local:warsh-text.json'),
  ('warsh-66-1', 'warsh', 66, 1, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ لِمَ تُحَرِّمُ مَآ أَحَلَّ ࡰ۬للَّهُ لَكَ تَبْتَغِے مَرْضَاتَ أَزْوَٰجِكَ࣌ وَاللَّهُ غَفُورࣱ رَّحِيمࣱ࣌', 'يأيها‏ ࡰلنبےء لم تحرم ما أحل ࡰلله لك تبتغے مرضات أزوجك࣌ والله غفور رحيم࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-2', 'warsh', 66, 2, 'قَدْ فَرَضَ ࡰ۬للَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ࣌ وَاللَّهُ مَوْلٜيٰكُمْ࣌ وَهُوَ ࡰ۬لْعَلِيمُ ࡲ۬لْحَكِيمُ࣌', 'قد فرض ࡰلله لكم تحلة أيمنكم࣌ والله موليكم࣌ وهو ࡰلعليم ࡲلحكيم࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-3', 'warsh', 66, 3, 'وَإِذَ ࡰسَرَّ‏ ࡰ۬لنَّبِےٓءُ ࡹِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثاࣰ࣌ فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ࡲ۬للَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضࣲ࣌ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنَ ࡰنۢبَأَكَ هَٰذَا قَالَ نَبَّأَنِيَ ࡰ۬لْعَلِيمُ ࡲ۬لْخَبِيرُ࣌', 'وإذ ࡰسر‏ ࡰلنبےء ࡹلى بعض أزوجه حديثا࣌ فلما نبأت به وأظهره ࡲلله عليه عرف بعضه وأعرض عن بعض࣌ فلما نبأها به قالت من ࡰنبأك هذا قال نبأني ࡰلعليم ࡲلخبير࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-4', 'warsh', 66, 4, 'إِن تَتُوبَآ إِلَى ࡰ۬للَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا࣌ وَإِن تَظَّٰهَرَا عَلَيْهِ فَإِنَّ ࡰ۬للَّهَ هُوَ مَوْلٜيٰهُ وَجِبْرِيلُ وَصَٰلِحُ ࡲ۬لْمُومِنِينَ࣌ وَالْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ࣌', 'إن تتوبا إلى ࡰلله فقد صغت قلوبكما࣌ وإن تظهرا عليه فإن ࡰلله هو موليه وجبريل وصلح ࡲلمومنين࣌ والملئكة بعد ذلك ظهير࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-5', 'warsh', 66, 5, 'عَسٜىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَنْ يُّبَدِّلَهُۥٓ أَزْوَٰجاً خَيْراࣰ مِّنكُنَّ مُسْلِمَٰتࣲ مُّومِنَٰتࣲ قَٰنِتَٰتࣲ تَٰٓئِبَٰتٍ عَٰبِدَٰتࣲ سَٰٓئِحَٰتࣲ ثَيِّبَٰتࣲ وَأَبْكَاراࣰ࣌', 'عسى ربه إن طلقكن أن يبدله أزوجا خيرا منكن مسلمت مومنت قنتت تئبت عبدت سئحت ثيبت وأبكارا࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-6', 'warsh', 66, 6, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمْ وَأَهْلِيكُمْ نَاراࣰ وَقُودُهَا ࡰ۬لنَّاسُ وَالْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَٰظࣱ شِدَادࣱ لَّا يَعْصُونَ ࡰ۬للَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُومَرُونَ࣌', 'يأيها ࡰلذين ءامنوا قوا أنفسكم وأهليكم نارا وقودها ࡰلناس والحجارة عليها ملئكة غلظ شداد لا يعصون ࡰلله ما أمرهم ويفعلون ما يومرون࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-7', 'warsh', 66, 7, 'يَٰٓأَيُّهَا ࡰ۬لذِينَ كَفَرُواْ لَا تَعْتَذِرُواْ ࡲ۬لْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ࣌', 'يأيها ࡰلذين كفروا لا تعتذروا ࡲليوم إنما تجزون ما كنتم تعملون࣌', NULL, 560, 'local:warsh-text.json'),
  ('warsh-66-8', 'warsh', 66, 8, '۞ يَٰٓأَيُّهَا ࡰ۬لذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ࡰ۬للَّهِ تَوْبَةࣰ نَّصُوحاً عَسٜىٰ رَبُّكُمُۥٓ أَنْ يُّكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ يَوْمَ لَا يُخْزِے ࡴ۬للَّهُ ࡲ۬لنَّبِےٓءَ وَالذِينَ ءَامَنُواْ مَعَهُۥ نُورُهُمْ يَسْعٜىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ࣌ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَآ࣌ إِنَّكَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرࣱ࣌', 'يأيها ࡰلذين ءامنوا توبوا إلى ࡰلله توبة نصوحا عسى ربكم أن يكفر عنكم سياتكم ويدخلكم جنت تجرے من تحتها ࡰلانهر يوم لا يخزے ࡴلله ࡲلنبےء والذين ءامنوا معه نورهم يسعى بين أيديهم وبأيمنهم࣌ يقولون ربنا أتمم لنا نورنا واغفر لنا࣌ إنك على كل شےء قدير࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-9', 'warsh', 66, 9, 'يَٰٓأَيُّهَا‏ ࡰ۬لنَّبِےٓءُ جَٰهِدِ ࡴ۬لْكُفَّارَ وَالْمُنَٰفِقِينَ وَاغْلُظْ عَلَيْهِمْ࣌ وَمَأْوٜيٰهُمْ جَهَنَّمُ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'يأيها‏ ࡰلنبےء جهد ࡴلكفار والمنفقين واغلظ عليهم࣌ ومأويهم جهنم࣌ وبيس ࡰلمصير࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-10', 'warsh', 66, 10, 'ضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ لِّلذِينَ كَفَرُواْ ࡲٜمْرَأَتَ نُوحࣲ وَامْرَأَتَ لُوطࣲ࣌ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ فَخَانَتَٰهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ࡰ۬للَّهِ شَيْـٔاࣰ࣌ وَقِيلَ ࡸَدْخُلَا ࡰ۬لنَّارَ مَعَ ࡰ۬لدَّٰخِلِينَ࣌', 'ضرب ࡰلله مثلا للذين كفروا ࡲمرأت نوح وامرأت لوط࣌ كانتا تحت عبدين من عبادنا صالحين فخانتهما فلم يغنيا عنهما من ࡰلله شيا࣌ وقيل ࡸدخلا ࡰلنار مع ࡰلدخلين࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-11', 'warsh', 66, 11, 'وَضَرَبَ ࡰ۬للَّهُ مَثَلاࣰ لِّلذِينَ ءَامَنُواْ ࡲٜمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ࡴٜبْنِ لِے عِندَكَ بَيْتاࣰ فِے ࡴ۬لْجَنَّةِ وَنَجِّنِے مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِے مِنَ ࡰ۬لْقَوْمِ ࡴ۬لظَّٰلِمِينَ࣌', 'وضرب ࡰلله مثلا للذين ءامنوا ࡲمرأت فرعون إذ قالت رب ࡴبن لے عندك بيتا فے ࡴلجنة ونجنے من فرعون وعمله ونجنے من ࡰلقوم ࡴلظلمين࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-66-12', 'warsh', 66, 12, 'وَمَرْيَمَ ࡰٜبْنَتَ عِمْرَٰنَ ࡰ۬لتِےٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكِتَٰبِهِۦ وَكَانَتْ مِنَ ࡰ۬لْقَٰنِتِينَ࣌', 'ومريم ࡰبنت عمرن ࡰلتے أحصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبه وكانت من ࡰلقنتين࣌', NULL, 561, 'local:warsh-text.json'),
  ('warsh-67-1', 'warsh', 67, 1, 'تَبَٰرَكَ ࡰ۬لذِے بِيَدِهِ ࡴ۬لْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَےْءࣲ قَدِيرٌ࣌', 'تبرك ࡰلذے بيده ࡴلملك وهو على كل شےء قدير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-2', 'warsh', 67, 2, 'ࡴ۬لذِے خَلَقَ ࡰ۬لْمَوْتَ وَالْحَيَوٰةَ لِيَبْلُوَكُمُۥٓ أَيُّكُمُۥٓ أَحْسَنُ عَمَلاࣰ࣌ وَهُوَ ࡰ۬لْعَزِيزُ ࡲ۬لْغَفُورُ࣌', 'ࡴلذے خلق ࡰلموت والحيوة ليبلوكم أيكم أحسن عملا࣌ وهو ࡰلعزيز ࡲلغفور࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-3', 'warsh', 67, 3, 'ࡲ۬لذِے خَلَقَ سَبْعَ سَمَٰوَٰتࣲ طِبَاقاࣰ࣌ مَّا تَرٜىٰ فِے خَلْقِ ࡴ۬لرَّحْمَٰنِ مِن تَفَٰوُتࣲ࣌ فَارْجِعِ ࡴ۬لْبَصَرَ هَلْ تَرٜىٰ مِن فُطُورࣲ࣌', 'ࡲلذے خلق سبع سموت طباقا࣌ ما ترى فے خلق ࡴلرحمن من تفوت࣌ فارجع ࡴلبصر هل ترى من فطور࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-4', 'warsh', 67, 4, 'ثُمَّ ࡰٜرْجِعِ ࡴ۬لْبَصَرَ كَرَّتَيْنِ يَنقَلِبِ ࡴلَيْكَ ࡰ۬لْبَصَرُ خَاسِئاࣰ وَهُوَ حَسِيرࣱ࣌', 'ثم ࡰرجع ࡴلبصر كرتين ينقلب ࡴليك ࡰلبصر خاسئا وهو حسير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-5', 'warsh', 67, 5, 'وَلَقَدْ زَيَّنَّا ࡰ۬لسَّمَآءَ ࡰ۬لدُّنْيٜا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُوماࣰ لِّلشَّيَٰطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ ࡰ۬لسَّعِيرِ࣌', 'ولقد زينا ࡰلسماء ࡰلدنيا بمصبيح وجعلنها رجوما للشيطين وأعتدنا لهم عذاب ࡰلسعير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-6', 'warsh', 67, 6, 'وَلِلذِينَ كَفَرُواْ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ࣌ وَبِيسَ ࡰ۬لْمَصِيرُ࣌', 'وللذين كفروا بربهم عذاب جهنم࣌ وبيس ࡰلمصير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-7', 'warsh', 67, 7, 'إِذَآ أُلْقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقاࣰ وَهِيَ تَفُورُ', 'إذا ألقوا فيها سمعوا لها شهيقا وهي تفور', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-8', 'warsh', 67, 8, 'تَكَادُ تَمَيَّزُ مِنَ ࡰ۬لْغَيْظِ࣌ كُلَّمَآ أُلْقِيَ فِيهَا فَوْجࣱ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَاتِكُمْ نَذِيرࣱ࣌', 'تكاد تميز من ࡰلغيظ࣌ كلما ألقي فيها فوج سألهم خزنتها ألم ياتكم نذير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-9', 'warsh', 67, 9, 'قَالُواْ بَلٜىٰ قَدْ جَآءَنَا نَذِيرࣱ', 'قالوا بلى قد جاءنا نذير', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-10', 'warsh', 67, 10, 'فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ࡰ۬للَّهُ مِن شَےْءٍ ࡴنَ ࡰنتُمُۥٓ إِلَّا فِے ضَلَٰلࣲ كَبِيرࣲ࣌', 'فكذبنا وقلنا ما نزل ࡰلله من شےء ࡴن ࡰنتم إلا فے ضلل كبير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-11', 'warsh', 67, 11, 'وَقَالُواْ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِےٓ أَصْحَٰبِ ࡴ۬لسَّعِيرِ࣌', 'وقالوا لو كنا نسمع أو نعقل ما كنا فے أصحب ࡴلسعير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-12', 'warsh', 67, 12, 'فَاعْتَرَفُواْ بِذَنۢبِهِمْ࣌ فَسُحْقاࣰ لِّأَصْحَٰبِ ࡴ۬لسَّعِيرِ࣌', 'فاعترفوا بذنبهم࣌ فسحقا لأصحب ࡴلسعير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-13', 'warsh', 67, 13, 'إِنَّ ࡰ۬لذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ لَهُم مَّغْفِرَةࣱ وَأَجْرࣱ كَبِيرࣱ࣌', 'إن ࡰلذين يخشون ربهم بالغيب لهم مغفرة وأجر كبير࣌', NULL, 562, 'local:warsh-text.json'),
  ('warsh-67-14', 'warsh', 67, 14, 'وَأَسِرُّواْ قَوْلَكُمُۥٓ أَوِ ࡴٜجْهَرُواْ بِهِۦٓ࣌ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ࡴ۬لصُّدُورِ࣌', 'وأسروا قولكم أو ࡴجهروا به࣌ إنه عليم بذات ࡴلصدور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-15', 'warsh', 67, 15, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ࡰ۬للَّطِيفُ ࡲ۬لْخَبِيرُ࣌', 'ألا يعلم من خلق وهو ࡰللطيف ࡲلخبير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-16', 'warsh', 67, 16, 'هُوَ ࡰ۬لذِے جَعَلَ لَكُمُ ࡲ۬لَارْضَ ذَلُولاࣰ فَامْشُواْ فِے مَنَاكِبِهَا وَكُلُواْ مِن رِّزْقِهِۦ࣌ وَإِلَيْهِ ࡴ۬لنُّشُورُ࣌', 'هو ࡰلذے جعل لكم ࡲلارض ذلولا فامشوا فے مناكبها وكلوا من رزقه࣌ وإليه ࡴلنشور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-17', 'warsh', 67, 17, 'ءَامِنتُم مَّن فِے ࡴ۬لسَّمَآءِ ࡶَنْ يَّخْسِفَ بِكُمُ ࡲ۬لَارْضَ فَإِذَا هِيَ تَمُورُ࣌', 'ءامنتم من فے ࡴلسماء ࡶن يخسف بكم ࡲلارض فإذا هي تمور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-18', 'warsh', 67, 18, 'أَمَ ࡰمِنتُم مَّن فِے ࡴ۬لسَّمَآءِ ࡶَنْ يُّرْسِلَ عَلَيْكُمْ حَاصِباࣰ࣌ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِۦ࣌', 'أم ࡰمنتم من فے ࡴلسماء ࡶن يرسل عليكم حاصبا࣌ فستعلمون كيف نذير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-19', 'warsh', 67, 19, 'وَلَقَدْ كَذَّبَ ࡰ۬لذِينَ مِن قَبْلِهِمْ࣌ فَكَيْفَ كَانَ نَكِيرِۦٓ࣌', 'ولقد كذب ࡰلذين من قبلهم࣌ فكيف كان نكير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-20', 'warsh', 67, 20, '۞ أَوَلَمْ يَرَوِاْ ࡴلَى ࡰ۬لطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتࣲ وَيَقْبِضْنَ࣌ مَا يُمْسِكُهُنَّ إِلَّا ࡰ۬لرَّحْمَٰنُ࣌ إِنَّهُۥ بِكُلِّ شَےْءِۢ بَصِيرٌ࣌', 'أولم يروا ࡴلى ࡰلطير فوقهم صفت ويقبضن࣌ ما يمسكهن إلا ࡰلرحمن࣌ إنه بكل شےء بصير࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-21', 'warsh', 67, 21, 'ࡰمَّنْ هَٰذَا ࡰ۬لذِے هُوَ جُندࣱ لَّكُمْ يَنصُرُكُم مِّن دُونِ ࡴ۬لرَّحْمَٰنِ࣌ إِنِ ࡴ۬لْكَٰفِرُونَ إِلَّا فِے غُرُورٍ࣌', 'ࡰمن هذا ࡰلذے هو جند لكم ينصركم من دون ࡴلرحمن࣌ إن ࡴلكفرون إلا فے غرور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-22', 'warsh', 67, 22, 'ࡰمَّنْ هَٰذَا ࡰ۬لذِے يَرْزُقُكُمُۥٓ إِنَ ࡰمْسَكَ رِزْقَهُۥ࣌ بَل لَّجُّواْ فِے عُتُوࣲّ وَنُفُورٍ࣌', 'ࡰمن هذا ࡰلذے يرزقكم إن ࡰمسك رزقه࣌ بل لجوا فے عتو ونفور࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-23', 'warsh', 67, 23, 'ࡰفَمَنْ يَّمْشِے مُكِبّاً عَلَىٰ وَجْهِهِۦٓ أَهْدٜىٰٓ أَمَّنْ يَّمْشِے سَوِيّاً عَلَىٰ صِرَٰطࣲ مُّسْتَقِيمࣲ࣌', 'ࡰفمن يمشے مكبا على وجهه أهدى أمن يمشے سويا على صرط مستقيم࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-24', 'warsh', 67, 24, 'قُلْ هُوَ ࡰ۬لذِےٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ࡲ۬لسَّمْعَ وَالَابْصَٰرَ وَالَافْـِٕدَةَ࣌ قَلِيلاࣰ مَّا تَشْكُرُونَ࣌', 'قل هو ࡰلذے أنشأكم وجعل لكم ࡲلسمع والابصر والافدة࣌ قليلا ما تشكرون࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-25', 'warsh', 67, 25, 'قُلْ هُوَ ࡰ۬لذِے ذَرَأَكُمْ فِے ࡴ۬لَارْضِ وَإِلَيْهِ تُحْشَرُونَ࣌', 'قل هو ࡰلذے ذرأكم فے ࡴلارض وإليه تحشرون࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-26', 'warsh', 67, 26, 'وَيَقُولُونَ مَتٜىٰ هَٰذَا ࡰ۬لْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ࣌', 'ويقولون متى هذا ࡰلوعد إن كنتم صدقين࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-27', 'warsh', 67, 27, 'قُلِ ࡴنَّمَا ࡰ۬لْعِلْمُ عِندَ ࡰ۬للَّهِ وَإِنَّمَآ أَنَا نَذِيرࣱ مُّبِينࣱ࣌', 'قل ࡴنما ࡰلعلم عند ࡰلله وإنما أنا نذير مبين࣌', NULL, 563, 'local:warsh-text.json'),
  ('warsh-67-28', 'warsh', 67, 28, 'فَلَمَّا رَأَوْهُ زُلْفَةࣰ س۬يٓـَٔتْ وُجُوهُ ࡲ۬لذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ࡰ۬لذِے كُنتُم بِهِۦ تَدَّعُونَ࣌', 'فلما رأوه زلفة سيت وجوه ࡲلذين كفروا وقيل هذا ࡰلذے كنتم به تدعون࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-67-29', 'warsh', 67, 29, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِنَ ࡰهْلَكَنِيَ ࡰ۬للَّهُ وَمَن مَّعِيَ أَوْ رَحِمَنَا فَمَنْ يُّجِيرُ ࡲ۬لْكٜـٰفِرِينَ مِنْ عَذَابٍ ࡰلِيمࣲ࣌', 'قل ࡰريتم إن ࡰهلكني ࡰلله ومن معي أو رحمنا فمن يجير ࡲلكفرين من عذاب ࡰليم࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-67-30', 'warsh', 67, 30, 'قُلْ هُوَ ࡰ۬لرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا࣌ فَسَتَعْلَمُونَ مَنْ هُوَ فِے ضَلَٰلࣲ مُّبِينࣲ࣌', 'قل هو ࡰلرحمن ءامنا به وعليه توكلنا࣌ فستعلمون من هو فے ضلل مبين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-67-31', 'warsh', 67, 31, 'قُلَ ࡰرَٰٓيْتُمُۥٓ إِنَ ࡰصْبَحَ مَآؤُكُمْ غَوْراࣰ فَمَنْ يَّاتِيكُم بِمَآءࣲ مَّعِينࣲ࣌', 'قل ࡰريتم إن ࡰصبح ماؤكم غورا فمن ياتيكم بماء معين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-1', 'warsh', 68, 1, 'نُّٓ࣌ وَالْقَلَمِ وَمَا يَسْطُرُونَ', 'ن࣌ والقلم وما يسطرون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-2', 'warsh', 68, 2, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونࣲ', 'ما أنت بنعمة ربك بمجنون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-3', 'warsh', 68, 3, 'وَإِنَّ لَكَ لَأَجْراً غَيْرَ مَمْنُونࣲ', 'وإن لك لأجرا غير ممنون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-4', 'warsh', 68, 4, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمࣲ࣌', 'وإنك لعلى خلق عظيم࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-5', 'warsh', 68, 5, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 'فستبصر ويبصرون', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-6', 'warsh', 68, 6, 'بِأَييِّكُمُ ࡲ۬لْمَفْتُونُ࣌', 'بأييكم ࡲلمفتون࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-7', 'warsh', 68, 7, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ࣌ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ࣌', 'إن ربك هو أعلم بمن ضل عن سبيله࣌ وهو أعلم بالمهتدين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-8', 'warsh', 68, 8, 'فَلَا تُطِعِ ࡴ۬لْمُكَذِّبِينَ࣌', 'فلا تطع ࡴلمكذبين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-9', 'warsh', 68, 9, 'وَدُّواْ لَوْ تُدْهِنُ فَيُدْهِنُونَ࣌', 'ودوا لو تدهن فيدهنون࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-10', 'warsh', 68, 10, 'وَلَا تُطِعْ كُلَّ حَلَّٰفࣲ مَّهِينٍ', 'ولا تطع كل حلف مهين', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-11', 'warsh', 68, 11, 'هَمَّازࣲ مَّشَّآءِۢ بِنَمِيمࣲ', 'هماز مشاء بنميم', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-12', 'warsh', 68, 12, 'مَّنَّاعࣲ لِّلْخَيْرِ مُعْتَدٍ ࡰثِيمٍ', 'مناع للخير معتد ࡰثيم', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-13', 'warsh', 68, 13, 'عُتُلِّۢ بَعْدَ ذَٰلِكَ زَنِيمٍ', 'عتل بعد ذلك زنيم', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-14', 'warsh', 68, 14, 'ࡰن كَانَ ذَا مَالࣲ وَبَنِينَ', 'ࡰن كان ذا مال وبنين', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-15', 'warsh', 68, 15, 'إِذَا تُتْلٜىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'إذا تتلى عليه ءايتنا قال أسطير ࡲلاولين࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-16', 'warsh', 68, 16, 'سَنَسِمُهُۥ عَلَى ࡰ۬لْخُرْطُومِ࣌', 'سنسمه على ࡰلخرطوم࣌', NULL, 564, 'local:warsh-text.json'),
  ('warsh-68-17', 'warsh', 68, 17, 'إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ࡰ۬لْجَنَّةِ إِذَ ࡰقْسَمُواْ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 'إنا بلونهم كما بلونا أصحب ࡰلجنة إذ ࡰقسموا ليصرمنها مصبحين', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-18', 'warsh', 68, 18, 'وَلَا يَسْتَثْنُونَ࣌', 'ولا يستثنون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-19', 'warsh', 68, 19, '۞ فَطَافَ عَلَيْهَا طَآئِفࣱ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 'فطاف عليها طائف من ربك وهم نائمون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-20', 'warsh', 68, 20, 'فَأَصْبَحَتْ كَالصَّرِيمِ࣌', 'فأصبحت كالصريم࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-21', 'warsh', 68, 21, 'فَتَنَادَوْاْ مُصْبِحِينَ', 'فتنادوا مصبحين', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-22', 'warsh', 68, 22, 'أَنُ ࡲ࢈غْدُواْ عَلَىٰ حَرْثِكُمُۥٓ إِن كُنتُمْ صَٰرِمِينَ࣌', 'أن ࡲ࢈غدوا على حرثكم إن كنتم صرمين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-23', 'warsh', 68, 23, 'فَانطَلَقُواْ وَهُمْ يَتَخَٰفَتُونَ', 'فانطلقوا وهم يتخفتون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-24', 'warsh', 68, 24, 'أَن لَّا يَدْخُلَنَّهَا ࡰ۬لْيَوْمَ عَلَيْكُم مِّسْكِينࣱ࣌', 'أن لا يدخلنها ࡰليوم عليكم مسكين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-25', 'warsh', 68, 25, 'وَغَدَوْاْ عَلَىٰ حَرْدࣲ قَٰدِرِينَ࣌', 'وغدوا على حرد قدرين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-26', 'warsh', 68, 26, 'فَلَمَّا رَأَوْهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ', 'فلما رأوها قالوا إنا لضالون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-27', 'warsh', 68, 27, 'بَلْ نَحْنُ مَحْرُومُونَ࣌', 'بل نحن محرومون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-28', 'warsh', 68, 28, 'قَالَ أَوْسَطُهُمُۥٓ أَلَمَ ࡰقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ࣌', 'قال أوسطهم ألم ࡰقل لكم لولا تسبحون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-29', 'warsh', 68, 29, 'قَالُواْ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ࣌', 'قالوا سبحن ربنا إنا كنا ظلمين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-30', 'warsh', 68, 30, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضࣲ يَتَلَٰوَمُونَ࣌', 'فأقبل بعضهم على بعض يتلومون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-31', 'warsh', 68, 31, 'قَالُواْ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ', 'قالوا يويلنا إنا كنا طغين', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-32', 'warsh', 68, 32, 'عَسٜىٰ رَبُّنَآ أَنْ يُّبَدِّلَنَا خَيْراࣰ مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ࣌', 'عسى ربنا أن يبدلنا خيرا منها إنا إلى ربنا رغبون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-33', 'warsh', 68, 33, 'كَذَٰلِكَ ࡰ۬لْعَذَابُ࣌ وَلَعَذَابُ ࡲ۬لَاخِرَةِ أَكْبَرُ لَوْ كَانُواْ يَعْلَمُونَ࣌', 'كذلك ࡰلعذاب࣌ ولعذاب ࡲلاخرة أكبر لو كانوا يعلمون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-34', 'warsh', 68, 34, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ࡴ۬لنَّعِيمِ࣌', 'إن للمتقين عند ربهم جنت ࡴلنعيم࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-35', 'warsh', 68, 35, 'أَفَنَجْعَلُ ࡲ۬لْمُسْلِمِينَ كَالْمُجْرِمِينَ࣌', 'أفنجعل ࡲلمسلمين كالمجرمين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-36', 'warsh', 68, 36, 'مَا لَكُمْ࣌ كَيْفَ تَحْكُمُونَ࣌', 'ما لكم࣌ كيف تحكمون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-37', 'warsh', 68, 37, 'أَمْ لَكُمْ كِتَٰبࣱ فِيهِ تَدْرُسُونَ', 'أم لكم كتب فيه تدرسون', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-38', 'warsh', 68, 38, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ࣌', 'إن لكم فيه لما تخيرون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-39', 'warsh', 68, 39, 'أَمْ لَكُمُۥٓ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ ࡴلَىٰ يَوْمِ ࡴ۬لْقِيَٰمَةِ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ࣌', 'أم لكم أيمن علينا بلغة ࡴلى يوم ࡴلقيمة إن لكم لما تحكمون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-40', 'warsh', 68, 40, 'سَلْهُمُۥٓ أَيُّهُم بِذَٰلِكَ زَعِيمٌ࣌', 'سلهم أيهم بذلك زعيم࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-41', 'warsh', 68, 41, 'ࡰمْ لَهُمْ شُرَكَآءُ فَلْيَاتُواْ بِشُرَكَآئِهِمُۥٓ إِن كَانُواْ صَٰدِقِينَ࣌', 'ࡰم لهم شركاء فلياتوا بشركائهم إن كانوا صدقين࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-42', 'warsh', 68, 42, 'يَوْمَ يُكْشَفُ عَن سَاقࣲ وَيُدْعَوْنَ إِلَى ࡰ۬لسُّجُودِ فَلَا يَسْتَطِيعُونَ࣌', 'يوم يكشف عن ساق ويدعون إلى ࡰلسجود فلا يستطيعون࣌', NULL, 565, 'local:warsh-text.json'),
  ('warsh-68-43', 'warsh', 68, 43, 'خَٰشِعَةً ࡰبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةࣱ࣌ وَقَدْ كَانُواْ يُدْعَوْنَ إِلَى ࡰ۬لسُّجُودِ وَهُمْ سَٰلِمُونَ࣌', 'خشعة ࡰبصرهم ترهقهم ذلة࣌ وقد كانوا يدعون إلى ࡰلسجود وهم سلمون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-44', 'warsh', 68, 44, 'فَذَرْنِے وَمَنْ يُّكَذِّبُ بِهَٰذَا ࡰ۬لْحَدِيثِ࣌ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'فذرنے ومن يكذب بهذا ࡰلحديث࣌ سنستدرجهم من حيث لا يعلمون', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-45', 'warsh', 68, 45, 'وَأُمْلِے لَهُمُۥٓ࣌ إِنَّ كَيْدِے مَتِينٌ࣌', 'وأملے لهم࣌ إن كيدے متين࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-46', 'warsh', 68, 46, 'ࡰمْ تَسْـَٔلُهُمُۥٓ أَجْراࣰ فَهُم مِّن مَّغْرَمࣲ مُّثْقَلُونَ࣌', 'ࡰم تسلهم أجرا فهم من مغرم مثقلون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-47', 'warsh', 68, 47, 'أَمْ عِندَهُمُ ࡲ۬لْغَيْبُ فَهُمْ يَكْتُبُونَ࣌', 'أم عندهم ࡲلغيب فهم يكتبون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-48', 'warsh', 68, 48, '۞ فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَٰحِبِ ࡴ۬لْحُوتِ إِذْ نَادٜىٰ وَهُوَ مَكْظُومࣱ࣌', 'فاصبر لحكم ربك ولا تكن كصحب ࡴلحوت إذ نادى وهو مكظوم࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-49', 'warsh', 68, 49, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةࣱ مِّن رَّبِّهِۦ لَنُبِذَ بِالْعَرَآءِ وَهُوَ مَذْمُومࣱ࣌', 'لولا أن تدركه نعمة من ربه لنبذ بالعراء وهو مذموم࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-50', 'warsh', 68, 50, 'فَاجْتَبٜـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ࡰ۬لصَّٰلِحِينَ࣌', 'فاجتبه ربه فجعله من ࡰلصلحين࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-51', 'warsh', 68, 51, 'وَإِنْ يَّكَادُ ࡲ۬لذِينَ كَفَرُواْ لَيَزْلِقُونَكَ بِأَبْصٜـٰرِهِمْ لَمَّا سَمِعُواْ ࡲ۬لذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونࣱ࣌', 'وإن يكاد ࡲلذين كفروا ليزلقونك بأبصرهم لما سمعوا ࡲلذكر ويقولون إنه لمجنون࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-68-52', 'warsh', 68, 52, 'وَمَا هُوَ إِلَّا ذِكْرࣱ لِّلْعَٰلَمِينَ࣌', 'وما هو إلا ذكر للعلمين࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-1', 'warsh', 69, 1, 'ࡰ۬لْحَآقَّةُ مَا ࡰ۬لْحَآقَّةُ࣌', 'ࡰلحاقة ما ࡰلحاقة࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-2', 'warsh', 69, 2, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْحَآقَّةُ࣌', 'وما أدريك ما ࡰلحاقة࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-3', 'warsh', 69, 3, 'كَذَّبَتْ ثَمُودُ وَعَادُۢ بِالْقَارِعَةِ࣌', 'كذبت ثمود وعاد بالقارعة࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-4', 'warsh', 69, 4, 'فَأَمَّا ثَمُودُ فَأُهْلِكُواْ بِالطَّاغِيَةِ࣌', 'فأما ثمود فأهلكوا بالطاغية࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-5', 'warsh', 69, 5, 'وَأَمَّا عَادࣱ فَأُهْلِكُواْ بِرِيحࣲ صَرْصَرٍ عَاتِيَةࣲ', 'وأما عاد فأهلكوا بريح صرصر عاتية', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-6', 'warsh', 69, 6, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالࣲ وَثَمَٰنِيَةَ أَيَّامٍ حُسُوماࣰ࣌ فَتَرَى ࡰ۬لْقَوْمَ فِيهَا صَرْعٜىٰ كَأَنَّهُمُۥٓ أَعْجَازُ نَخْلٍ خَاوِيَةࣲ࣌', 'سخرها عليهم سبع ليال وثمنية أيام حسوما࣌ فترى ࡰلقوم فيها صرعى كأنهم أعجاز نخل خاوية࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-7', 'warsh', 69, 7, 'فَهَلْ تَرٜىٰ لَهُم مِّنۢ بَاقِيَةࣲ࣌', 'فهل ترى لهم من باقية࣌', NULL, 566, 'local:warsh-text.json'),
  ('warsh-69-8', 'warsh', 69, 8, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَالْمُوتَفِكَٰتُ بِالْخَاطِئَةِ', 'وجاء فرعون ومن قبله والموتفكت بالخاطئة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-9', 'warsh', 69, 9, 'فَعَصَوْاْ رَسُولَ رَبِّهِمْ فَأَخَذَهُمُۥٓ أَخْذَةࣰ رَّابِيَةً࣌', 'فعصوا رسول ربهم فأخذهم أخذة رابية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-10', 'warsh', 69, 10, 'ࡴنَّا لَمَّا طَغَا ࡰ۬لْمَآءُ حَمَلْنَٰكُمْ فِے ࡴ۬لْجَارِيَةِ', 'ࡴنا لما طغا ࡰلماء حملنكم فے ࡴلجارية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-11', 'warsh', 69, 11, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةࣰ وَتَعِيَهَآ أُذْنࣱ وَٰعِيَةࣱ࣌', 'لنجعلها لكم تذكرة وتعيها أذن وعية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-12', 'warsh', 69, 12, 'فَإِذَا نُفِخَ فِے ࡴ۬لصُّورِ نَفْخَةࣱ وَٰحِدَةࣱ', 'فإذا نفخ فے ࡴلصور نفخة وحدة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-13', 'warsh', 69, 13, 'وَحُمِلَتِ ࡴ۬لَارْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةࣰ وَٰحِدَةࣰ', 'وحملت ࡴلارض والجبال فدكتا دكة وحدة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-14', 'warsh', 69, 14, 'فَيَوْمَئِذࣲ وَقَعَتِ ࡴ۬لْوَاقِعَةُ', 'فيومئذ وقعت ࡴلواقعة', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-15', 'warsh', 69, 15, 'وَانشَقَّتِ ࡴ۬لسَّمَآءُ فَهِيَ يَوْمَئِذࣲ وَاهِيَةࣱ', 'وانشقت ࡴلسماء فهي يومئذ واهية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-16', 'warsh', 69, 16, 'وَالْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا࣌ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذࣲ ثَمَٰنِيَةࣱ', 'والملك على أرجائها࣌ ويحمل عرش ربك فوقهم يومئذ ثمنية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-17', 'warsh', 69, 17, 'يَوْمَئِذࣲ تُعْرَضُونَ لَا تَخْفٜىٰ مِنكُمْ خَافِيَةࣱ࣌', 'يومئذ تعرضون لا تخفى منكم خافية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-18', 'warsh', 69, 18, '۞ فَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ࡲٜقْرَءُواْ كِتَٰبِيَهْ࣌', 'فأما من ࡳوتي كتبه بيمينه فيقول هاؤم ࡲقرءوا كتبيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-19', 'warsh', 69, 19, 'إِنِّے ظَنَنتُ أَنِّے مُلَٰقٍ حِسَابِيَهْ࣌', 'إنے ظننت أنے ملق حسابيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-20', 'warsh', 69, 20, 'فَهُوَ فِے عِيشَةࣲ رَّاضِيَةࣲ', 'فهو فے عيشة راضية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-21', 'warsh', 69, 21, 'فِے جَنَّةٍ عَالِيَةࣲ', 'فے جنة عالية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-22', 'warsh', 69, 22, 'قُطُوفُهَا دَانِيَةࣱ࣌', 'قطوفها دانية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-23', 'warsh', 69, 23, 'كُلُواْ وَاشْرَبُواْ࣌ هَنِيٓـٔاَۢ بِمَآ أَسْلَفْتُمْ فِے ࡴ۬لَايَّامِ ࡴ۬لْخَالِيَةِ࣌', 'كلوا واشربوا࣌ هنيا بما أسلفتم فے ࡴلايام ࡴلخالية࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-24', 'warsh', 69, 24, 'وَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ', 'وأما من ࡳوتي كتبه بشماله', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-25', 'warsh', 69, 25, 'فَيَقُولُ يَٰلَيْتَنِے لَمُ ࡳوتَ كِتَٰبِيَهْ࣌', 'فيقول يليتنے لم ࡳوت كتبيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-26', 'warsh', 69, 26, 'وَلَمَ ࡰدْرِ مَا حِسَابِيَهْ࣌', 'ولم ࡰدر ما حسابيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-27', 'warsh', 69, 27, 'يَٰلَيْتَهَا كَانَتِ ࡴ۬لْقَاضِيَةَ', 'يليتها كانت ࡴلقاضية', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-28', 'warsh', 69, 28, 'مَآ أَغْنٜىٰ عَنِّے مَالِيَه࣌', 'ما أغنى عنے ماليه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-29', 'warsh', 69, 29, 'هَّلَكَ عَنِّے سُلْطَٰنِيَهْ࣌', 'هلك عنے سلطنيه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-30', 'warsh', 69, 30, 'خُذُوهُ فَغُلُّوهُ', 'خذوه فغلوه', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-31', 'warsh', 69, 31, 'ثُمَّ ࡰ۬لْجَحِيمَ صَلُّوهُ', 'ثم ࡰلجحيم صلوه', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-32', 'warsh', 69, 32, 'ثُمَّ فِے سِلْسِلَةࣲ ذَرْعُهَا سَبْعُونَ ذِرَاعاࣰ فَاسْلُكُوهُ࣌', 'ثم فے سلسلة ذرعها سبعون ذراعا فاسلكوه࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-33', 'warsh', 69, 33, 'إِنَّهُۥ كَانَ لَا يُومِنُ بِاللَّهِ ࡴ۬لْعَظِيمِ', 'إنه كان لا يومن بالله ࡴلعظيم', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-34', 'warsh', 69, 34, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ࡴ۬لْمِسْكِينِ࣌', 'ولا يحض على طعام ࡴلمسكين࣌', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-35', 'warsh', 69, 35, 'فَلَيْسَ لَهُ ࡲ۬لْيَوْمَ هَٰهُنَا حَمِيمࣱ', 'فليس له ࡲليوم ههنا حميم', NULL, 567, 'local:warsh-text.json'),
  ('warsh-69-36', 'warsh', 69, 36, 'وَلَا طَعَامٌ ࡴلَّا مِنْ غِسْلِينࣲ', 'ولا طعام ࡴلا من غسلين', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-37', 'warsh', 69, 37, 'لَّا يَاكُلُهُۥٓ إِلَّا ࡰ۬لْخَٰطِـُٔونَ࣌', 'لا ياكله إلا ࡰلخطون࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-38', 'warsh', 69, 38, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', 'فلا أقسم بما تبصرون', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-39', 'warsh', 69, 39, 'وَمَا لَا تُبْصِرُونَ', 'وما لا تبصرون', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-40', 'warsh', 69, 40, 'إِنَّهُۥ لَقَوْلُ رَسُولࣲ كَرِيمࣲ', 'إنه لقول رسول كريم', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-41', 'warsh', 69, 41, 'وَمَا هُوَ بِقَوْلِ شَاعِرࣲ قَلِيلاࣰ مَّا تُومِنُونَ', 'وما هو بقول شاعر قليلا ما تومنون', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-42', 'warsh', 69, 42, 'وَلَا بِقَوْلِ كَاهِنࣲ࣌ قَلِيلاࣰ مَّا تَذَّكَّرُونَ࣌', 'ولا بقول كاهن࣌ قليلا ما تذكرون࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-43', 'warsh', 69, 43, 'تَنزِيلࣱ مِّن رَّبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'تنزيل من رب ࡴلعلمين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-44', 'warsh', 69, 44, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ࡰ۬لَاقَاوِيلِ', 'ولو تقول علينا بعض ࡰلاقاويل', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-45', 'warsh', 69, 45, 'لَأَخَذْنَا مِنْهُ بِالْيَمِينِ', 'لأخذنا منه باليمين', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-46', 'warsh', 69, 46, 'ثُمَّ لَقَطَعْنَا مِنْهُ ࡲ۬لْوَتِينَ', 'ثم لقطعنا منه ࡲلوتين', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-47', 'warsh', 69, 47, 'فَمَا مِنكُم مِّنَ ࡰحَدٍ عَنْهُ حَٰجِزِينَ࣌', 'فما منكم من ࡰحد عنه حجزين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-48', 'warsh', 69, 48, 'وَإِنَّهُۥ لَتَذْكِرَةࣱ لِّلْمُتَّقِينَ࣌', 'وإنه لتذكرة للمتقين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-49', 'warsh', 69, 49, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ࣌', 'وإنا لنعلم أن منكم مكذبين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-50', 'warsh', 69, 50, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ࡰ۬لْكٜـٰفِرِينَ࣌', 'وإنه لحسرة على ࡰلكفرين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-51', 'warsh', 69, 51, 'وَإِنَّهُۥ لَحَقُّ ࡲ۬لْيَقِينِ࣌', 'وإنه لحق ࡲليقين࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-69-52', 'warsh', 69, 52, 'فَسَبِّحْ بِاسْمِ رَبِّكَ ࡰ۬لْعَظِيمِ࣌', 'فسبح باسم ربك ࡰلعظيم࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-1', 'warsh', 70, 1, 'سَالَ سَآئِلُۢ بِعَذَابࣲ وَاقِعࣲ', 'سال سائل بعذاب واقع', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-2', 'warsh', 70, 2, 'لِّلْكٜـٰفِرِينَ لَيْسَ لَهُۥ دَافِعࣱ', 'للكفرين ليس له دافع', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-3', 'warsh', 70, 3, 'مِّنَ ࡰ۬للَّهِ ذِے ࡴ۬لْمَعَارِجِ࣌', 'من ࡰلله ذے ࡴلمعارج࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-4', 'warsh', 70, 4, 'تَعْرُجُ ࡲ۬لْمَلَٰٓئِكَةُ وَالرُّوحُ إِلَيْهِ فِے يَوْمࣲ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةࣲ࣌', 'تعرج ࡲلملئكة والروح إليه فے يوم كان مقداره خمسين ألف سنة࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-5', 'warsh', 70, 5, 'فَاصْبِرْ صَبْراࣰ جَمِيلاً࣌', 'فاصبر صبرا جميلا࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-6', 'warsh', 70, 6, 'ࡴنَّهُمْ يَرَوْنَهُۥ بَعِيداࣰ', 'ࡴنهم يرونه بعيدا', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-7', 'warsh', 70, 7, 'وَنَرٜيٰهُ قَرِيباࣰ࣌', 'ونريه قريبا࣌', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-8', 'warsh', 70, 8, 'يَوْمَ تَكُونُ ࡲ۬لسَّمَآءُ كَالْمُهْلِ', 'يوم تكون ࡲلسماء كالمهل', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-9', 'warsh', 70, 9, 'وَتَكُونُ ࡲ۬لْجِبَالُ كَالْعِهْنِ', 'وتكون ࡲلجبال كالعهن', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-10', 'warsh', 70, 10, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيماࣰ', 'ولا يسل حميم حميما', NULL, 568, 'local:warsh-text.json'),
  ('warsh-70-11', 'warsh', 70, 11, 'يُبَصَّرُونَهُمْ࣌ يَوَدُّ ࡲ۬لْمُجْرِمُ لَوْ يَفْتَدِے مِنْ عَذَابِ يَوْمَئِذِۢ بِبَنِيهِ', 'يبصرونهم࣌ يود ࡲلمجرم لو يفتدے من عذاب يومئذ ببنيه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-12', 'warsh', 70, 12, 'وَصَٰحِبَتِهِۦ وَأَخِيهِ', 'وصحبته وأخيه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-13', 'warsh', 70, 13, 'وَفَصِيلَتِهِ ࡴ۬لتِے تُـْٔوِيهِ', 'وفصيلته ࡴلتے تويه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-14', 'warsh', 70, 14, 'وَمَن فِے ࡴ۬لَارْضِ جَمِيعاࣰ ثُمَّ يُنجِيهِ', 'ومن فے ࡴلارض جميعا ثم ينجيه', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-15', 'warsh', 70, 15, 'كَلَّآ࣌ إِنَّهَا لَظٜىٰ', 'كلا࣌ إنها لظى', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-16', 'warsh', 70, 16, 'نَزَّاعَةࣱ لِّلشَّوٜىٰ', 'نزاعة للشوى', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-17', 'warsh', 70, 17, 'تَدْعُواْ مَنَ ࡰدْبَرَ وَتَوَلّٜىٰ', 'تدعوا من ࡰدبر وتولى', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-18', 'warsh', 70, 18, 'وَجَمَعَ فَأَوْعٜىٰٓ࣌', 'وجمع فأوعى࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-19', 'warsh', 70, 19, 'إِنَّ ࡰ۬لِانسَٰنَ خُلِقَ هَلُوعاً', 'إن ࡰلانسن خلق هلوعا', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-20', 'warsh', 70, 20, 'ࡴذَا مَسَّهُ ࡲ۬لشَّرُّ جَزُوعاࣰ', 'ࡴذا مسه ࡲلشر جزوعا', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-21', 'warsh', 70, 21, 'وَإِذَا مَسَّهُ ࡲ۬لْخَيْرُ مَنُوعاً', 'وإذا مسه ࡲلخير منوعا', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-22', 'warsh', 70, 22, 'ࡴلَّا ࡰ۬لْمُصَلِّينَ', 'ࡴلا ࡰلمصلين', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-23', 'warsh', 70, 23, 'ࡰ۬لذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ࣌', 'ࡰلذين هم على صلاتهم دائمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-24', 'warsh', 70, 24, 'وَالذِينَ فِےٓ أَمْوَٰلِهِمْ حَقࣱّ مَّعْلُومࣱ', 'والذين فے أمولهم حق معلوم', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-25', 'warsh', 70, 25, 'لِّلسَّآئِلِ وَالْمَحْرُومِ࣌', 'للسائل والمحروم࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-26', 'warsh', 70, 26, 'وَالذِينَ يُصَدِّقُونَ بِيَوْمِ ࡴ۬لدِّينِ࣌', 'والذين يصدقون بيوم ࡴلدين࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-27', 'warsh', 70, 27, 'وَالذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', 'والذين هم من عذاب ربهم مشفقون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-28', 'warsh', 70, 28, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَامُونࣲ࣌', 'إن عذاب ربهم غير مامون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-29', 'warsh', 70, 29, 'وَالذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'والذين هم لفروجهم حفظون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-30', 'warsh', 70, 30, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمُۥٓ أَوْ مَا مَلَكَتَ ࡰيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ࣌', 'إلا على أزوجهم أو ما ملكت ࡰيمنهم فإنهم غير ملومين࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-31', 'warsh', 70, 31, 'فَمَنِ ࡴٜبْتَغٜىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ࡲ۬لْعَادُونَ࣌', 'فمن ࡴبتغى وراء ذلك فأولئك هم ࡲلعادون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-32', 'warsh', 70, 32, 'وَالذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ࣌', 'والذين هم لأمنتهم وعهدهم رعون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-33', 'warsh', 70, 33, 'وَالذِينَ هُم بِشَهَٰدَتِهِمْ قَآئِمُونَ࣌', 'والذين هم بشهدتهم قائمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-34', 'warsh', 70, 34, 'وَالذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'والذين هم على صلاتهم يحافظون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-35', 'warsh', 70, 35, 'أُوْلَٰٓئِكَ فِے جَنَّٰتࣲ مُّكْرَمُونَ࣌', 'أولئك فے جنت مكرمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-36', 'warsh', 70, 36, 'فَمَالِ ࡴ۬لذِينَ كَفَرُواْ قِبَلَكَ مُهْطِعِينَ', 'فمال ࡴلذين كفروا قبلك مهطعين', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-37', 'warsh', 70, 37, 'عَنِ ࡴ۬لْيَمِينِ وَعَنِ ࡴ۬لشِّمَالِ عِزِينَ࣌', 'عن ࡴليمين وعن ࡴلشمال عزين࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-38', 'warsh', 70, 38, 'أَيَطْمَعُ كُلُّ ࡲٜمْرِےࣲٕ مِّنْهُمُۥٓ أَنْ يُّدْخَلَ جَنَّةَ نَعِيمࣲ', 'أيطمع كل ࡲمرے منهم أن يدخل جنة نعيم', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-39', 'warsh', 70, 39, 'كَلَّآ࣌ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ࣌', 'كلا࣌ إنا خلقنهم مما يعلمون࣌', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-40', 'warsh', 70, 40, '۞ فَلَآ أُقْسِمُ بِرَبِّ ࡴ۬لْمَشَٰرِقِ وَالْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ', 'فلا أقسم برب ࡴلمشرق والمغرب إنا لقدرون', NULL, 569, 'local:warsh-text.json'),
  ('warsh-70-41', 'warsh', 70, 41, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْراࣰ مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ࣌', 'على أن نبدل خيرا منهم وما نحن بمسبوقين࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-70-42', 'warsh', 70, 42, 'فَذَرْهُمْ يَخُوضُواْ وَيَلْعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوْمَهُمُ ࡲ۬لذِے يُوعَدُونَ', 'فذرهم يخوضوا ويلعبوا حتى يلقوا يومهم ࡲلذے يوعدون', NULL, 570, 'local:warsh-text.json'),
  ('warsh-70-43', 'warsh', 70, 43, 'يَوْمَ يَخْرُجُونَ مِنَ ࡰ۬لَاجْدَاثِ سِرَاعاࣰ كَأَنَّهُمُۥٓ إِلَىٰ نَصْبࣲ يُوفِضُونَ', 'يوم يخرجون من ࡰلاجداث سراعا كأنهم إلى نصب يوفضون', NULL, 570, 'local:warsh-text.json'),
  ('warsh-70-44', 'warsh', 70, 44, 'خَٰشِعَةً ࡰبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةࣱ࣌ ذَٰلِكَ ࡰ۬لْيَوْمُ ࡲ۬لذِے كَانُواْ يُوعَدُونَ࣌', 'خشعة ࡰبصرهم ترهقهم ذلة࣌ ذلك ࡰليوم ࡲلذے كانوا يوعدون࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-1', 'warsh', 71, 1, 'إِنَّآ أَرْسَلْنَا نُوحاً ࡴلَىٰ قَوْمِهِۦٓ أَنَ ࡰنذِرْ قَوْمَكَ مِن قَبْلِ أَنْ يَّاتِيَهُمْ عَذَابٌ ࡰلِيمࣱ࣌', 'إنا أرسلنا نوحا ࡴلى قومه أن ࡰنذر قومك من قبل أن ياتيهم عذاب ࡰليم࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-2', 'warsh', 71, 2, 'قَالَ يَٰقَوْمِ إِنِّے لَكُمْ نَذِيرࣱ مُّبِينٌ', 'قال يقوم إنے لكم نذير مبين', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-3', 'warsh', 71, 3, 'ࡰنُ ࡲ࢈عْبُدُواْ ࡲ۬للَّهَ وَاتَّقُوهُ وَأَطِيعُونِ', 'ࡰن ࡲ࢈عبدوا ࡲلله واتقوه وأطيعون', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-4', 'warsh', 71, 4, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُوَ۬خِّرْكُمُۥٓ إِلَىٰٓ أَجَلࣲ مُّسَمّىً࣌ ࡴنَّ أَجَلَ ࡰ۬للَّهِ إِذَا جَآءَ لَا يُوَ۬خَّرُ لَوْ كُنتُمْ تَعْلَمُونَ࣌', 'يغفر لكم من ذنوبكم ويوخركم إلى أجل مسمى࣌ ࡴن أجل ࡰلله إذا جاء لا يوخر لو كنتم تعلمون࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-5', 'warsh', 71, 5, 'قَالَ رَبِّ إِنِّے دَعَوْتُ قَوْمِے لَيْلاࣰ وَنَهَاراࣰ', 'قال رب إنے دعوت قومے ليلا ونهارا', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-6', 'warsh', 71, 6, 'فَلَمْ يَزِدْهُمْ دُعَآءِيَ إِلَّا فِرَاراࣰ࣌', 'فلم يزدهم دعاءي إلا فرارا࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-7', 'warsh', 71, 7, 'وَإِنِّے كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓاْ أَصَٰبِعَهُمْ فِےٓ ءَاذَانِهِمْ وَاسْتَغْشَوْاْ ثِيَابَهُمْ وَأَصَرُّواْ وَاسْتَكْبَرُواْ ࡲٜسْتِكْبَاراࣰ࣌', 'وإنے كلما دعوتهم لتغفر لهم جعلوا أصبعهم فے ءاذانهم واستغشوا ثيابهم وأصروا واستكبروا ࡲستكبارا࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-8', 'warsh', 71, 8, 'ثُمَّ إِنِّے دَعَوْتُهُمْ جِهَاراࣰ࣌', 'ثم إنے دعوتهم جهارا࣌', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-9', 'warsh', 71, 9, 'ثُمَّ إِنِّيَ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمُۥٓ إِسْرَاراࣰ', 'ثم إني أعلنت لهم وأسررت لهم إسرارا', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-10', 'warsh', 71, 10, 'فَقُلْتُ ࡲٜسْتَغْفِرُواْ رَبَّكُمُۥٓ إِنَّهُۥ كَانَ غَفَّاراࣰ', 'فقلت ࡲستغفروا ربكم إنه كان غفارا', NULL, 570, 'local:warsh-text.json'),
  ('warsh-71-11', 'warsh', 71, 11, 'يُرْسِلِ ࡴ۬لسَّمَآءَ عَلَيْكُم مِّدْرَاراࣰ', 'يرسل ࡴلسماء عليكم مدرارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-12', 'warsh', 71, 12, 'وَيُمْدِدْكُم بِأَمْوَٰلࣲ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّٰتࣲ وَيَجْعَل لَّكُمُۥٓ أَنْهَٰراࣰ࣌', 'ويمددكم بأمول وبنين ويجعل لكم جنت ويجعل لكم أنهرا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-13', 'warsh', 71, 13, 'مَّا لَكُمْ لَا تَرْجُونَ لِلهِ وَقَاراࣰ', 'ما لكم لا ترجون لله وقارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-14', 'warsh', 71, 14, 'وَقَدْ خَلَقَكُمُۥٓ أَطْوَاراً࣌', 'وقد خلقكم أطوارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-15', 'warsh', 71, 15, '۞ ࡰلَمْ تَرَوْاْ كَيْفَ خَلَقَ ࡰ۬للَّهُ سَبْعَ سَمَٰوَٰتࣲ طِبَاقاࣰ', 'ࡰلم تروا كيف خلق ࡰلله سبع سموت طباقا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-16', 'warsh', 71, 16, 'وَجَعَلَ ࡰ۬لْقَمَرَ فِيهِنَّ نُوراࣰ وَجَعَلَ ࡰ۬لشَّمْسَ سِرَاجاࣰ࣌', 'وجعل ࡰلقمر فيهن نورا وجعل ࡰلشمس سراجا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-17', 'warsh', 71, 17, 'وَاللَّهُ أَنۢبَتَكُم مِّنَ ࡰ۬لَارْضِ نَبَاتاࣰ', 'والله أنبتكم من ࡰلارض نباتا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-18', 'warsh', 71, 18, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمُۥٓ إِخْرَاجاࣰ࣌', 'ثم يعيدكم فيها ويخرجكم إخراجا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-19', 'warsh', 71, 19, 'وَاللَّهُ جَعَلَ لَكُمُ ࡲ۬لَارْضَ بِسَاطاࣰ', 'والله جعل لكم ࡲلارض بساطا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-20', 'warsh', 71, 20, 'لِّتَسْلُكُواْ مِنْهَا سُبُلاࣰ فِجَاجاࣰ࣌', 'لتسلكوا منها سبلا فجاجا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-21', 'warsh', 71, 21, 'قَالَ نُوحࣱ رَّبِّ إِنَّهُمْ عَصَوْنِے وَاتَّبَعُواْ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَاراࣰ', 'قال نوح رب إنهم عصونے واتبعوا من لم يزده ماله وولده إلا خسارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-22', 'warsh', 71, 22, 'وَمَكَرُواْ مَكْراࣰ كُبَّاراࣰ࣌', 'ومكروا مكرا كبارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-23', 'warsh', 71, 23, 'وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وُدّاࣰ وَلَا سُوَاعاࣰ', 'وقالوا لا تذرن ءالهتكم ولا تذرن ودا ولا سواعا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-24', 'warsh', 71, 24, 'وَلَا يَغُوثَ وَيَعُوقَ وَنَسْراࣰ࣌', 'ولا يغوث ويعوق ونسرا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-25', 'warsh', 71, 25, 'وَقَدَ ࡰضَلُّواْ كَثِيراࣰ࣌ وَلَا تَزِدِ ࡴ۬لظَّٰلِمِينَ إِلَّا ضَلَٰلاࣰ࣌', 'وقد ࡰضلوا كثيرا࣌ ولا تزد ࡴلظلمين إلا ضللا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-26', 'warsh', 71, 26, 'مِّمَّا خَطِيٓـَٰٔتِهِمُۥٓ أُغْرِقُواْ فَأُدْخِلُواْ نَاراࣰ', 'مما خطيتهم أغرقوا فأدخلوا نارا', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-27', 'warsh', 71, 27, 'فَلَمْ يَجِدُواْ لَهُم مِّن دُونِ ࡴ۬للَّهِ أَنصَاراࣰ࣌', 'فلم يجدوا لهم من دون ࡴلله أنصارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-28', 'warsh', 71, 28, 'وَقَالَ نُوحࣱ رَّبِّ لَا تَذَرْ عَلَى ࡰ۬لَارْضِ مِنَ ࡰ۬لْكٜـٰفِرِينَ دَيَّاراً࣌', 'وقال نوح رب لا تذر على ࡰلارض من ࡰلكفرين ديارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-29', 'warsh', 71, 29, 'ࡴنَّكَ إِن تَذَرْهُمْ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِراࣰ كَفَّاراࣰ࣌', 'ࡴنك إن تذرهم يضلوا عبادك ولا يلدوا إلا فاجرا كفارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-71-30', 'warsh', 71, 30, 'رَّبِّ ࡴٜغْفِرْ لِے وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيْتِے مُومِناࣰ وَلِلْمُومِنِينَ وَالْمُومِنَٰتِ࣌ وَلَا تَزِدِ ࡴ۬لظَّٰلِمِينَ إِلَّا تَبَاراࣰ࣌', 'رب ࡴغفر لے ولولدي ولمن دخل بيتے مومنا وللمومنين والمومنت࣌ ولا تزد ࡴلظلمين إلا تبارا࣌', NULL, 571, 'local:warsh-text.json'),
  ('warsh-72-1', 'warsh', 72, 1, 'قُلُ ࡳوحِيَ إِلَيَّ أَنَّهُ ࡲٜسْتَمَعَ نَفَرࣱ مِّنَ ࡰ۬لْجِنِّ فَقَالُوٓاْ إِنَّا سَمِعْنَا قُرْءَاناً عَجَباࣰ', 'قل ࡳوحي إلي أنه ࡲستمع نفر من ࡰلجن فقالوا إنا سمعنا قرءانا عجبا', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-2', 'warsh', 72, 2, 'يَهْدِےٓ إِلَى ࡰ۬لرُّشْدِ فَـَٔامَنَّا بِهِۦ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَداࣰ࣌', 'يهدے إلى ࡰلرشد فامنا به ولن نشرك بربنا أحدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-3', 'warsh', 72, 3, 'وَإِنَّهُۥ تَعَٰلٜىٰ جَدُّ رَبِّنَا مَا ࡰٜتَّخَذَ صَٰحِبَةࣰ وَلَا وَلَداࣰ࣌', 'وإنه تعلى جد ربنا ما ࡰتخذ صحبة ولا ولدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-4', 'warsh', 72, 4, 'وَإِنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ࡰ۬للَّهِ شَطَطاࣰ࣌', 'وإنه كان يقول سفيهنا على ࡰلله شططا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-5', 'warsh', 72, 5, 'وَإِنَّا ظَنَنَّآ أَن لَّن تَقُولَ ࡰ۬لِانسُ وَالْجِنُّ عَلَى ࡰ۬للَّهِ كَذِباࣰ࣌', 'وإنا ظننا أن لن تقول ࡰلانس والجن على ࡰلله كذبا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-6', 'warsh', 72, 6, 'وَإِنَّهُۥ كَانَ رِجَالࣱ مِّنَ ࡰ۬لِانسِ يَعُوذُونَ بِرِجَالࣲ مِّنَ ࡰ۬لْجِنِّ فَزَادُوهُمْ رَهَقاࣰ࣌', 'وإنه كان رجال من ࡰلانس يعوذون برجال من ࡰلجن فزادوهم رهقا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-7', 'warsh', 72, 7, 'وَإِنَّهُمْ ظَنُّواْ كَمَا ظَنَنتُمُۥٓ أَن لَّنْ يَّبْعَثَ ࡰ۬للَّهُ أَحَداࣰ࣌', 'وإنهم ظنوا كما ظننتم أن لن يبعث ࡰلله أحدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-8', 'warsh', 72, 8, 'وَإِنَّا لَمَسْنَا ࡰ۬لسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَساࣰ شَدِيداࣰ وَشُهُباࣰ࣌', 'وإنا لمسنا ࡰلسماء فوجدنها ملئت حرسا شديدا وشهبا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-9', 'warsh', 72, 9, 'وَإِنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ فَمَنْ يَّسْتَمِعِ ࡴ۬لَانَ يَجِدْ لَهُۥ شِهَاباࣰ رَّصَداࣰ࣌', 'وإنا كنا نقعد منها مقعد للسمع فمن يستمع ࡴلان يجد له شهابا رصدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-10', 'warsh', 72, 10, 'وَإِنَّا لَا نَدْرِےٓ أَشَرٌّ ࡳرِيدَ بِمَن فِے ࡴ۬لَارْضِ أَمَ ࡰرَادَ بِهِمْ رَبُّهُمْ رَشَداࣰ࣌', 'وإنا لا ندرے أشر ࡳريد بمن فے ࡴلارض أم ࡰراد بهم ربهم رشدا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-11', 'warsh', 72, 11, 'وَإِنَّا مِنَّا ࡰ۬لصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ࣌ كُنَّا طَرَآئِقَ قِدَداࣰ࣌', 'وإنا منا ࡰلصلحون ومنا دون ذلك࣌ كنا طرائق قددا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-12', 'warsh', 72, 12, 'وَإِنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ࡰ۬للَّهَ فِے ࡴ۬لَارْضِ وَلَن نُّعْجِزَهُۥ هَرَباࣰ࣌', 'وإنا ظننا أن لن نعجز ࡰلله فے ࡴلارض ولن نعجزه هربا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-13', 'warsh', 72, 13, 'وَإِنَّا لَمَّا سَمِعْنَا ࡰ۬لْهُدٜىٰٓ ءَامَنَّا بِهِۦ࣌ فَمَنْ يُّومِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْساࣰ وَلَا رَهَقاࣰ࣌', 'وإنا لما سمعنا ࡰلهدى ءامنا به࣌ فمن يومن بربه فلا يخاف بخسا ولا رهقا࣌', NULL, 572, 'local:warsh-text.json'),
  ('warsh-72-14', 'warsh', 72, 14, 'وَإِنَّا مِنَّا ࡰ۬لْمُسْلِمُونَ وَمِنَّا ࡰ۬لْقَٰسِطُونَ࣌ فَمَنَ ࡰسْلَمَ فَأُوْلَٰٓئِكَ تَحَرَّوْاْ رَشَداࣰ࣌', 'وإنا منا ࡰلمسلمون ومنا ࡰلقسطون࣌ فمن ࡰسلم فأولئك تحروا رشدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-15', 'warsh', 72, 15, 'وَأَمَّا ࡰ۬لْقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَباࣰ࣌', 'وأما ࡰلقسطون فكانوا لجهنم حطبا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-16', 'warsh', 72, 16, 'وَأَن لَّوِ ࡴٜسْتَقَٰمُواْ عَلَى ࡰ۬لطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقاࣰ', 'وأن لو ࡴستقموا على ࡰلطريقة لأسقينهم ماء غدقا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-17', 'warsh', 72, 17, 'لِّنَفْتِنَهُمْ فِيهِ࣌ وَمَنْ يُّعْرِضْ عَن ذِكْرِ رَبِّهِۦ نَسْلُكْهُ عَذَاباࣰ صَعَداࣰ࣌', 'لنفتنهم فيه࣌ ومن يعرض عن ذكر ربه نسلكه عذابا صعدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-18', 'warsh', 72, 18, 'وَأَنَّ ࡰ۬لْمَسَٰجِدَ لِلهِ فَلَا تَدْعُواْ مَعَ ࡰ۬للَّهِ أَحَداࣰ࣌', 'وأن ࡰلمسجد لله فلا تدعوا مع ࡰلله أحدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-19', 'warsh', 72, 19, 'وَإِنَّهُۥ لَمَّا قَامَ عَبْدُ ࡲ۬للَّهِ يَدْعُوهُ كَادُواْ يَكُونُونَ عَلَيْهِ لِبَداࣰ࣌', 'وإنه لما قام عبد ࡲلله يدعوه كادوا يكونون عليه لبدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-20', 'warsh', 72, 20, 'قَالَ إِنَّمَآ أَدْعُواْ رَبِّے وَلَآ أُشْرِكُ بِهِۦٓ أَحَداࣰ࣌', 'قال إنما أدعوا ربے ولا أشرك به أحدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-21', 'warsh', 72, 21, 'قُلِ ࡴنِّے لَآ أَمْلِكُ لَكُمْ ضَرّاࣰ وَلَا رَشَداࣰ࣌', 'قل ࡴنے لا أملك لكم ضرا ولا رشدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-22', 'warsh', 72, 22, 'قُلِ ࡴنِّے لَنْ يُّجِيرَنِے مِنَ ࡰ۬للَّهِ أَحَدࣱ وَلَنَ ࡰجِدَ مِن دُونِهِۦ مُلْتَحَداً', 'قل ࡴنے لن يجيرنے من ࡰلله أحد ولن ࡰجد من دونه ملتحدا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-23', 'warsh', 72, 23, 'ࡴلَّا بَلَٰغاࣰ مِّنَ ࡰ۬للَّهِ وَرِسَٰلَٰتِهِۦ࣌ ۞ وَمَنْ يَّعْصِ ࡴ۬للَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَداً࣌', 'ࡴلا بلغا من ࡰلله ورسلته࣌  ومن يعص ࡴلله ورسوله فإن له نار جهنم خلدين فيها أبدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-24', 'warsh', 72, 24, 'حَتَّىٰٓ إِذَا رَأَوْاْ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنَ ࡰضْعَفُ نَاصِراࣰ وَأَقَلُّ عَدَداࣰ࣌', 'حتى إذا رأوا ما يوعدون فسيعلمون من ࡰضعف ناصرا وأقل عددا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-25', 'warsh', 72, 25, 'قُلِ ࡴنَ ࡰدْرِےٓ أَقَرِيبࣱ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّيَ أَمَداً࣌', 'قل ࡴن ࡰدرے أقريب ما توعدون أم يجعل له ربي أمدا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-26', 'warsh', 72, 26, 'عَٰلِمُ ࡲ۬لْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَداً', 'علم ࡲلغيب فلا يظهر على غيبه أحدا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-27', 'warsh', 72, 27, 'ࡴلَّا مَنِ ࡴٜرْتَضٜىٰ مِن رَّسُولࣲ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَداࣰ', 'ࡴلا من ࡴرتضى من رسول فإنه يسلك من بين يديه ومن خلفه رصدا', NULL, 573, 'local:warsh-text.json'),
  ('warsh-72-28', 'warsh', 72, 28, 'لِّيَعْلَمَ أَن قَدَ ࡰبْلَغُواْ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصٜىٰ كُلَّ شَےْءٍ عَدَداࣰ࣌', 'ليعلم أن قد ࡰبلغوا رسلت ربهم وأحاط بما لديهم وأحصى كل شےء عددا࣌', NULL, 573, 'local:warsh-text.json'),
  ('warsh-73-1', 'warsh', 73, 1, 'يَٰٓأَيُّهَا ࡰ۬لْمُزَّمِّلُ قُمِ ࡴ۬ليْلَ إِلَّا قَلِيلاࣰ', 'يأيها ࡰلمزمل قم ࡴليل إلا قليلا', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-2', 'warsh', 73, 2, 'نِّصْفَهُۥٓ أَوُ ࡲ࢈نقُصْ مِنْهُ قَلِيلاً', 'نصفه أو ࡲ࢈نقص منه قليلا', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-3', 'warsh', 73, 3, 'ࡰوْ زِدْ عَلَيْهِ وَرَتِّلِ ࡴ۬لْقُرْءَانَ تَرْتِيلاً࣌', 'ࡰو زد عليه ورتل ࡴلقرءان ترتيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-4', 'warsh', 73, 4, 'ࡴنَّا سَنُلْقِے عَلَيْكَ قَوْلاࣰ ثَقِيلاً࣌', 'ࡴنا سنلقے عليك قولا ثقيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-5', 'warsh', 73, 5, 'ࡴنَّ نَاشِئَةَ ࡰ۬ليْلِ هِيَ أَشَدُّ وَطْـٔاࣰ وَأَقْوَمُ قِيلاً࣌', 'ࡴن ناشئة ࡰليل هي أشد وطا وأقوم قيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-6', 'warsh', 73, 6, 'ࡴنَّ لَكَ فِے ࡴ۬لنَّهٜارِ سَبْحاࣰ طَوِيلاࣰ࣌', 'ࡴن لك فے ࡴلنهار سبحا طويلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-7', 'warsh', 73, 7, 'وَاذْكُرِ ࡴٜسْمَ رَبِّكَ وَتَبَتَّلِ ࡴلَيْهِ تَبْتِيلاࣰ࣌', 'واذكر ࡴسم ربك وتبتل ࡴليه تبتيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-8', 'warsh', 73, 8, 'رَّبُّ ࡲ۬لْمَشْرِقِ وَالْمَغْرِبِ࣌ لَآ إِلَٰهَ إِلَّا هُوَ࣌ فَاتَّخِذْهُ وَكِيلاࣰ࣌', 'رب ࡲلمشرق والمغرب࣌ لا إله إلا هو࣌ فاتخذه وكيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-9', 'warsh', 73, 9, 'وَاصْبِرْ عَلَىٰ مَا يَقُولُونَ࣌ وَاهْجُرْهُمْ هَجْراࣰ جَمِيلاࣰ࣌', 'واصبر على ما يقولون࣌ واهجرهم هجرا جميلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-10', 'warsh', 73, 10, 'وَذَرْنِے وَالْمُكَذِّبِينَ أُوْلِے ࡴ۬لنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلاً࣌', 'وذرنے والمكذبين أولے ࡴلنعمة ومهلهم قليلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-11', 'warsh', 73, 11, 'ࡴنَّ لَدَيْنَآ أَنكَالاࣰ وَجَحِيماࣰ', 'ࡴن لدينا أنكالا وجحيما', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-12', 'warsh', 73, 12, 'وَطَعَاماࣰ ذَا غُصَّةࣲ وَعَذَاباً ࡰلِيماࣰ', 'وطعاما ذا غصة وعذابا ࡰليما', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-13', 'warsh', 73, 13, 'يَوْمَ تَرْجُفُ ࡲ۬لَارْضُ وَالْجِبَالُ وَكَانَتِ ࡴ۬لْجِبَالُ كَثِيباࣰ مَّهِيلاً࣌', 'يوم ترجف ࡲلارض والجبال وكانت ࡴلجبال كثيبا مهيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-14', 'warsh', 73, 14, 'ࡴنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولاࣰ شَٰهِداً عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولاࣰ', 'ࡴنا أرسلنا إليكم رسولا شهدا عليكم كما أرسلنا إلى فرعون رسولا', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-15', 'warsh', 73, 15, 'فَعَصٜىٰ فِرْعَوْنُ ࡲ۬لرَّسُولَ فَأَخَذْنَٰهُ أَخْذاࣰ وَبِيلاࣰ࣌', 'فعصى فرعون ࡲلرسول فأخذنه أخذا وبيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-16', 'warsh', 73, 16, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْماࣰ يَجْعَلُ ࡲ۬لْوِلْدَٰنَ شِيباً ࡴ۬لسَّمَآءُ مُنفَطِرُۢ بِهِۦ࣌ كَانَ وَعْدُهُۥ مَفْعُولاً࣌', 'فكيف تتقون إن كفرتم يوما يجعل ࡲلولدن شيبا ࡴلسماء منفطر به࣌ كان وعده مفعولا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-17', 'warsh', 73, 17, 'ࡴنَّ هَٰذِهِۦ تَذْكِرَةࣱ࣌ فَمَن شَآءَ ࡰٜتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلاً࣌', 'ࡴن هذه تذكرة࣌ فمن شاء ࡰتخذ إلى ربه سبيلا࣌', NULL, 574, 'local:warsh-text.json'),
  ('warsh-73-18', 'warsh', 73, 18, '۞ ࡴنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنٜىٰ مِن ثُلُثَيِ ࡴ۬ليْلِ وَنِصْفِهِۦ وَثُلُثِهِۦ وَطَآئِفَةࣱ مِّنَ ࡰ۬لذِينَ مَعَكَ࣌ وَاللَّهُ يُقَدِّرُ ࡲ۬ليْلَ وَالنَّهَارَ࣌ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ࣌ فَاقْرَءُواْ مَا تَيَسَّرَ مِنَ ࡰ۬لْقُرْءَانِ࣌ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضٜىٰ وَءَاخَرُونَ يَضْرِبُونَ فِے ࡴ۬لَارْضِ يَبْتَغُونَ مِن فَضْلِ ࡴ۬للَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِے سَبِيلِ ࡴ۬للَّهِ࣌ فَاقْرَءُواْ مَا تَيَسَّرَ مِنْهُ࣌ وَأَقِيمُواْ ࡲ۬لصَّلَوٰةَ وَءَاتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَأَقْرِضُواْ ࡲ۬للَّهَ قَرْضاً حَسَناࣰ࣌ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرࣲ تَجِدُوهُ عِندَ ࡰ۬للَّهِ هُوَ خَيْراࣰ وَأَعْظَمَ أَجْراࣰ࣌ وَاسْتَغْفِرُواْ ࡲ۬للَّهَ࣌ إِنَّ ࡰ۬للَّهَ غَفُورࣱ رَّحِيمࣱ࣌', 'ࡴن ربك يعلم أنك تقوم أدنى من ثلثي ࡴليل ونصفه وثلثه وطائفة من ࡰلذين معك࣌ والله يقدر ࡲليل والنهار࣌ علم أن لن تحصوه فتاب عليكم࣌ فاقرءوا ما تيسر من ࡰلقرءان࣌ علم أن سيكون منكم مرضى وءاخرون يضربون فے ࡴلارض يبتغون من فضل ࡴلله وءاخرون يقتلون فے سبيل ࡴلله࣌ فاقرءوا ما تيسر منه࣌ وأقيموا ࡲلصلوة وءاتوا ࡲلزكوة࣌ وأقرضوا ࡲلله قرضا حسنا࣌ وما تقدموا لأنفسكم من خير تجدوه عند ࡰلله هو خيرا وأعظم أجرا࣌ واستغفروا ࡲلله࣌ إن ࡰلله غفور رحيم࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-1', 'warsh', 74, 1, 'يَٰٓأَيُّهَا ࡰ۬لْمُدَّثِّرُ', 'يأيها ࡰلمدثر', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-2', 'warsh', 74, 2, 'قُمْ فَأَنذِرْ࣌', 'قم فأنذر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-3', 'warsh', 74, 3, 'وَرَبَّكَ فَكَبِّرْ࣌', 'وربك فكبر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-4', 'warsh', 74, 4, 'وَثِيَابَكَ فَطَهِّرْ࣌', 'وثيابك فطهر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-5', 'warsh', 74, 5, 'وَالرِّجْزَ فَاهْجُرْ࣌', 'والرجز فاهجر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-6', 'warsh', 74, 6, 'وَلَا تَمْنُن تَسْتَكْثِرُ࣌', 'ولا تمنن تستكثر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-7', 'warsh', 74, 7, 'وَلِرَبِّكَ فَاصْبِرْ࣌', 'ولربك فاصبر࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-8', 'warsh', 74, 8, 'فَإِذَا نُقِرَ فِے ࡴ۬لنَّاقُورِ', 'فإذا نقر فے ࡴلناقور', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-9', 'warsh', 74, 9, 'فَذَٰلِكَ يَوْمَئِذࣲ يَوْمٌ عَسِيرٌ', 'فذلك يومئذ يوم عسير', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-10', 'warsh', 74, 10, 'عَلَى ࡰ۬لْكٜـٰفِرِينَ غَيْرُ يَسِيرࣲ࣌', 'على ࡰلكفرين غير يسير࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-11', 'warsh', 74, 11, 'ذَرْنِے وَمَنْ خَلَقْتُ وَحِيداࣰ', 'ذرنے ومن خلقت وحيدا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-12', 'warsh', 74, 12, 'وَجَعَلْتُ لَهُۥ مَالاࣰ مَّمْدُوداࣰ', 'وجعلت له مالا ممدودا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-13', 'warsh', 74, 13, 'وَبَنِينَ شُهُوداࣰ', 'وبنين شهودا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-14', 'warsh', 74, 14, 'وَمَهَّدتُّ لَهُۥ تَمْهِيداࣰ', 'ومهدت له تمهيدا', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-15', 'warsh', 74, 15, 'ثُمَّ يَطْمَعُ أَنَ ࡰزِيدَ', 'ثم يطمع أن ࡰزيد', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-16', 'warsh', 74, 16, 'كَلَّآ࣌ إِنَّهُۥ كَانَ لِأٓيَٰتِنَا عَنِيداࣰ࣌', 'كلا࣌ إنه كان لأيتنا عنيدا࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-17', 'warsh', 74, 17, 'سَأُرْهِقُهُۥ صَعُوداً࣌', 'سأرهقه صعودا࣌', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-18', 'warsh', 74, 18, 'ࡴنَّهُۥ فَكَّرَ وَقَدَّرَ', 'ࡴنه فكر وقدر', NULL, 575, 'local:warsh-text.json'),
  ('warsh-74-19', 'warsh', 74, 19, 'فَقُتِلَ كَيْفَ قَدَّرَ', 'فقتل كيف قدر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-20', 'warsh', 74, 20, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', 'ثم قتل كيف قدر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-21', 'warsh', 74, 21, 'ثُمَّ نَظَرَ', 'ثم نظر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-22', 'warsh', 74, 22, 'ثُمَّ عَبَسَ وَبَسَرَ', 'ثم عبس وبسر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-23', 'warsh', 74, 23, 'ثُمَّ أَدْبَرَ وَاسْتَكْبَرَ', 'ثم أدبر واستكبر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-24', 'warsh', 74, 24, 'فَقَالَ إِنْ هَٰذَآ إِلَّا سِحْرࣱ يُوثَرُ', 'فقال إن هذا إلا سحر يوثر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-25', 'warsh', 74, 25, 'إِنْ هَٰذَآ إِلَّا قَوْلُ ࡲ۬لْبَشَرِ࣌', 'إن هذا إلا قول ࡲلبشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-26', 'warsh', 74, 26, 'سَأُصْلِيهِ سَقَرَ࣌', 'سأصليه سقر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-27', 'warsh', 74, 27, 'وَمَآ أَدْرٜيٰكَ مَا سَقَرُ࣌', 'وما أدريك ما سقر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-28', 'warsh', 74, 28, 'لَا تُبْقِے وَلَا تَذَرُ࣌', 'لا تبقے ولا تذر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-29', 'warsh', 74, 29, 'لَوَّاحَةࣱ لِّلْبَشَرِ࣌', 'لواحة للبشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-30', 'warsh', 74, 30, 'عَلَيْهَا تِسْعَةَ عَشَرَ࣌', 'عليها تسعة عشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-31', 'warsh', 74, 31, '۞ وَمَا جَعَلْنَآ أَصْحَٰبَ ࡰ۬لنّٜارِ إِلَّا مَلَٰٓئِكَةࣰ࣌ وَمَا جَعَلْنَا عِدَّتَهُمُۥٓ إِلَّا فِتْنَةࣰ لِّلذِينَ كَفَرُواْ لِيَسْتَيْقِنَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ وَيَزْدَادَ ࡰ۬لذِينَ ءَامَنُوٓاْ إِيمَٰناࣰ وَلَا يَرْتَابَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ وَالْمُومِنُونَ وَلِيَقُولَ ࡰ۬لذِينَ فِے قُلُوبِهِم مَّرَضࣱ وَالْكَٰفِرُونَ مَاذَآ أَرَادَ ࡰ۬للَّهُ بِهَٰذَا مَثَلاࣰ࣌ كَذَٰلِكَ يُضِلُّ ࡲ۬للَّهُ مَنْ يَّشَآءُ وَيَهْدِے مَنْ يَّشَآءُ࣌ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ࣌ وَمَا هِيَ إِلَّا ذِكْرٜىٰ لِلْبَشَرِ࣌', 'وما جعلنا أصحب ࡰلنار إلا ملئكة࣌ وما جعلنا عدتهم إلا فتنة للذين كفروا ليستيقن ࡰلذين أوتوا ࡲلكتب ويزداد ࡰلذين ءامنوا إيمنا ولا يرتاب ࡰلذين أوتوا ࡲلكتب والمومنون وليقول ࡰلذين فے قلوبهم مرض والكفرون ماذا أراد ࡰلله بهذا مثلا࣌ كذلك يضل ࡲلله من يشاء ويهدے من يشاء࣌ وما يعلم جنود ربك إلا هو࣌ وما هي إلا ذكرى للبشر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-32', 'warsh', 74, 32, 'كَلَّا وَالْقَمَرِ', 'كلا والقمر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-33', 'warsh', 74, 33, 'وَاليْلِ إِذَ ࡰدْبَرَ', 'واليل إذ ࡰدبر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-34', 'warsh', 74, 34, 'وَالصُّبْحِ إِذَآ أَسْفَرَ', 'والصبح إذا أسفر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-35', 'warsh', 74, 35, 'إِنَّهَا لَإِحْدَى ࡰ۬لْكُبَرِ', 'إنها لإحدى ࡰلكبر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-36', 'warsh', 74, 36, 'نَذِيراࣰ لِّلْبَشَرِ', 'نذيرا للبشر', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-37', 'warsh', 74, 37, 'لِمَن شَآءَ مِنكُمُۥٓ أَنْ يَّتَقَدَّمَ أَوْ يَتَأَخَّرَ࣌', 'لمن شاء منكم أن يتقدم أو يتأخر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-38', 'warsh', 74, 38, 'كُلُّ نَفْسِۢ بِمَا كَسَبَتْ رَهِينَةٌ', 'كل نفس بما كسبت رهينة', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-39', 'warsh', 74, 39, 'ࡴلَّآ أَصْحَٰبَ ࡰ۬لْيَمِينِ࣌', 'ࡴلا أصحب ࡰليمين࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-40', 'warsh', 74, 40, 'فِے جَنَّٰتࣲ يَتَسَآءَلُونَ عَنِ ࡴ۬لْمُجْرِمِينَ', 'فے جنت يتساءلون عن ࡴلمجرمين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-41', 'warsh', 74, 41, 'مَا سَلَكَكُمْ فِے سَقَرَ࣌', 'ما سلككم فے سقر࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-42', 'warsh', 74, 42, 'قَالُواْ لَمْ نَكُ مِنَ ࡰ۬لْمُصَلِّينَ', 'قالوا لم نك من ࡰلمصلين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-43', 'warsh', 74, 43, 'وَلَمْ نَكُ نُطْعِمُ ࡲ۬لْمِسْكِينَ', 'ولم نك نطعم ࡲلمسكين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-44', 'warsh', 74, 44, 'وَكُنَّا نَخُوضُ مَعَ ࡰ۬لْخَآئِضِينَ', 'وكنا نخوض مع ࡰلخائضين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-45', 'warsh', 74, 45, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ࡴ۬لدِّينِ', 'وكنا نكذب بيوم ࡴلدين', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-46', 'warsh', 74, 46, 'حَتَّىٰٓ أَتٜيٰنَا ࡰ۬لْيَقِينُ࣌', 'حتى أتينا ࡰليقين࣌', NULL, 576, 'local:warsh-text.json'),
  ('warsh-74-47', 'warsh', 74, 47, 'فَمَا تَنفَعُهُمْ شَفَٰعَةُ ࡲ۬لشَّٰفِعِينَ࣌', 'فما تنفعهم شفعة ࡲلشفعين࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-48', 'warsh', 74, 48, 'فَمَا لَهُمْ عَنِ ࡴ۬لتَّذْكِرَةِ مُعْرِضِينَ', 'فما لهم عن ࡴلتذكرة معرضين', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-49', 'warsh', 74, 49, 'كَأَنَّهُمْ حُمُرࣱ مُّسْتَنفَرَةࣱ', 'كأنهم حمر مستنفرة', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-50', 'warsh', 74, 50, 'فَرَّتْ مِن قَسْوَرَةِۢ࣌', 'فرت من قسورة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-51', 'warsh', 74, 51, 'بَلْ يُرِيدُ كُلُّ ࡲٜمْرِےࣲٕ مِّنْهُمُۥٓ أَنْ يُّوتٜىٰ صُحُفاࣰ مُّنَشَّرَةࣰ࣌', 'بل يريد كل ࡲمرے منهم أن يوتى صحفا منشرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-52', 'warsh', 74, 52, 'كَلَّا بَل لَّا يَخَافُونَ ࡰ۬لَاخِرَةَ࣌', 'كلا بل لا يخافون ࡰلاخرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-53', 'warsh', 74, 53, 'كَلَّآ إِنَّهُۥ تَذْكِرَةࣱ࣌', 'كلا إنه تذكرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-54', 'warsh', 74, 54, 'فَمَن شَآءَ ذَكَرَهُۥ࣌', 'فمن شاء ذكره࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-74-55', 'warsh', 74, 55, 'وَمَا تَذْكُرُونَ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ࣌ هُوَ أَهْلُ ࡲ۬لتَّقْوٜىٰ وَأَهْلُ ࡲ۬لْمَغْفِرَةِ࣌', 'وما تذكرون إلا أن يشاء ࡰلله࣌ هو أهل ࡲلتقوى وأهل ࡲلمغفرة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-1', 'warsh', 75, 1, 'لَآ أُقْسِمُ بِيَوْمِ ࡴ۬لْقِيَٰمَةِ', 'لا أقسم بيوم ࡴلقيمة', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-2', 'warsh', 75, 2, 'وَلَآ أُقْسِمُ بِالنَّفْسِ ࡴ۬للَّوَّامَةِ࣌', 'ولا أقسم بالنفس ࡴللوامة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-3', 'warsh', 75, 3, 'أَيَحْسِبُ ࡲ۬لِانسَٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', 'أيحسب ࡲلانسن ألن نجمع عظامه', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-4', 'warsh', 75, 4, 'بَلٜىٰ࣌ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ࣌', 'بلى࣌ قدرين على أن نسوي بنانه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-5', 'warsh', 75, 5, 'بَلْ يُرِيدُ ࡲ۬لِانسَٰنُ لِيَفْجُرَ أَمَامَهُۥ࣌', 'بل يريد ࡲلانسن ليفجر أمامه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-6', 'warsh', 75, 6, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ࡲ۬لْقِيَٰمَةِ࣌', 'يسل أيان يوم ࡲلقيمة࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-7', 'warsh', 75, 7, 'فَإِذَا بَرَقَ ࡰ۬لْبَصَرُ', 'فإذا برق ࡰلبصر', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-8', 'warsh', 75, 8, 'وَخَسَفَ ࡰ۬لْقَمَرُ', 'وخسف ࡰلقمر', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-9', 'warsh', 75, 9, 'وَجُمِعَ ࡰ۬لشَّمْسُ وَالْقَمَرُ', 'وجمع ࡰلشمس والقمر', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-10', 'warsh', 75, 10, 'يَقُولُ ࡲ۬لِانسَٰنُ يَوْمَئِذٍ ࡰيْنَ ࡰ۬لْمَفَرُّ࣌', 'يقول ࡲلانسن يومئذ ࡰين ࡰلمفر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-11', 'warsh', 75, 11, 'كَلَّا لَا وَزَرَ࣌', 'كلا لا وزر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-12', 'warsh', 75, 12, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ࡴ۬لْمُسْتَقَرُّ࣌', 'إلى ربك يومئذ ࡴلمستقر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-13', 'warsh', 75, 13, 'يُنَبَّؤُاْ ࡲ۬لِانسَٰنُ يَوْمَئِذِۢ بِمَا قَدَّمَ وَأَخَّرَ࣌', 'ينبؤا ࡲلانسن يومئذ بما قدم وأخر࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-14', 'warsh', 75, 14, 'بَلِ ࡴ۬لِانسَٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةࣱ', 'بل ࡴلانسن على نفسه بصيرة', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-15', 'warsh', 75, 15, 'وَلَوَ ࡰلْقٜىٰ مَعَاذِيرَهُۥ࣌', 'ولو ࡰلقى معاذيره࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-16', 'warsh', 75, 16, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ࣌ إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ࣌', 'لا تحرك به لسانك لتعجل به࣌ إن علينا جمعه وقرءانه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-17', 'warsh', 75, 17, 'فَإِذَا قَرَأْنَٰهُ فَاتَّبِعْ قُرْءَانَهُۥ', 'فإذا قرأنه فاتبع قرءانه', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-18', 'warsh', 75, 18, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ࣌', 'ثم إن علينا بيانه࣌', NULL, 577, 'local:warsh-text.json'),
  ('warsh-75-19', 'warsh', 75, 19, 'كَلَّا بَلْ تُحِبُّونَ ࡰ۬لْعَاجِلَةَ', 'كلا بل تحبون ࡰلعاجلة', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-20', 'warsh', 75, 20, 'وَتَذَرُونَ ࡰ۬لَاخِرَةَ࣌', 'وتذرون ࡰلاخرة࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-21', 'warsh', 75, 21, 'وُجُوهࣱ يَوْمَئِذࣲ نَّاضِرَةٌ', 'وجوه يومئذ ناضرة', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-22', 'warsh', 75, 22, 'ࡴلَىٰ رَبِّهَا نَاظِرَةࣱ࣌', 'ࡴلى ربها ناظرة࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-23', 'warsh', 75, 23, 'وَوُجُوهࣱ يَوْمَئِذِۢ بَاسِرَةࣱ', 'ووجوه يومئذ باسرة', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-24', 'warsh', 75, 24, 'تَظُنُّ أَنْ يُّفْعَلَ بِهَا فَاقِرَةࣱ࣌', 'تظن أن يفعل بها فاقرة࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-25', 'warsh', 75, 25, 'كَلَّآ إِذَا بَلَغَتِ ࡴ۬لتَّرَاقِيَ', 'كلا إذا بلغت ࡴلتراقي', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-26', 'warsh', 75, 26, 'وَقِيلَ مَن رَّاقࣲ', 'وقيل من راق', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-27', 'warsh', 75, 27, 'وَظَنَّ أَنَّهُ ࡲ۬لْفِرَاقُ', 'وظن أنه ࡲلفراق', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-28', 'warsh', 75, 28, 'وَالْتَفَّتِ ࡴ۬لسَّاقُ بِالسَّاقِ', 'والتفت ࡴلساق بالساق', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-29', 'warsh', 75, 29, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ࡴ۬لْمَسَاقُ࣌', 'إلى ربك يومئذ ࡴلمساق࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-30', 'warsh', 75, 30, 'فَلَا صَدَّقَ وَلَا صَلّٜىٰ࣌', 'فلا صدق ولا صلى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-31', 'warsh', 75, 31, 'وَلَٰكِن كَذَّبَ وَتَوَلّٜىٰ࣌', 'ولكن كذب وتولى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-32', 'warsh', 75, 32, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطّٜىٰٓ࣌', 'ثم ذهب إلى أهله يتمطى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-33', 'warsh', 75, 33, 'أَوْلٜىٰ لَكَ فَأَوْلٜىٰ', 'أولى لك فأولى', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-34', 'warsh', 75, 34, 'ثُمَّ أَوْلٜىٰ لَكَ فَأَوْلٜىٰٓ࣌', 'ثم أولى لك فأولى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-35', 'warsh', 75, 35, 'أَيَحْسِبُ ࡲ۬لِانسَٰنُ أَنْ يُّتْرَكَ سُدىً࣌', 'أيحسب ࡲلانسن أن يترك سدى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-36', 'warsh', 75, 36, 'ࡰلَمْ يَكُ نُطْفَةࣰ مِّن مَّنِيࣲّ تُمْنٜىٰ', 'ࡰلم يك نطفة من مني تمنى', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-37', 'warsh', 75, 37, 'ثُمَّ كَانَ عَلَقَةࣰ فَخَلَقَ فَسَوّٜىٰ', 'ثم كان علقة فخلق فسوى', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-38', 'warsh', 75, 38, 'فَجَعَلَ مِنْهُ ࡲ۬لزَّوْجَيْنِ ࡴ۬لذَّكَرَ وَالُانثٜىٰٓ࣌', 'فجعل منه ࡲلزوجين ࡴلذكر والانثى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-75-39', 'warsh', 75, 39, 'أَلَيْسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَنْ يُّحْۑِيَ ࡰ۬لْمَوْتٜىٰ࣌', 'أليس ذلك بقدر على أن يحۑي ࡰلموتى࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-1', 'warsh', 76, 1, 'هَلَ ࡰتٜىٰ عَلَى ࡰ۬لِانسَٰنِ حِينࣱ مِّنَ ࡰ۬لدَّهْرِ لَمْ يَكُن شَيْـٔاࣰ مَّذْكُوراً࣌', 'هل ࡰتى على ࡰلانسن حين من ࡰلدهر لم يكن شيا مذكورا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-2', 'warsh', 76, 2, 'ࡴنَّا خَلَقْنَا ࡰ۬لِانسَٰنَ مِن نُّطْفَةٍ ࡰمْشَاجࣲ نَّبْتَلِيهِ فَجَعَلْنَٰهُ سَمِيعاَۢ بَصِيراً࣌', 'ࡴنا خلقنا ࡰلانسن من نطفة ࡰمشاج نبتليه فجعلنه سميعا بصيرا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-3', 'warsh', 76, 3, 'ࡴنَّا هَدَيْنَٰهُ ࡲ۬لسَّبِيلَ إِمَّا شَاكِراࣰ وَإِمَّا كَفُوراً࣌', 'ࡴنا هدينه ࡲلسبيل إما شاكرا وإما كفورا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-4', 'warsh', 76, 4, 'ࡴنَّآ أَعْتَدْنَا لِلْكٜـٰفِرِينَ سَلَٰسِلاࣰ وَأَغْلَٰلاࣰ وَسَعِيراً࣌', 'ࡴنا أعتدنا للكفرين سلسلا وأغللا وسعيرا࣌', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-5', 'warsh', 76, 5, 'ࡴنَّ ࡰ۬لَابْرَارَ يَشْرَبُونَ مِن كَأْسࣲ كَانَ مِزَاجُهَا كَافُوراً', 'ࡴن ࡰلابرار يشربون من كأس كان مزاجها كافورا', NULL, 578, 'local:warsh-text.json'),
  ('warsh-76-6', 'warsh', 76, 6, 'عَيْناࣰ يَشْرَبُ بِهَا عِبَادُ ࡲ۬للَّهِ يُفَجِّرُونَهَا تَفْجِيراࣰ࣌', 'عينا يشرب بها عباد ࡲلله يفجرونها تفجيرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-7', 'warsh', 76, 7, 'يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْماࣰ كَانَ شَرُّهُۥ مُسْتَطِيراࣰ࣌', 'يوفون بالنذر ويخافون يوما كان شره مستطيرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-8', 'warsh', 76, 8, 'وَيُطْعِمُونَ ࡰ۬لطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِيناࣰ وَيَتِيماࣰ وَأَسِيراً', 'ويطعمون ࡰلطعام على حبه مسكينا ويتيما وأسيرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-9', 'warsh', 76, 9, 'ࡴنَّمَا نُطْعِمُكُمْ لِوَجْهِ ࡴ۬للَّهِ࣌ لَا نُرِيدُ مِنكُمْ جَزَآءࣰ وَلَا شُكُوراً࣌', 'ࡴنما نطعمكم لوجه ࡴلله࣌ لا نريد منكم جزاء ولا شكورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-10', 'warsh', 76, 10, 'ࡴنَّا نَخَافُ مِن رَّبِّنَا يَوْماً عَبُوساࣰ قَمْطَرِيراࣰ࣌', 'ࡴنا نخاف من ربنا يوما عبوسا قمطريرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-11', 'warsh', 76, 11, 'فَوَقٜيٰهُمُ ࡲ۬للَّهُ شَرَّ ذَٰلِكَ ࡰ۬لْيَوْمِ وَلَقّٜيٰهُمْ نَضْرَةࣰ وَسُرُوراࣰ࣌', 'فوقيهم ࡲلله شر ذلك ࡰليوم ولقيهم نضرة وسرورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-12', 'warsh', 76, 12, 'وَجَزٜيٰهُم بِمَا صَبَرُواْ جَنَّةࣰ وَحَرِيراࣰ', 'وجزيهم بما صبروا جنة وحريرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-13', 'warsh', 76, 13, 'مُّتَّكِـِٕينَ فِيهَا عَلَى ࡰ۬لَارَآئِكِ لَا يَرَوْنَ فِيهَا شَمْساࣰ وَلَا زَمْهَرِيراࣰ', 'متكين فيها على ࡰلارائك لا يرون فيها شمسا ولا زمهريرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-14', 'warsh', 76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلاࣰ࣌', 'ودانية عليهم ظللها وذللت قطوفها تذليلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-15', 'warsh', 76, 15, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةࣲ مِّن فِضَّةࣲ وَأَكْوَابࣲ كَانَتْ قَوَارِيراࣰ࣌', 'ويطاف عليهم بانية من فضة وأكواب كانت قواريرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-16', 'warsh', 76, 16, 'قَوَارِيراࣰ مِّن فِضَّةࣲ قَدَّرُوهَا تَقْدِيراࣰ࣌', 'قواريرا من فضة قدروها تقديرا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-17', 'warsh', 76, 17, 'وَيُسْقَوْنَ فِيهَا كَأْساࣰ كَانَ مِزَاجُهَا زَنجَبِيلاً', 'ويسقون فيها كأسا كان مزاجها زنجبيلا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-18', 'warsh', 76, 18, 'عَيْناࣰ فِيهَا تُسَمّٜىٰ سَلْسَبِيلاࣰ࣌', 'عينا فيها تسمى سلسبيلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-19', 'warsh', 76, 19, '۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنࣱ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤاࣰ مَّنثُوراࣰ࣌', 'ويطوف عليهم ولدن مخلدون إذا رأيتهم حسبتهم لؤلؤا منثورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-20', 'warsh', 76, 20, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيماࣰ وَمُلْكاࣰ كَبِيراً', 'وإذا رأيت ثم رأيت نعيما وملكا كبيرا', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-21', 'warsh', 76, 21, 'عَٰلِيهِمْ ثِيَابُ سُندُسٍ خُضْرࣱ وَإِسْتَبْرَقࣱ࣌ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةࣲ࣌ وَسَقٜيٰهُمْ رَبُّهُمْ شَرَاباࣰ طَهُوراً࣌', 'عليهم ثياب سندس خضر وإستبرق࣌ وحلوا أساور من فضة࣌ وسقيهم ربهم شرابا طهورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-22', 'warsh', 76, 22, 'ࡴنَّ هَٰذَا كَانَ لَكُمْ جَزَآءࣰ وَكَانَ سَعْيُكُم مَّشْكُوراً࣌', 'ࡴن هذا كان لكم جزاء وكان سعيكم مشكورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-23', 'warsh', 76, 23, 'ࡴنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ࡰ۬لْقُرْءَانَ تَنزِيلاࣰ࣌', 'ࡴنا نحن نزلنا عليك ࡰلقرءان تنزيلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-24', 'warsh', 76, 24, 'فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمُۥٓ ءَاثِماً ࡰوْ كَفُوراࣰ࣌', 'فاصبر لحكم ربك ولا تطع منهم ءاثما ࡰو كفورا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-25', 'warsh', 76, 25, 'وَاذْكُرِ ࡴٜسْمَ رَبِّكَ بُكْرَةࣰ وَأَصِيلاࣰ࣌', 'واذكر ࡴسم ربك بكرة وأصيلا࣌', NULL, 579, 'local:warsh-text.json'),
  ('warsh-76-26', 'warsh', 76, 26, 'وَمِنَ ࡰ۬ليْلِ فَاسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلاࣰ طَوِيلاً࣌', 'ومن ࡰليل فاسجد له وسبحه ليلا طويلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-27', 'warsh', 76, 27, 'ࡴنَّ هَٰٓؤُلَآءِ يُحِبُّونَ ࡰ۬لْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْماࣰ ثَقِيلاࣰ࣌', 'ࡴن هؤلاء يحبون ࡰلعاجلة ويذرون وراءهم يوما ثقيلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-28', 'warsh', 76, 28, 'نَّحْنُ خَلَقْنَٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَٰلَهُمْ تَبْدِيلاً࣌', 'نحن خلقنهم وشددنا أسرهم وإذا شئنا بدلنا أمثلهم تبديلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-29', 'warsh', 76, 29, 'ࡴنَّ هَٰذِهِۦ تَذْكِرَةࣱ࣌ فَمَن شَآءَ ࡰٜتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلاࣰ࣌', 'ࡴن هذه تذكرة࣌ فمن شاء ࡰتخذ إلى ربه سبيلا࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-30', 'warsh', 76, 30, 'وَمَا تَشَآءُونَ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ࣌ إِنَّ ࡰ۬للَّهَ كَانَ عَلِيماً حَكِيماࣰ࣌', 'وما تشاءون إلا أن يشاء ࡰلله࣌ إن ࡰلله كان عليما حكيما࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-76-31', 'warsh', 76, 31, 'يُدْخِلُ مَنْ يَّشَآءُ فِے رَحْمَتِهِۦ࣌ وَالظَّٰلِمِينَ أَعَدَّ لَهُمْ عَذَاباً ࡰلِيماࣰ࣌', 'يدخل من يشاء فے رحمته࣌ والظلمين أعد لهم عذابا ࡰليما࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-1', 'warsh', 77, 1, 'وَالْمُرْسَلَٰتِ عُرْفاࣰ', 'والمرسلت عرفا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-2', 'warsh', 77, 2, 'فَالْعَٰصِفَٰتِ عَصْفاࣰ', 'فالعصفت عصفا', NULL, 580, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-77-3', 'warsh', 77, 3, 'وَالنَّٰشِرَٰتِ نَشْراࣰ', 'والنشرت نشرا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-4', 'warsh', 77, 4, 'فَالْفَٰرِقَٰتِ فَرْقاࣰ', 'فالفرقت فرقا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-5', 'warsh', 77, 5, 'فَالْمُلْقِيَٰتِ ذِكْراً', 'فالملقيت ذكرا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-6', 'warsh', 77, 6, 'عُذْراً ࡰوْ نُذُراً', 'عذرا ࡰو نذرا', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-7', 'warsh', 77, 7, 'ࡴنَّمَا تُوعَدُونَ لَوَٰقِعࣱ࣌', 'ࡴنما توعدون لوقع࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-8', 'warsh', 77, 8, 'فَإِذَا ࡰ۬لنُّجُومُ طُمِسَتْ', 'فإذا ࡰلنجوم طمست', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-9', 'warsh', 77, 9, 'وَإِذَا ࡰ۬لسَّمَآءُ فُرِجَتْ', 'وإذا ࡰلسماء فرجت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-10', 'warsh', 77, 10, 'وَإِذَا ࡰ۬لْجِبَالُ نُسِفَتْ', 'وإذا ࡰلجبال نسفت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-11', 'warsh', 77, 11, 'وَإِذَا ࡰ۬لرُّسُلُ أُقِّتَتْ', 'وإذا ࡰلرسل أقتت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-12', 'warsh', 77, 12, 'لِأَيِّ يَوْمٍ ࡳجِّلَتْ', 'لأي يوم ࡳجلت', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-13', 'warsh', 77, 13, 'لِيَوْمِ ࡴ۬لْفَصْلِ࣌', 'ليوم ࡴلفصل࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-14', 'warsh', 77, 14, 'وَمَآ أَدْرٜيٰكَ مَا يَوْمُ ࡲ۬لْفَصْلِ࣌', 'وما أدريك ما يوم ࡲلفصل࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-15', 'warsh', 77, 15, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-16', 'warsh', 77, 16, '۞ أَلَمْ نُهْلِكِ ࡴ۬لَاوَّلِينَ࣌', 'ألم نهلك ࡴلاولين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-17', 'warsh', 77, 17, 'ثُمَّ نُتْبِعُهُمُ ࡲ۬لَاخِرِينَ࣌', 'ثم نتبعهم ࡲلاخرين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-18', 'warsh', 77, 18, 'كَذَٰلِكَ نَفْعَلُ بِالْمُجْرِمِينَ࣌', 'كذلك نفعل بالمجرمين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-19', 'warsh', 77, 19, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 580, 'local:warsh-text.json'),
  ('warsh-77-20', 'warsh', 77, 20, 'أَلَمْ نَخْلُقكُّم مِّن مَّآءࣲ مَّهِينࣲ', 'ألم نخلقكم من ماء مهين', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-21', 'warsh', 77, 21, 'فَجَعَلْنَٰهُ فِے قَرٜارࣲ مَّكِينٍ', 'فجعلنه فے قرار مكين', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-22', 'warsh', 77, 22, 'ࡴلَىٰ قَدَرࣲ مَّعْلُومࣲ', 'ࡴلى قدر معلوم', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-23', 'warsh', 77, 23, 'فَقَدَّرْنَا࣌ فَنِعْمَ ࡰ۬لْقَٰدِرُونَ࣌', 'فقدرنا࣌ فنعم ࡰلقدرون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-24', 'warsh', 77, 24, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-25', 'warsh', 77, 25, 'أَلَمْ نَجْعَلِ ࡴ۬لَارْضَ كِفَاتاً', 'ألم نجعل ࡴلارض كفاتا', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-26', 'warsh', 77, 26, 'ࡰحْيَآءࣰ وَأَمْوَٰتاࣰ', 'ࡰحياء وأموتا', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-27', 'warsh', 77, 27, 'وَجَعَلْنَا فِيهَا رَوَٰسِيَ شَٰمِخَٰتࣲ وَأَسْقَيْنَٰكُم مَّآءࣰ فُرَاتاࣰ࣌', 'وجعلنا فيها روسي شمخت وأسقينكم ماء فراتا࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-28', 'warsh', 77, 28, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-29', 'warsh', 77, 29, 'ࡰٜنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ', 'ࡰنطلقوا إلى ما كنتم به تكذبون', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-30', 'warsh', 77, 30, 'ࡰٜنطَلِقُوٓاْ إِلَىٰ ظِلࣲّ ذِے ثَلَٰثِ شُعَبࣲ', 'ࡰنطلقوا إلى ظل ذے ثلث شعب', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-31', 'warsh', 77, 31, 'لَّا ظَلِيلࣲ وَلَا يُغْنِے مِنَ ࡰ۬للَّهَبِ࣌', 'لا ظليل ولا يغنے من ࡰللهب࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-32', 'warsh', 77, 32, 'إِنَّهَا تَرْمِے بِشَرَرࣲ كَالْقَصْرِ', 'إنها ترمے بشرر كالقصر', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-33', 'warsh', 77, 33, 'كَأَنَّهُۥ جِمَٰلَٰتࣱ صُفْرࣱ࣌', 'كأنه جملت صفر࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-34', 'warsh', 77, 34, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-35', 'warsh', 77, 35, 'هَٰذَا يَوْمُ لَا يَنطِقُونَ', 'هذا يوم لا ينطقون', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-36', 'warsh', 77, 36, 'وَلَا يُوذَنُ لَهُمْ فَيَعْتَذِرُونَ࣌', 'ولا يوذن لهم فيعتذرون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-37', 'warsh', 77, 37, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-38', 'warsh', 77, 38, 'هَٰذَا يَوْمُ ࡲ۬لْفَصْلِ جَمَعْنَٰكُمْ وَالَاوَّلِينَ', 'هذا يوم ࡲلفصل جمعنكم والاولين', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-39', 'warsh', 77, 39, 'فَإِن كَانَ لَكُمْ كَيْدࣱ فَكِيدُونِ࣌', 'فإن كان لكم كيد فكيدون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-40', 'warsh', 77, 40, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-41', 'warsh', 77, 41, 'إِنَّ ࡰ۬لْمُتَّقِينَ فِے ظِلَٰلࣲ وَعُيُونࣲ', 'إن ࡰلمتقين فے ظلل وعيون', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-42', 'warsh', 77, 42, 'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ࣌', 'وفوكه مما يشتهون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-43', 'warsh', 77, 43, 'كُلُواْ وَاشْرَبُواْ࣌ هَنِيٓـٔاَۢ بِمَا كُنتُمْ تَعْمَلُونَ࣌', 'كلوا واشربوا࣌ هنيا بما كنتم تعملون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-44', 'warsh', 77, 44, 'إِنَّا كَذَٰلِكَ نَجْزِے ࡴ۬لْمُحْسِنِينَ࣌', 'إنا كذلك نجزے ࡴلمحسنين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-45', 'warsh', 77, 45, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-46', 'warsh', 77, 46, 'كُلُواْ وَتَمَتَّعُواْ قَلِيلاً ࡴنَّكُم مُّجْرِمُونَ࣌', 'كلوا وتمتعوا قليلا ࡴنكم مجرمون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-47', 'warsh', 77, 47, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-48', 'warsh', 77, 48, 'وَإِذَا قِيلَ لَهُمُ ࡲٜرْكَعُواْ لَا يَرْكَعُونَ࣌', 'وإذا قيل لهم ࡲركعوا لا يركعون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-49', 'warsh', 77, 49, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ࣌', 'ويل يومئذ للمكذبين࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-77-50', 'warsh', 77, 50, 'فَبِأَيِّ حَدِيثِۢ بَعْدَهُۥ يُومِنُونَ࣌', 'فبأي حديث بعده يومنون࣌', NULL, 581, 'local:warsh-text.json'),
  ('warsh-78-1', 'warsh', 78, 1, 'عَمَّ࣌ يَتَسَآءَلُونَ', 'عم࣌ يتساءلون', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-2', 'warsh', 78, 2, 'عَنِ ࡴ۬لنَّبَإِ ࡴ۬لْعَظِيمِ', 'عن ࡴلنبإ ࡴلعظيم', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-3', 'warsh', 78, 3, 'ࡴ۬لذِے هُمْ فِيهِ مُخْتَلِفُونَ࣌', 'ࡴلذے هم فيه مختلفون࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-4', 'warsh', 78, 4, 'كَلَّا سَيَعْلَمُونَ', 'كلا سيعلمون', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-5', 'warsh', 78, 5, 'ثُمَّ كَلَّا سَيَعْلَمُونَ࣌', 'ثم كلا سيعلمون࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-6', 'warsh', 78, 6, 'أَلَمْ نَجْعَلِ ࡴ۬لَارْضَ مِهَٰداࣰ', 'ألم نجعل ࡴلارض مهدا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-7', 'warsh', 78, 7, 'وَالْجِبَالَ أَوْتَاداࣰ', 'والجبال أوتادا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-8', 'warsh', 78, 8, 'وَخَلَقْنَٰكُمُۥٓ أَزْوَٰجاࣰ', 'وخلقنكم أزوجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-9', 'warsh', 78, 9, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتاࣰ', 'وجعلنا نومكم سباتا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-10', 'warsh', 78, 10, 'وَجَعَلْنَا ࡰ۬ليْلَ لِبَاساࣰ', 'وجعلنا ࡰليل لباسا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-11', 'warsh', 78, 11, 'وَجَعَلْنَا ࡰ۬لنَّهَارَ مَعَاشاࣰ', 'وجعلنا ࡰلنهار معاشا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-12', 'warsh', 78, 12, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعاࣰ شِدَاداࣰ', 'وبنينا فوقكم سبعا شدادا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-13', 'warsh', 78, 13, 'وَجَعَلْنَا سِرَاجاࣰ وَهَّاجاࣰ', 'وجعلنا سراجا وهاجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-14', 'warsh', 78, 14, 'وَأَنزَلْنَا مِنَ ࡰ۬لْمُعْصِرَٰتِ مَآءࣰ ثَجَّاجاࣰ', 'وأنزلنا من ࡰلمعصرت ماء ثجاجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-15', 'warsh', 78, 15, 'لِّنُخْرِجَ بِهِۦ حَبّاࣰ وَنَبَاتاࣰ', 'لنخرج به حبا ونباتا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-16', 'warsh', 78, 16, 'وَجَنَّٰتٍ ࡰلْفَافاً࣌', 'وجنت ࡰلفافا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-17', 'warsh', 78, 17, 'ࡴنَّ يَوْمَ ࡰ۬لْفَصْلِ كَانَ مِيقَٰتاࣰ', 'ࡴن يوم ࡰلفصل كان ميقتا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-18', 'warsh', 78, 18, 'يَوْمَ يُنفَخُ فِے ࡴ۬لصُّورِ فَتَاتُونَ أَفْوَاجاࣰ', 'يوم ينفخ فے ࡴلصور فتاتون أفواجا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-19', 'warsh', 78, 19, 'وَفُتِّحَتِ ࡴ۬لسَّمَآءُ فَكَانَتَ ࡰبْوَٰباࣰ', 'وفتحت ࡴلسماء فكانت ࡰبوبا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-20', 'warsh', 78, 20, 'وَسُيِّرَتِ ࡴ۬لْجِبَالُ فَكَانَتْ سَرَاباً࣌', 'وسيرت ࡴلجبال فكانت سرابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-21', 'warsh', 78, 21, 'ࡴنَّ جَهَنَّمَ كَانَتْ مِرْصَاداࣰ', 'ࡴن جهنم كانت مرصادا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-22', 'warsh', 78, 22, 'لِّلطَّٰغِينَ مَـَٔاباࣰ', 'للطغين مابا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-23', 'warsh', 78, 23, 'لَّٰبِثِينَ فِيهَآ أَحْقَاباࣰ࣌', 'لبثين فيها أحقابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-24', 'warsh', 78, 24, 'لَّا يَذُوقُونَ فِيهَا بَرْداࣰ وَلَا شَرَاباً', 'لا يذوقون فيها بردا ولا شرابا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-25', 'warsh', 78, 25, 'ࡴلَّا حَمِيماࣰ وَغَسَاقاࣰ', 'ࡴلا حميما وغساقا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-26', 'warsh', 78, 26, 'جَزَآءࣰ وِفَاقاً࣌', 'جزاء وفاقا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-27', 'warsh', 78, 27, 'ࡴنَّهُمْ كَانُواْ لَا يَرْجُونَ حِسَاباࣰ', 'ࡴنهم كانوا لا يرجون حسابا', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-28', 'warsh', 78, 28, 'وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّاباࣰ࣌', 'وكذبوا بايتنا كذابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-29', 'warsh', 78, 29, 'وَكُلَّ شَےْءٍ ࡰحْصَيْنَٰهُ كِتَٰباࣰ࣌', 'وكل شےء ࡰحصينه كتبا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-30', 'warsh', 78, 30, 'فَذُوقُواْ فَلَن نَّزِيدَكُمُۥٓ إِلَّا عَذَاباً࣌', 'فذوقوا فلن نزيدكم إلا عذابا࣌', NULL, 582, 'local:warsh-text.json'),
  ('warsh-78-31', 'warsh', 78, 31, 'ࡴنَّ لِلْمُتَّقِينَ مَفَازاً', 'ࡴن للمتقين مفازا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-32', 'warsh', 78, 32, 'حَدَآئِقَ وَأَعْنَٰباࣰ', 'حدائق وأعنبا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-33', 'warsh', 78, 33, 'وَكَوَاعِبَ أَتْرَاباࣰ', 'وكواعب أترابا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-34', 'warsh', 78, 34, 'وَكَأْساࣰ دِهَاقاࣰ', 'وكأسا دهاقا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-35', 'warsh', 78, 35, 'لَّا يَسْمَعُونَ فِيهَا لَغْواࣰ وَلَا كِذَّاباࣰ࣌', 'لا يسمعون فيها لغوا ولا كذابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-36', 'warsh', 78, 36, 'جَزَآءࣰ مِّن رَّبِّكَ عَطَآءً حِسَاباࣰ࣌', 'جزاء من ربك عطاء حسابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-37', 'warsh', 78, 37, 'رَّبُّ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ وَمَا بَيْنَهُمَا࣌ ࡰ۬لرَّحْمَٰنُ لَا يَمْلِكُونَ مِنْهُ خِطَاباࣰ࣌', 'رب ࡲلسموت والارض وما بينهما࣌ ࡰلرحمن لا يملكون منه خطابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-38', 'warsh', 78, 38, 'يَوْمَ يَقُومُ ࡲ۬لرُّوحُ وَالْمَلَٰٓئِكَةُ صَفّاࣰ لَّا يَتَكَلَّمُونَ إِلَّا مَنَ ࡰذِنَ لَهُ ࡲ۬لرَّحْمَٰنُ وَقَالَ صَوَاباࣰ࣌', 'يوم يقوم ࡲلروح والملئكة صفا لا يتكلمون إلا من ࡰذن له ࡲلرحمن وقال صوابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-39', 'warsh', 78, 39, 'ذَٰلِكَ ࡰ۬لْيَوْمُ ࡲ۬لْحَقُّ࣌ فَمَن شَآءَ ࡰٜتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔاباً࣌', 'ذلك ࡰليوم ࡲلحق࣌ فمن شاء ࡰتخذ إلى ربه مابا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-78-40', 'warsh', 78, 40, 'ࡴنَّآ أَنذَرْنَٰكُمْ عَذَاباࣰ قَرِيباࣰ يَوْمَ يَنظُرُ ࡲ۬لْمَرْءُ مَا قَدَّمَتْ يَدَٰهُ وَيَقُولُ ࡲ۬لْكَافِرُ يَٰلَيْتَنِے كُنتُ تُرَٰباࣰ࣌', 'ࡴنا أنذرنكم عذابا قريبا يوم ينظر ࡲلمرء ما قدمت يده ويقول ࡲلكافر يليتنے كنت تربا࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-1', 'warsh', 79, 1, 'وَالنَّٰزِعَٰتِ غَرْقاࣰ', 'والنزعت غرقا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-2', 'warsh', 79, 2, 'وَالنَّٰشِطَٰتِ نَشْطاࣰ', 'والنشطت نشطا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-3', 'warsh', 79, 3, 'وَالسَّٰبِحَٰتِ سَبْحاࣰ', 'والسبحت سبحا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-4', 'warsh', 79, 4, 'فَالسَّٰبِقَٰتِ سَبْقاࣰ', 'فالسبقت سبقا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-5', 'warsh', 79, 5, 'فَالْمُدَبِّرَٰتِ أَمْراࣰ', 'فالمدبرت أمرا', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-6', 'warsh', 79, 6, 'يَوْمَ تَرْجُفُ ࡲ۬لرَّاجِفَةُ', 'يوم ترجف ࡲلراجفة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-7', 'warsh', 79, 7, 'تَتْبَعُهَا ࡰ۬لرَّادِفَةُ࣌', 'تتبعها ࡰلرادفة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-8', 'warsh', 79, 8, 'قُلُوبࣱ يَوْمَئِذࣲ وَاجِفَةٌ', 'قلوب يومئذ واجفة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-9', 'warsh', 79, 9, 'ࡰبْصَٰرُهَا خَٰشِعَةࣱ࣌', 'ࡰبصرها خشعة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-10', 'warsh', 79, 10, 'يَقُولُونَ أَࢇنَّا لَمَرْدُودُونَ فِے ࡴ۬لْحَافِرَةِ', 'يقولون أࢇنا لمردودون فے ࡴلحافرة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-11', 'warsh', 79, 11, 'إِذَا كُنَّا عِظَٰماࣰ نَّخِرَةࣰ࣌', 'إذا كنا عظما نخرة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-12', 'warsh', 79, 12, 'قَالُواْ تِلْكَ إِذاࣰ كَرَّةٌ خَاسِرَةࣱ', 'قالوا تلك إذا كرة خاسرة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-13', 'warsh', 79, 13, 'فَإِنَّمَا هِيَ زَجْرَةࣱ وَٰحِدَةࣱ', 'فإنما هي زجرة وحدة', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-14', 'warsh', 79, 14, 'فَإِذَا هُم بِالسَّاهِرَةِ࣌', 'فإذا هم بالساهرة࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-15', 'warsh', 79, 15, 'هَلَ ࡰتٜيٰكَ حَدِيثُ مُوسٜىٰٓ', 'هل ࡰتيك حديث موسى', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-16', 'warsh', 79, 16, 'إِذْ نَادٜيٰهُ رَبُّهُۥ بِالْوَادِ ࡴ۬لْمُقَدَّسِ طُوَى࣌', 'إذ ناديه ربه بالواد ࡴلمقدس طوى࣌', NULL, 583, 'local:warsh-text.json'),
  ('warsh-79-17', 'warsh', 79, 17, 'ࡰٜذْهَبِ ࡴلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغٜىٰ', 'ࡰذهب ࡴلى فرعون إنه طغى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-18', 'warsh', 79, 18, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَّكّٜىٰ', 'فقل هل لك إلى أن تزكى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-19', 'warsh', 79, 19, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشٜىٰ࣌', 'وأهديك إلى ربك فتخشى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-20', 'warsh', 79, 20, 'فَأَرٜيٰهُ ࡲ۬لَايَةَ ࡰ۬لْكُبْرٜىٰ', 'فأريه ࡲلاية ࡰلكبرى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-21', 'warsh', 79, 21, 'فَكَذَّبَ وَعَصٜىٰ', 'فكذب وعصى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-22', 'warsh', 79, 22, 'ثُمَّ أَدْبَرَ يَسْعٜىٰ', 'ثم أدبر يسعى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-23', 'warsh', 79, 23, 'فَحَشَرَ فَنَادٜىٰ', 'فحشر فنادى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-24', 'warsh', 79, 24, 'فَقَالَ أَنَا رَبُّكُمُ ࡲ۬لَاعْلٜىٰ', 'فقال أنا ربكم ࡲلاعلى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-25', 'warsh', 79, 25, 'فَأَخَذَهُ ࡲ۬للَّهُ نَكَالَ ࡰ۬لَاخِرَةِ وَالُاولٜىٰٓ࣌', 'فأخذه ࡲلله نكال ࡰلاخرة والاولى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-26', 'warsh', 79, 26, 'إِنَّ فِے ذَٰلِكَ لَعِبْرَةࣰ لِّمَنْ يَّخْشٜىٰٓ࣌', 'إن فے ذلك لعبرة لمن يخشى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-27', 'warsh', 79, 27, 'ءَآنتُمُۥٓ أَشَدُّ خَلْقاً ࡰمِ ࡴ۬لسَّمَآءُ࣌ بَنَيٰهَا', 'ءانتم أشد خلقا ࡰم ࡴلسماء࣌ بنيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-28', 'warsh', 79, 28, 'رَفَعَ سَمْكَهَا فَسَوَّيٰهَا', 'رفع سمكها فسويها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-29', 'warsh', 79, 29, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَيٰهَا࣌', 'وأغطش ليلها وأخرج ضحيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-30', 'warsh', 79, 30, 'وَالَارْضَ بَعْدَ ذَٰلِكَ دَحَيٰهَآ', 'والارض بعد ذلك دحيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-31', 'warsh', 79, 31, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَيٰهَا', 'أخرج منها ماءها ومرعيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-32', 'warsh', 79, 32, 'وَالْجِبَالَ أَرْسَيٰهَا', 'والجبال أرسيها', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-33', 'warsh', 79, 33, 'مَتَٰعاࣰ لَّكُمْ وَلِأَنْعَٰمِكُمْ࣌', 'متعا لكم ولأنعمكم࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-34', 'warsh', 79, 34, 'فَإِذَا جَآءَتِ ࡴ۬لطَّآمَّةُ ࡲ۬لْكُبْرٜىٰ', 'فإذا جاءت ࡴلطامة ࡲلكبرى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-35', 'warsh', 79, 35, 'يَوْمَ يَتَذَكَّرُ ࡲ۬لِانسَٰنُ مَا سَعٜىٰ', 'يوم يتذكر ࡲلانسن ما سعى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-36', 'warsh', 79, 36, 'وَبُرِّزَتِ ࡴ۬لْجَحِيمُ لِمَنْ يَّرٜىٰ࣌', 'وبرزت ࡴلجحيم لمن يرى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-37', 'warsh', 79, 37, 'فَأَمَّا مَن طَغٜىٰ وَءَاثَرَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا', 'فأما من طغى وءاثر ࡰلحيوة ࡰلدنيا', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-38', 'warsh', 79, 38, 'فَإِنَّ ࡰ۬لْجَحِيمَ هِيَ ࡰ۬لْمَأْوٜىٰ࣌', 'فإن ࡰلجحيم هي ࡰلمأوى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-39', 'warsh', 79, 39, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ࡰ۬لنَّفْسَ عَنِ ࡴ۬لْهَوٜىٰ', 'وأما من خاف مقام ربه ونهى ࡰلنفس عن ࡴلهوى', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-40', 'warsh', 79, 40, 'فَإِنَّ ࡰ۬لْجَنَّةَ هِيَ ࡰ۬لْمَأْوٜىٰ࣌', 'فإن ࡰلجنة هي ࡰلمأوى࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-41', 'warsh', 79, 41, '۞ يَسْـَٔلُونَكَ عَنِ ࡴ۬لسَّاعَةِ أَيَّانَ مُرْسَيٰهَا࣌', 'يسلونك عن ࡴلساعة أيان مرسيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-42', 'warsh', 79, 42, 'فِيمَ أَنتَ مِن ذِكْرٜيٰهَآ࣌', 'فيم أنت من ذكريها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-43', 'warsh', 79, 43, 'إِلَىٰ رَبِّكَ مُنتَهَيٰهَآ࣌', 'إلى ربك منتهيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-44', 'warsh', 79, 44, 'إِنَّمَآ أَنتَ مُنذِرُ مَنْ يَّخْشَيٰهَا࣌', 'إنما أنت منذر من يخشيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-79-45', 'warsh', 79, 45, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓاْ إِلَّا عَشِيَّةً ࡰوْ ضُحَيٰهَا࣌', 'كأنهم يوم يرونها لم يلبثوا إلا عشية ࡰو ضحيها࣌', NULL, 584, 'local:warsh-text.json'),
  ('warsh-80-1', 'warsh', 80, 1, 'عَبَسَ وَتَوَلّٜىٰٓ', 'عبس وتولى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-2', 'warsh', 80, 2, 'أَن جَآءَهُ ࡲ۬لَاعْمٜىٰ࣌', 'أن جاءه ࡲلاعمى࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-3', 'warsh', 80, 3, 'وَمَا يُدْرِيكَ࣌ لَعَلَّهُۥ يَزَّكّٜىٰٓ', 'وما يدريك࣌ لعله يزكى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-4', 'warsh', 80, 4, 'أَوْ يَذَّكَّرُ فَتَنفَعُهُ ࡲ۬لذِّكْرٜىٰٓ࣌', 'أو يذكر فتنفعه ࡲلذكرى࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-5', 'warsh', 80, 5, 'أَمَّا مَنِ ࡴٜسْتَغْنٜىٰ', 'أما من ࡴستغنى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-6', 'warsh', 80, 6, 'فَأَنتَ لَهُۥ تَصَّدّٜىٰ', 'فأنت له تصدى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-7', 'warsh', 80, 7, 'وَمَا عَلَيْكَ أَلَّا يَزَّكّٜىٰ࣌', 'وما عليك ألا يزكى࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-8', 'warsh', 80, 8, 'وَأَمَّا مَن جَآءَكَ يَسْعٜىٰ', 'وأما من جاءك يسعى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-9', 'warsh', 80, 9, 'وَهُوَ يَخْشٜىٰ', 'وهو يخشى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-10', 'warsh', 80, 10, 'فَأَنتَ عَنْهُ تَلَهّٜىٰ', 'فأنت عنه تلهى', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-11', 'warsh', 80, 11, 'كَلَّآ࣌ إِنَّهَا تَذْكِرَةࣱ࣌', 'كلا࣌ إنها تذكرة࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-12', 'warsh', 80, 12, 'فَمَن شَآءَ ذَكَرَهُۥ', 'فمن شاء ذكره', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-13', 'warsh', 80, 13, 'فِے صُحُفࣲ مُّكَرَّمَةࣲ', 'فے صحف مكرمة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-14', 'warsh', 80, 14, 'مَّرْفُوعَةࣲ مُّطَهَّرَةِۢ', 'مرفوعة مطهرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-15', 'warsh', 80, 15, 'بِأَيْدِے سَفَرَةࣲ', 'بأيدے سفرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-16', 'warsh', 80, 16, 'كِرَامِۢ بَرَرَةࣲ࣌', 'كرام بررة࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-17', 'warsh', 80, 17, 'قُتِلَ ࡰ۬لِانسَٰنُ مَآ أَكْفَرَهُۥ࣌', 'قتل ࡰلانسن ما أكفره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-18', 'warsh', 80, 18, 'مِنَ ࡰيِّ شَےْءٍ خَلَقَهُۥ࣌', 'من ࡰي شےء خلقه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-19', 'warsh', 80, 19, 'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ', 'من نطفة خلقه فقدره', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-20', 'warsh', 80, 20, 'ثُمَّ ࡰ۬لسَّبِيلَ يَسَّرَهُۥ', 'ثم ࡰلسبيل يسره', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-21', 'warsh', 80, 21, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ࣌', 'ثم أماته فأقبره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-22', 'warsh', 80, 22, 'ثُمَّ إِذَا شَآءَ انشَرَهُۥ࣌', 'ثم إذا شاء انشره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-23', 'warsh', 80, 23, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ࣌', 'كلا لما يقض ما أمره࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-24', 'warsh', 80, 24, 'فَلْيَنظُرِ ࡴ۬لِانسَٰنُ إِلَىٰ طَعَامِهِۦٓ࣌', 'فلينظر ࡴلانسن إلى طعامه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-25', 'warsh', 80, 25, 'إِنَّا صَبَبْنَا ࡰ۬لْمَآءَ صَبّاࣰ', 'إنا صببنا ࡰلماء صبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-26', 'warsh', 80, 26, 'ثُمَّ شَقَقْنَا ࡰ۬لَارْضَ شَقّاࣰ', 'ثم شققنا ࡰلارض شقا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-27', 'warsh', 80, 27, 'فَأَنۢبَتْنَا فِيهَا حَبّاࣰ', 'فأنبتنا فيها حبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-28', 'warsh', 80, 28, 'وَعِنَباࣰ وَقَضْباࣰ', 'وعنبا وقضبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-29', 'warsh', 80, 29, 'وَزَيْتُوناࣰ وَنَخْلاࣰ', 'وزيتونا ونخلا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-30', 'warsh', 80, 30, 'وَحَدَآئِقَ غُلْباࣰ', 'وحدائق غلبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-31', 'warsh', 80, 31, 'وَفَٰكِهَةࣰ وَأَبّاࣰ', 'وفكهة وأبا', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-32', 'warsh', 80, 32, 'مَّتَٰعاࣰ لَّكُمْ وَلِأَنْعَٰمِكُمْ࣌', 'متعا لكم ولأنعمكم࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-33', 'warsh', 80, 33, 'فَإِذَا جَآءَتِ ࡴ۬لصَّآخَّةُ', 'فإذا جاءت ࡴلصاخة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-34', 'warsh', 80, 34, 'يَوْمَ يَفِرُّ ࡲ۬لْمَرْءُ مِنَ ࡰخِيهِ', 'يوم يفر ࡲلمرء من ࡰخيه', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-35', 'warsh', 80, 35, 'وَأُمِّهِۦ وَأَبِيهِ', 'وأمه وأبيه', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-36', 'warsh', 80, 36, 'وَصَٰحِبَتِهِۦ وَبَنِيهِ࣌', 'وصحبته وبنيه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-37', 'warsh', 80, 37, 'لِكُلِّ ࡴٜمْرِےࣲٕ مِّنْهُمْ يَوْمَئِذࣲ شَأْنࣱ يُغْنِيهِ࣌', 'لكل ࡴمرے منهم يومئذ شأن يغنيه࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-38', 'warsh', 80, 38, 'وُجُوهࣱ يَوْمَئِذࣲ مُّسْفِرَةࣱ', 'وجوه يومئذ مسفرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-39', 'warsh', 80, 39, 'ضَاحِكَةࣱ مُّسْتَبْشِرَةࣱ࣌', 'ضاحكة مستبشرة࣌', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-40', 'warsh', 80, 40, 'وَوُجُوهࣱ يَوْمَئِذٍ عَلَيْهَا غَبَرَةࣱ', 'ووجوه يومئذ عليها غبرة', NULL, 585, 'local:warsh-text.json'),
  ('warsh-80-41', 'warsh', 80, 41, 'تَرْهَقُهَا قَتَرَةٌ࣌', 'ترهقها قترة࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-80-42', 'warsh', 80, 42, 'ࡳوْلَٰٓئِكَ هُمُ ࡲ۬لْكَفَرَةُ ࡲ۬لْفَجَرَةُ࣌', 'ࡳولئك هم ࡲلكفرة ࡲلفجرة࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-1', 'warsh', 81, 1, 'إِذَا ࡰ۬لشَّمْسُ كُوِّرَتْ', 'إذا ࡰلشمس كورت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-2', 'warsh', 81, 2, 'وَإِذَا ࡰ۬لنُّجُومُ ࡲٜنكَدَرَتْ', 'وإذا ࡰلنجوم ࡲنكدرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-3', 'warsh', 81, 3, 'وَإِذَا ࡰ۬لْجِبَالُ سُيِّرَتْ', 'وإذا ࡰلجبال سيرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-4', 'warsh', 81, 4, 'وَإِذَا ࡰ۬لْعِشَارُ عُطِّلَتْ', 'وإذا ࡰلعشار عطلت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-5', 'warsh', 81, 5, 'وَإِذَا ࡰ۬لْوُحُوشُ حُشِرَتْ', 'وإذا ࡰلوحوش حشرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-6', 'warsh', 81, 6, 'وَإِذَا ࡰ۬لْبِحَارُ سُجِّرَتْ', 'وإذا ࡰلبحار سجرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-7', 'warsh', 81, 7, 'وَإِذَا ࡰ۬لنُّفُوسُ زُوِّجَتْ', 'وإذا ࡰلنفوس زوجت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-8', 'warsh', 81, 8, 'وَإِذَا ࡰ۬لْمَوْءُۥدَةُ سُئِلَتْ', 'وإذا ࡰلموءدة سئلت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-9', 'warsh', 81, 9, 'بِأَيِّ ذَنۢبࣲ قُتِلَتْ', 'بأي ذنب قتلت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-10', 'warsh', 81, 10, 'وَإِذَا ࡰ۬لصُّحُفُ نُشِرَتْ', 'وإذا ࡰلصحف نشرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-11', 'warsh', 81, 11, 'وَإِذَا ࡰ۬لسَّمَآءُ كُشِطَتْ', 'وإذا ࡰلسماء كشطت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-12', 'warsh', 81, 12, 'وَإِذَا ࡰ۬لْجَحِيمُ سُعِّرَتْ', 'وإذا ࡰلجحيم سعرت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-13', 'warsh', 81, 13, 'وَإِذَا ࡰ۬لْجَنَّةُ أُزْلِفَتْ', 'وإذا ࡰلجنة أزلفت', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-14', 'warsh', 81, 14, 'عَلِمَتْ نَفْسࣱ مَّآ أَحْضَرَتْ࣌', 'علمت نفس ما أحضرت࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-15', 'warsh', 81, 15, 'فَلَآ أُقْسِمُ بِالْخُنَّسِ', 'فلا أقسم بالخنس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-16', 'warsh', 81, 16, 'ࡴ۬لْجَوَارِ ࡴ۬لْكُنَّسِ', 'ࡴلجوار ࡴلكنس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-17', 'warsh', 81, 17, 'وَاليْلِ إِذَا عَسْعَسَ', 'واليل إذا عسعس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-18', 'warsh', 81, 18, 'وَالصُّبْحِ إِذَا تَنَفَّسَ', 'والصبح إذا تنفس', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-19', 'warsh', 81, 19, 'إِنَّهُۥ لَقَوْلُ رَسُولࣲ كَرِيمࣲ', 'إنه لقول رسول كريم', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-20', 'warsh', 81, 20, 'ذِے قُوَّةٍ عِندَ ذِے ࡴ۬لْعَرْشِ مَكِينࣲ', 'ذے قوة عند ذے ࡴلعرش مكين', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-21', 'warsh', 81, 21, 'مُّطَاعࣲ ثَمَّ أَمِينࣲ࣌', 'مطاع ثم أمين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-22', 'warsh', 81, 22, 'وَمَا صَٰحِبُكُم بِمَجْنُونࣲ࣌', 'وما صحبكم بمجنون࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-23', 'warsh', 81, 23, 'وَلَقَدْ رٜءٜاهُ بِالُافُقِ ࡴ۬لْمُبِينِ࣌', 'ولقد رءاه بالافق ࡴلمبين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-24', 'warsh', 81, 24, 'وَمَا هُوَ عَلَى ࡰ۬لْغَيْبِ بِضَنِينࣲ࣌', 'وما هو على ࡰلغيب بضنين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-25', 'warsh', 81, 25, 'وَمَا هُوَ بِقَوْلِ شَيْطَٰنࣲ رَّجِيمࣲ', 'وما هو بقول شيطن رجيم', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-26', 'warsh', 81, 26, 'فَأَيْنَ تَذْهَبُونَ࣌', 'فأين تذهبون࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-27', 'warsh', 81, 27, 'إِنْ هُوَ إِلَّا ذِكْرࣱ لِّلْعَٰلَمِينَ', 'إن هو إلا ذكر للعلمين', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-28', 'warsh', 81, 28, 'لِمَن شَآءَ مِنكُمُۥٓ أَنْ يَّسْتَقِيمَ࣌', 'لمن شاء منكم أن يستقيم࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-81-29', 'warsh', 81, 29, 'وَمَا تَشَآءُونَ إِلَّآ أَنْ يَّشَآءَ ࡰ۬للَّهُ رَبُّ ࡲ۬لْعَٰلَمِينَ࣌', 'وما تشاءون إلا أن يشاء ࡰلله رب ࡲلعلمين࣌', NULL, 586, 'local:warsh-text.json'),
  ('warsh-82-1', 'warsh', 82, 1, 'إِذَا ࡰ۬لسَّمَآءُ ࡲٜنفَطَرَتْ', 'إذا ࡰلسماء ࡲنفطرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-2', 'warsh', 82, 2, 'وَإِذَا ࡰ۬لْكَوَاكِبُ ࡲٜنتَثَرَتْ', 'وإذا ࡰلكواكب ࡲنتثرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-3', 'warsh', 82, 3, 'وَإِذَا ࡰ۬لْبِحَارُ فُجِّرَتْ', 'وإذا ࡰلبحار فجرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-4', 'warsh', 82, 4, 'وَإِذَا ࡰ۬لْقُبُورُ بُعْثِرَتْ', 'وإذا ࡰلقبور بعثرت', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-5', 'warsh', 82, 5, 'عَلِمَتْ نَفْسࣱ مَّا قَدَّمَتْ وَأَخَّرَتْ࣌', 'علمت نفس ما قدمت وأخرت࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-6', 'warsh', 82, 6, 'يَٰٓأَيُّهَا ࡰ۬لِانسَٰنُ مَا غَرَّكَ بِرَبِّكَ ࡰ۬لْكَرِيمِ', 'يأيها ࡰلانسن ما غرك بربك ࡰلكريم', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-7', 'warsh', 82, 7, 'ࡴ۬لذِے خَلَقَكَ فَسَوّٜيٰكَ فَعَدَّلَكَ', 'ࡴلذے خلقك فسويك فعدلك', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-8', 'warsh', 82, 8, 'فِےٓ أَيِّ صُورَةࣲ مَّا شَآءَ رَكَّبَكَ࣌', 'فے أي صورة ما شاء ركبك࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-9', 'warsh', 82, 9, 'كَلَّا بَلْ تُكَذِّبُونَ بِالدِّينِ', 'كلا بل تكذبون بالدين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-10', 'warsh', 82, 10, 'وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ', 'وإن عليكم لحفظين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-11', 'warsh', 82, 11, 'كِرَاماࣰ كَٰتِبِينَ', 'كراما كتبين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-12', 'warsh', 82, 12, 'يَعْلَمُونَ مَا تَفْعَلُونَ࣌', 'يعلمون ما تفعلون࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-13', 'warsh', 82, 13, 'إِنَّ ࡰ۬لَابْرَارَ لَفِے نَعِيمࣲ࣌', 'إن ࡰلابرار لفے نعيم࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-14', 'warsh', 82, 14, 'وَإِنَّ ࡰ۬لْفُجَّارَ لَفِے جَحِيمࣲ', 'وإن ࡰلفجار لفے جحيم', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-15', 'warsh', 82, 15, 'يَصْلَوْنَهَا يَوْمَ ࡰ۬لدِّينِ', 'يصلونها يوم ࡰلدين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-16', 'warsh', 82, 16, 'وَمَا هُمْ عَنْهَا بِغَآئِبِينَ࣌', 'وما هم عنها بغائبين࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-17', 'warsh', 82, 17, 'وَمَآ أَدْرٜيٰكَ مَا يَوْمُ ࡲ۬لدِّينِ', 'وما أدريك ما يوم ࡲلدين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-18', 'warsh', 82, 18, 'ثُمَّ مَآ أَدْرٜيٰكَ مَا يَوْمُ ࡲ۬لدِّينِ࣌', 'ثم ما أدريك ما يوم ࡲلدين࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-82-19', 'warsh', 82, 19, 'يَوْمَ لَا تَمْلِكُ نَفْسࣱ لِّنَفْسࣲ شَيْـٔاࣰ࣌ وَالَامْرُ يَوْمَئِذࣲ لِّلهِ࣌', 'يوم لا تملك نفس لنفس شيا࣌ والامر يومئذ لله࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-1', 'warsh', 83, 1, 'وَيْلࣱ لِّلْمُطَفِّفِينَ', 'ويل للمطففين', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-2', 'warsh', 83, 2, 'ࡰ۬لذِينَ إِذَا ࡰٜكْتَالُواْ عَلَى ࡰ۬لنَّاسِ يَسْتَوْفُونَ', 'ࡰلذين إذا ࡰكتالوا على ࡰلناس يستوفون', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-3', 'warsh', 83, 3, 'وَإِذَا كَالُوهُمُۥٓ أَو وَّزَنُوهُمْ يُخْسِرُونَ࣌', 'وإذا كالوهم أو وزنوهم يخسرون࣌', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-4', 'warsh', 83, 4, 'أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', 'ألا يظن أولئك أنهم مبعوثون', NULL, 587, 'local:warsh-text.json'),
  ('warsh-83-5', 'warsh', 83, 5, 'لِيَوْمٍ عَظِيمࣲ', 'ليوم عظيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-6', 'warsh', 83, 6, 'يَوْمَ يَقُومُ ࡲ۬لنَّاسُ لِرَبِّ ࡴ۬لْعَٰلَمِينَ࣌', 'يوم يقوم ࡲلناس لرب ࡴلعلمين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-7', 'warsh', 83, 7, 'كَلَّآ إِنَّ كِتَٰبَ ࡰ۬لْفُجّٜارِ لَفِے سِجِّينࣲ࣌', 'كلا إن كتب ࡰلفجار لفے سجين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-8', 'warsh', 83, 8, 'وَمَآ أَدْرٜيٰكَ مَا سِجِّينࣱ', 'وما أدريك ما سجين', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-9', 'warsh', 83, 9, 'كِتَٰبࣱ مَّرْقُومࣱ࣌', 'كتب مرقوم࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-10', 'warsh', 83, 10, 'وَيْلࣱ يَوْمَئِذࣲ لِّلْمُكَذِّبِينَ', 'ويل يومئذ للمكذبين', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-11', 'warsh', 83, 11, 'ࡰ۬لذِينَ يُكَذِّبُونَ بِيَوْمِ ࡴ۬لدِّينِ࣌', 'ࡰلذين يكذبون بيوم ࡴلدين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-12', 'warsh', 83, 12, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ ࡰثِيمٍ', 'وما يكذب به إلا كل معتد ࡰثيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-13', 'warsh', 83, 13, 'ࡴذَا تُتْلٜىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ࡲ۬لَاوَّلِينَ࣌', 'ࡴذا تتلى عليه ءايتنا قال أسطير ࡲلاولين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-14', 'warsh', 83, 14, '۞ كَلَّا بَل رَّانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكْسِبُونَ࣌', 'كلا بل ران على قلوبهم ما كانوا يكسبون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-15', 'warsh', 83, 15, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذࣲ لَّمَحْجُوبُونَ࣌', 'كلا إنهم عن ربهم يومئذ لمحجوبون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-16', 'warsh', 83, 16, 'ثُمَّ إِنَّهُمْ لَصَالُواْ ࡲ۬لْجَحِيمِ࣌', 'ثم إنهم لصالوا ࡲلجحيم࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-17', 'warsh', 83, 17, 'ثُمَّ يُقَالُ هَٰذَا ࡰ۬لذِے كُنتُم بِهِۦ تُكَذِّبُونَ࣌', 'ثم يقال هذا ࡰلذے كنتم به تكذبون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-18', 'warsh', 83, 18, 'كَلَّآ إِنَّ كِتَٰبَ ࡰ۬لَابْرٜارِ لَفِے عِلِّيِّينَ࣌', 'كلا إن كتب ࡰلابرار لفے عليين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-19', 'warsh', 83, 19, 'وَمَآ أَدْرٜيٰكَ مَا عِلِّيُّونَ', 'وما أدريك ما عليون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-20', 'warsh', 83, 20, 'كِتَٰبࣱ مَّرْقُومࣱ', 'كتب مرقوم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-21', 'warsh', 83, 21, 'يَشْهَدُهُ ࡲ۬لْمُقَرَّبُونَ࣌', 'يشهده ࡲلمقربون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-22', 'warsh', 83, 22, 'إِنَّ ࡰ۬لَابْرَارَ لَفِے نَعِيمٍ', 'إن ࡰلابرار لفے نعيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-23', 'warsh', 83, 23, 'عَلَى ࡰ۬لَارَآئِكِ يَنظُرُونَ', 'على ࡰلارائك ينظرون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-24', 'warsh', 83, 24, 'تَعْرِفُ فِے وُجُوهِهِمْ نَضْرَةَ ࡰ۬لنَّعِيمِ', 'تعرف فے وجوههم نضرة ࡰلنعيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-25', 'warsh', 83, 25, 'يُسْقَوْنَ مِن رَّحِيقࣲ مَّخْتُومٍ', 'يسقون من رحيق مختوم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-26', 'warsh', 83, 26, 'خِتَٰمُهُۥ مِسْكࣱ࣌ وَفِے ذَٰلِكَ فَلْيَتَنَافَسِ ࡴ۬لْمُتَنَٰفِسُونَ࣌', 'ختمه مسك࣌ وفے ذلك فليتنافس ࡴلمتنفسون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-27', 'warsh', 83, 27, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 'ومزاجه من تسنيم', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-28', 'warsh', 83, 28, 'عَيْناࣰ يَشْرَبُ بِهَا ࡰ۬لْمُقَرَّبُونَ࣌', 'عينا يشرب بها ࡰلمقربون࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-29', 'warsh', 83, 29, 'إِنَّ ࡰ۬لذِينَ أَجْرَمُواْ كَانُواْ مِنَ ࡰ۬لذِينَ ءَامَنُواْ يَضْحَكُونَ', 'إن ࡰلذين أجرموا كانوا من ࡰلذين ءامنوا يضحكون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-30', 'warsh', 83, 30, 'وَإِذَا مَرُّواْ بِهِمْ يَتَغَامَزُونَ', 'وإذا مروا بهم يتغامزون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-31', 'warsh', 83, 31, 'وَإِذَا ࡰٜنقَلَبُوٓاْ إِلَىٰٓ أَهْلِهِمُ ࡲٜنقَلَبُواْ فَٰكِهِينَ', 'وإذا ࡰنقلبوا إلى أهلهم ࡲنقلبوا فكهين', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-32', 'warsh', 83, 32, 'وَإِذَا رَأَوْهُمْ قَالُوٓاْ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ', 'وإذا رأوهم قالوا إن هؤلاء لضالون', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-33', 'warsh', 83, 33, 'وَمَآ أُرْسِلُواْ عَلَيْهِمْ حَٰفِظِينَ࣌', 'وما أرسلوا عليهم حفظين࣌', NULL, 588, 'local:warsh-text.json'),
  ('warsh-83-34', 'warsh', 83, 34, 'فَالْيَوْمَ ࡰ۬لذِينَ ءَامَنُواْ مِنَ ࡰ۬لْكُفّٜارِ يَضْحَكُونَ', 'فاليوم ࡰلذين ءامنوا من ࡰلكفار يضحكون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-83-35', 'warsh', 83, 35, 'عَلَى ࡰ۬لَارَآئِكِ࣌ يَنظُرُونَ', 'على ࡰلارائك࣌ ينظرون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-83-36', 'warsh', 83, 36, 'هَلْ ثُوِّبَ ࡰ۬لْكُفَّارُ مَا كَانُواْ يَفْعَلُونَ࣌', 'هل ثوب ࡰلكفار ما كانوا يفعلون࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-1', 'warsh', 84, 1, 'إِذَا ࡰ۬لسَّمَآءُ ࡲٜنشَقَّتْ', 'إذا ࡰلسماء ࡲنشقت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-2', 'warsh', 84, 2, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وأذنت لربها وحقت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-3', 'warsh', 84, 3, 'وَإِذَا ࡰ۬لَارْضُ مُدَّتْ', 'وإذا ࡰلارض مدت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-4', 'warsh', 84, 4, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 'وألقت ما فيها وتخلت', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-5', 'warsh', 84, 5, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ࣌', 'وأذنت لربها وحقت࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-6', 'warsh', 84, 6, 'يَٰٓأَيُّهَا ࡰ۬لِانسَٰنُ إِنَّكَ كَادِحٌ ࡴلَىٰ رَبِّكَ كَدْحاࣰ فَمُلَٰقِيهِ࣌', 'يأيها ࡰلانسن إنك كادح ࡴلى ربك كدحا فملقيه࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-7', 'warsh', 84, 7, 'فَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ', 'فأما من ࡳوتي كتبه بيمينه', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-8', 'warsh', 84, 8, 'فَسَوْفَ يُحَاسَبُ حِسَاباࣰ يَسِيراࣰ', 'فسوف يحاسب حسابا يسيرا', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-9', 'warsh', 84, 9, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُوراࣰ࣌', 'وينقلب إلى أهله مسرورا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-10', 'warsh', 84, 10, 'وَأَمَّا مَنُ ࡳوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 'وأما من ࡳوتي كتبه وراء ظهره', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-11', 'warsh', 84, 11, 'فَسَوْفَ يَدْعُواْ ثُبُوراࣰ', 'فسوف يدعوا ثبورا', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-12', 'warsh', 84, 12, 'وَيُصَلَّىٰ سَعِيراً࣌', 'ويصلى سعيرا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-13', 'warsh', 84, 13, 'ࡴنَّهُۥ كَانَ فِےٓ أَهْلِهِۦ مَسْرُوراً࣌', 'ࡴنه كان فے أهله مسرورا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-14', 'warsh', 84, 14, 'ࡴنَّهُۥ ظَنَّ أَن لَّنْ يَّحُورَ', 'ࡴنه ظن أن لن يحور', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-15', 'warsh', 84, 15, 'بَلٜىٰٓ࣌ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيراࣰ࣌', 'بلى࣌ إن ربه كان به بصيرا࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-16', 'warsh', 84, 16, '۞ فَلَآ أُقْسِمُ بِالشَّفَقِ', 'فلا أقسم بالشفق', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-17', 'warsh', 84, 17, 'وَاليْلِ وَمَا وَسَقَ', 'واليل وما وسق', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-18', 'warsh', 84, 18, 'وَالْقَمَرِ إِذَا ࡰٜتَّسَقَ', 'والقمر إذا ࡰتسق', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-19', 'warsh', 84, 19, 'لَتَرْكَبُنَّ طَبَقاً عَن طَبَقࣲ࣌', 'لتركبن طبقا عن طبق࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-20', 'warsh', 84, 20, 'فَمَا لَهُمْ لَا يُومِنُونَ', 'فما لهم لا يومنون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-21', 'warsh', 84, 21, 'وَإِذَا قُرِۓَ عَلَيْهِمُ ࡲ۬لْقُرْءَانُ لَا يَسْجُدُونَ࣌۩', 'وإذا قرے عليهم ࡲلقرءان لا يسجدون࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-22', 'warsh', 84, 22, 'بَلِ ࡴ۬لذِينَ كَفَرُواْ يُكَذِّبُونَ', 'بل ࡴلذين كفروا يكذبون', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-23', 'warsh', 84, 23, 'وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ࣌', 'والله أعلم بما يوعون࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-24', 'warsh', 84, 24, 'فَبَشِّرْهُم بِعَذَابٍ ࡰلِيمٍ࣌', 'فبشرهم بعذاب ࡰليم࣌', NULL, 589, 'local:warsh-text.json'),
  ('warsh-84-25', 'warsh', 84, 25, 'ࡴلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُمُۥٓ أَجْرٌ غَيْرُ مَمْنُونࣲ࣌', 'ࡴلا ࡰلذين ءامنوا وعملوا ࡲلصلحت لهم أجر غير ممنون࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-1', 'warsh', 85, 1, 'وَالسَّمَآءِ ذَاتِ ࡴ۬لْبُرُوجِ', 'والسماء ذات ࡴلبروج', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-2', 'warsh', 85, 2, 'وَالْيَوْمِ ࡴ۬لْمَوْعُودِ', 'واليوم ࡴلموعود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-3', 'warsh', 85, 3, 'وَشَاهِدࣲ وَمَشْهُودࣲ', 'وشاهد ومشهود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-4', 'warsh', 85, 4, 'قُتِلَ أَصْحَٰبُ ࡲ۬لُاخْدُودِ', 'قتل أصحب ࡲلاخدود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-5', 'warsh', 85, 5, 'ࡴ۬لنّٜارِ ذَاتِ ࡴ۬لْوَقُودِ', 'ࡴلنار ذات ࡴلوقود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-6', 'warsh', 85, 6, 'إِذْ هُمْ عَلَيْهَا قُعُودࣱ', 'إذ هم عليها قعود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-7', 'warsh', 85, 7, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِالْمُومِنِينَ شُهُودࣱ࣌', 'وهم على ما يفعلون بالمومنين شهود࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-8', 'warsh', 85, 8, 'وَمَا نَقَمُواْ مِنْهُمُۥٓ إِلَّآ أَنْ يُّومِنُواْ بِاللَّهِ ࡴ۬لْعَزِيزِ ࡴ۬لْحَمِيدِ', 'وما نقموا منهم إلا أن يومنوا بالله ࡴلعزيز ࡴلحميد', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-9', 'warsh', 85, 9, 'ࡴ۬لذِے لَهُۥ مُلْكُ ࡲ۬لسَّمَٰوَٰتِ وَالَارْضِ࣌ وَاللَّهُ عَلَىٰ كُلِّ شَےْءࣲ شَهِيدٌ࣌', 'ࡴلذے له ملك ࡲلسموت والارض࣌ والله على كل شےء شهيد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-10', 'warsh', 85, 10, 'ࡴنَّ ࡰ۬لذِينَ فَتَنُواْ ࡲ۬لْمُومِنِينَ وَالْمُومِنَٰتِ ثُمَّ لَمْ يَتُوبُواْ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ࡲ۬لْحَرِيقِ࣌', 'ࡴن ࡰلذين فتنوا ࡲلمومنين والمومنت ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب ࡲلحريق࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-11', 'warsh', 85, 11, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ لَهُمْ جَنَّٰتࣱ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ࣌ ذَٰلِكَ ࡰ۬لْفَوْزُ ࡲ۬لْكَبِيرُ࣌', 'إن ࡰلذين ءامنوا وعملوا ࡲلصلحت لهم جنت تجرے من تحتها ࡰلانهر࣌ ذلك ࡰلفوز ࡲلكبير࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-12', 'warsh', 85, 12, '۞ إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ࣌', 'إن بطش ربك لشديد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-13', 'warsh', 85, 13, 'ࡴنَّهُۥ هُوَ يُبْدِۓُ وَيُعِيدُ࣌', 'ࡴنه هو يبدے ويعيد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-14', 'warsh', 85, 14, 'وَهُوَ ࡰ۬لْغَفُورُ ࡲ۬لْوَدُودُ', 'وهو ࡰلغفور ࡲلودود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-15', 'warsh', 85, 15, 'ذُو ࡲ۬لْعَرْشِ࣌ ࡴ۬لْمَجِيدُ', 'ذو ࡲلعرش࣌ ࡴلمجيد', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-16', 'warsh', 85, 16, 'فَعَّالࣱ لِّمَا يُرِيدُ࣌', 'فعال لما يريد࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-17', 'warsh', 85, 17, 'هَلَ ࡰتٜيٰكَ حَدِيثُ ࡲ۬لْجُنُودِ', 'هل ࡰتيك حديث ࡲلجنود', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-18', 'warsh', 85, 18, 'فِرْعَوْنَ وَثَمُودَ࣌', 'فرعون وثمود࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-19', 'warsh', 85, 19, 'بَلِ ࡴ۬لذِينَ كَفَرُواْ فِے تَكْذِيبࣲ', 'بل ࡴلذين كفروا فے تكذيب', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-20', 'warsh', 85, 20, 'وَاللَّهُ مِنْ وَّرَآئِهِم مُّحِيطُۢ࣌', 'والله من ورائهم محيط࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-21', 'warsh', 85, 21, 'بَلْ هُوَ قُرْءَانࣱ مَّجِيدࣱ', 'بل هو قرءان مجيد', NULL, 590, 'local:warsh-text.json'),
  ('warsh-85-22', 'warsh', 85, 22, 'فِے لَوْحࣲ مَّحْفُوظࣱ࣌', 'فے لوح محفوظ࣌', NULL, 590, 'local:warsh-text.json'),
  ('warsh-86-1', 'warsh', 86, 1, 'وَالسَّمَآءِ وَالطَّارِقِ', 'والسماء والطارق', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-2', 'warsh', 86, 2, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لطَّارِقُ', 'وما أدريك ما ࡰلطارق', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-3', 'warsh', 86, 3, 'ࡲ۬لنَّجْمُ ࡲ۬لثَّاقِبُ', 'ࡲلنجم ࡲلثاقب', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-4', 'warsh', 86, 4, 'إِن كُلُّ نَفْسࣲ لَّمَا عَلَيْهَا حَافِظࣱ࣌', 'إن كل نفس لما عليها حافظ࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-5', 'warsh', 86, 5, 'فَلْيَنظُرِ ࡴ۬لِانسَٰنُ مِمَّ خُلِقَ࣌', 'فلينظر ࡴلانسن مم خلق࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-6', 'warsh', 86, 6, 'خُلِقَ مِن مَّآءࣲ دَافِقࣲ', 'خلق من ماء دافق', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-7', 'warsh', 86, 7, 'يَخْرُجُ مِنۢ بَيْنِ ࡴ۬لصُّلْبِ وَالتَّرَآئِبِ࣌', 'يخرج من بين ࡴلصلب والترائب࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-8', 'warsh', 86, 8, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرࣱ', 'إنه على رجعه لقادر', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-9', 'warsh', 86, 9, 'يَوْمَ تُبْلَى ࡰ۬لسَّرَآئِرُ', 'يوم تبلى ࡰلسرائر', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-10', 'warsh', 86, 10, 'فَمَا لَهُۥ مِن قُوَّةࣲ وَلَا نَاصِرࣲ࣌', 'فما له من قوة ولا ناصر࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-11', 'warsh', 86, 11, 'وَالسَّمَآءِ ذَاتِ ࡴ۬لرَّجْعِ', 'والسماء ذات ࡴلرجع', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-12', 'warsh', 86, 12, 'وَالَارْضِ ذَاتِ ࡴ۬لصَّدْعِ', 'والارض ذات ࡴلصدع', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-13', 'warsh', 86, 13, 'إِنَّهُۥ لَقَوْلࣱ فَصْلࣱ', 'إنه لقول فصل', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-14', 'warsh', 86, 14, 'وَمَا هُوَ بِالْهَزْلِ࣌', 'وما هو بالهزل࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-15', 'warsh', 86, 15, 'إِنَّهُمْ يَكِيدُونَ كَيْداࣰ', 'إنهم يكيدون كيدا', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-16', 'warsh', 86, 16, 'وَأَكِيدُ كَيْداࣰ࣌', 'وأكيد كيدا࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-86-17', 'warsh', 86, 17, 'فَمَهِّلِ ࡴ۬لْكٜـٰفِرِينَ أَمْهِلْهُمْ رُوَيْداࣰ࣌', 'فمهل ࡴلكفرين أمهلهم رويدا࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-1', 'warsh', 87, 1, 'سَبِّحِ ࡴٜسْمَ رَبِّكَ ࡰ۬لَاعْلَي', 'سبح ࡴسم ربك ࡰلاعلي', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-2', 'warsh', 87, 2, 'ࡰ۬لذِے خَلَقَ فَسَوّٜىٰ', 'ࡰلذے خلق فسوى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-3', 'warsh', 87, 3, 'وَالذِے قَدَّرَ فَهَدٜىٰ', 'والذے قدر فهدى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-4', 'warsh', 87, 4, 'وَالذِےٓ أَخْرَجَ ࡰ۬لْمَرْعٜىٰ', 'والذے أخرج ࡰلمرعى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-5', 'warsh', 87, 5, 'فَجَعَلَهُۥ غُثَآءً ࡰحْوٜىٰ࣌', 'فجعله غثاء ࡰحوى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-6', 'warsh', 87, 6, 'سَنُقْرِئُكَ فَلَا تَنسٜىٰٓ', 'سنقرئك فلا تنسى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-7', 'warsh', 87, 7, 'إِلَّا مَا شَآءَ ࡰ۬للَّهُ࣌ إِنَّهُۥ يَعْلَمُ ࡲ۬لْجَهْرَ وَمَا يَخْفٜىٰ࣌', 'إلا ما شاء ࡰلله࣌ إنه يعلم ࡲلجهر وما يخفى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-8', 'warsh', 87, 8, 'وَنُيَسِّرُكَ لِلْيُسْرٜىٰ࣌', 'ونيسرك لليسرى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-9', 'warsh', 87, 9, 'فَذَكِّرِ ࡴن نَّفَعَتِ ࡴ۬لذِّكْرٜىٰ࣌', 'فذكر ࡴن نفعت ࡴلذكرى࣌', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-10', 'warsh', 87, 10, 'سَيَذَّكَّرُ مَنْ يَّخْشٜىٰ', 'سيذكر من يخشى', NULL, 591, 'local:warsh-text.json'),
  ('warsh-87-11', 'warsh', 87, 11, 'وَيَتَجَنَّبُهَا ࡰ۬لَاشْقَي', 'ويتجنبها ࡰلاشقي', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-12', 'warsh', 87, 12, 'ࡰ۬لذِے يَصْلَى ࡰ۬لنَّارَ ࡰ۬لْكُبْرٜىٰ', 'ࡰلذے يصلى ࡰلنار ࡰلكبرى', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-13', 'warsh', 87, 13, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيٜىٰ࣌', 'ثم لا يموت فيها ولا يحيى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-14', 'warsh', 87, 14, 'قَدَ ࡰفْلَحَ مَن تَزَكّٜىٰ', 'قد ࡰفلح من تزكى', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-15', 'warsh', 87, 15, 'وَذَكَرَ ࡰٜسْمَ رَبِّهِۦ فَصَلّٜىٰ࣌', 'وذكر ࡰسم ربه فصلى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-16', 'warsh', 87, 16, 'بَلْ تُوثِرُونَ ࡰ۬لْحَيَوٰةَ ࡰ۬لدُّنْيٜا', 'بل توثرون ࡰلحيوة ࡰلدنيا', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-17', 'warsh', 87, 17, 'وَالَاخِرَةُ خَيْرࣱ وَأَبْقٜىٰٓ࣌', 'والاخرة خير وأبقى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-18', 'warsh', 87, 18, 'إِنَّ هَٰذَا لَفِے ࡴ۬لصُّحُفِ ࡴ۬لُاولٜىٰ', 'إن هذا لفے ࡴلصحف ࡴلاولى', NULL, 592, 'local:warsh-text.json'),
  ('warsh-87-19', 'warsh', 87, 19, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسٜىٰ࣌', 'صحف إبرهيم وموسى࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-1', 'warsh', 88, 1, 'هَلَ ࡰتٜيٰكَ حَدِيثُ ࡲ۬لْغَٰشِيَةِ࣌', 'هل ࡰتيك حديث ࡲلغشية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-2', 'warsh', 88, 2, 'وُجُوهࣱ يَوْمَئِذٍ خَٰشِعَةٌ', 'وجوه يومئذ خشعة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-3', 'warsh', 88, 3, 'عَامِلَةࣱ نَّاصِبَةࣱ', 'عاملة ناصبة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-4', 'warsh', 88, 4, 'تَصْلَىٰ نَاراً حَامِيَةࣰ', 'تصلى نارا حامية', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-5', 'warsh', 88, 5, 'تُسْقٜىٰ مِنْ عَيْنٍ اٰنِيَةࣲ࣌', 'تسقى من عين انية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-6', 'warsh', 88, 6, 'لَّيْسَ لَهُمْ طَعَامٌ ࡴلَّا مِن ضَرِيعࣲ', 'ليس لهم طعام ࡴلا من ضريع', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-7', 'warsh', 88, 7, 'لَّا يُسْمِنُ وَلَا يُغْنِے مِن جُوعࣲ࣌', 'لا يسمن ولا يغنے من جوع࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-8', 'warsh', 88, 8, 'وُجُوهࣱ يَوْمَئِذࣲ نَّاعِمَةࣱ', 'وجوه يومئذ ناعمة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-9', 'warsh', 88, 9, 'لِّسَعْيِهَا رَاضِيَةࣱ', 'لسعيها راضية', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-10', 'warsh', 88, 10, 'فِے جَنَّةٍ عَالِيَةࣲ', 'فے جنة عالية', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-11', 'warsh', 88, 11, 'لَّا تُسْمَعُ فِيهَا لَٰغِيَةࣱ࣌', 'لا تسمع فيها لغية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-12', 'warsh', 88, 12, 'فِيهَا عَيْنࣱ جَارِيَةࣱ࣌', 'فيها عين جارية࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-13', 'warsh', 88, 13, 'فِيهَا سُرُرࣱ مَّرْفُوعَةࣱ', 'فيها سرر مرفوعة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-14', 'warsh', 88, 14, 'وَأَكْوَابࣱ مَّوْضُوعَةࣱ', 'وأكواب موضوعة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-15', 'warsh', 88, 15, 'وَنَمَارِقُ مَصْفُوفَةࣱ', 'ونمارق مصفوفة', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-16', 'warsh', 88, 16, 'وَزَرَابِيُّ مَبْثُوثَةٌ࣌', 'وزرابي مبثوثة࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-17', 'warsh', 88, 17, '۞ ࡰفَلَا يَنظُرُونَ إِلَى ࡰ۬لِابِلِ كَيْفَ خُلِقَتْ', 'ࡰفلا ينظرون إلى ࡰلابل كيف خلقت', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-18', 'warsh', 88, 18, 'وَإِلَى ࡰ۬لسَّمَآءِ كَيْفَ رُفِعَتْ', 'وإلى ࡰلسماء كيف رفعت', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-19', 'warsh', 88, 19, 'وَإِلَى ࡰ۬لْجِبَالِ كَيْفَ نُصِبَتْ', 'وإلى ࡰلجبال كيف نصبت', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-20', 'warsh', 88, 20, 'وَإِلَى ࡰ۬لَارْضِ كَيْفَ سُطِحَتْ࣌', 'وإلى ࡰلارض كيف سطحت࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-21', 'warsh', 88, 21, 'فَذَكِّرِ ࡴنَّمَآ أَنتَ مُذَكِّرࣱ࣌', 'فذكر ࡴنما أنت مذكر࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-22', 'warsh', 88, 22, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ࣌', 'لست عليهم بمصيطر࣌', NULL, 592, 'local:warsh-text.json'),
  ('warsh-88-23', 'warsh', 88, 23, 'ࡴلَّا مَن تَوَلّٜىٰ وَكَفَرَ', 'ࡴلا من تولى وكفر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-88-24', 'warsh', 88, 24, 'فَيُعَذِّبُهُ ࡲ۬للَّهُ ࡲ۬لْعَذَابَ ࡰ۬لَاكْبَرَ࣌', 'فيعذبه ࡲلله ࡲلعذاب ࡰلاكبر࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-88-25', 'warsh', 88, 25, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', 'إن إلينا إيابهم', NULL, 593, 'local:warsh-text.json'),
  ('warsh-88-26', 'warsh', 88, 26, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ࣌', 'ثم إن علينا حسابهم࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-1', 'warsh', 89, 1, 'وَالْفَجْرِ', 'والفجر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-2', 'warsh', 89, 2, 'وَلَيَالٍ عَشْرࣲ', 'وليال عشر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-3', 'warsh', 89, 3, 'وَالشَّفْعِ وَالْوَتْرِ', 'والشفع والوتر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-4', 'warsh', 89, 4, 'وَاليْلِ إِذَا يَسْرِۦ', 'واليل إذا يسر', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-5', 'warsh', 89, 5, 'هَلْ فِے ذَٰلِكَ قَسَمࣱ لِّذِے حِجْرٍ࣌', 'هل فے ذلك قسم لذے حجر࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-6', 'warsh', 89, 6, 'ࡰلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 'ࡰلم تر كيف فعل ربك بعاد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-7', 'warsh', 89, 7, 'ࡴرَمَ ذَاتِ ࡴ۬لْعِمَادِ', 'ࡴرم ذات ࡴلعماد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-8', 'warsh', 89, 8, 'ࡴ۬لتِے لَمْ يُخْلَقْ مِثْلُهَا فِے ࡴ۬لْبِلَٰدِ', 'ࡴلتے لم يخلق مثلها فے ࡴلبلد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-9', 'warsh', 89, 9, 'وَثَمُودَ ࡰ۬لذِينَ جَابُواْ ࡲ۬لصَّخْرَ بِالْوَادِۦ', 'وثمود ࡰلذين جابوا ࡲلصخر بالواد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-10', 'warsh', 89, 10, 'وَفِرْعَوْنَ ذِے ࡴ۬لَاوْتَادِ', 'وفرعون ذے ࡴلاوتاد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-11', 'warsh', 89, 11, 'ࡴ۬لذِينَ طَغَوْاْ فِے ࡴ۬لْبِلَٰدِ', 'ࡴلذين طغوا فے ࡴلبلد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-12', 'warsh', 89, 12, 'فَأَكْثَرُواْ فِيهَا ࡰ۬لْفَسَادَ', 'فأكثروا فيها ࡰلفساد', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-13', 'warsh', 89, 13, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ࣌', 'فصب عليهم ربك سوط عذاب࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-14', 'warsh', 89, 14, 'ࡴنَّ رَبَّكَ لَبِالْمِرْصَادِ࣌', 'ࡴن ربك لبالمرصاد࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-15', 'warsh', 89, 15, 'فَأَمَّا ࡰ۬لِانسَٰنُ إِذَا مَا ࡰٜبْتَلٜيٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ', 'فأما ࡰلانسن إذا ما ࡰبتليه ربه فأكرمه ونعمه', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-16', 'warsh', 89, 16, 'فَيَقُولُ رَبِّيَ أَكْرَمَنِۦ࣌', 'فيقول ربي أكرمن࣌', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-17', 'warsh', 89, 17, 'وَأَمَّآ إِذَا مَا ࡰٜبْتَلٜيٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ', 'وأما إذا ما ࡰبتليه فقدر عليه رزقه', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-18', 'warsh', 89, 18, 'فَيَقُولُ رَبِّيَ أَهَٰنَنِۦ', 'فيقول ربي أهنن', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-19', 'warsh', 89, 19, 'كَلَّا࣌ بَل لَّا تُكْرِمُونَ ࡰ۬لْيَتِيمَ', 'كلا࣌ بل لا تكرمون ࡰليتيم', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-20', 'warsh', 89, 20, 'وَلَا تَحُضُّونَ عَلَىٰ طَعَامِ ࡴ۬لْمِسْكِينِ', 'ولا تحضون على طعام ࡴلمسكين', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-21', 'warsh', 89, 21, 'وَتَاكُلُونَ ࡰ۬لتُّرَاثَ أَكْلاࣰ لَّمّاࣰ', 'وتاكلون ࡰلتراث أكلا لما', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-22', 'warsh', 89, 22, 'وَتُحِبُّونَ ࡰ۬لْمَالَ حُبّاࣰ جَمّاࣰ', 'وتحبون ࡰلمال حبا جما', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-23', 'warsh', 89, 23, 'كَلَّآ࣌ إِذَا دُكَّتِ ࡴ۬لَارْضُ دَكّاࣰ دَكّاࣰ', 'كلا࣌ إذا دكت ࡴلارض دكا دكا', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-24', 'warsh', 89, 24, 'وَجَآءَ رَبُّكَ وَالْمَلَكُ صَفّاࣰ صَفّاࣰ', 'وجاء ربك والملك صفا صفا', NULL, 593, 'local:warsh-text.json'),
  ('warsh-89-25', 'warsh', 89, 25, 'وَجِےٓءَ يَوْمَئِذِۢ بِجَهَنَّمَ', 'وجےء يومئذ بجهنم', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-26', 'warsh', 89, 26, 'يَوْمَئِذࣲ يَتَذَكَّرُ ࡲ۬لِانسَٰنُ وَأَنّٜىٰ لَهُ ࡲ۬لذِّكْرٜىٰ࣌', 'يومئذ يتذكر ࡲلانسن وأنى له ࡲلذكرى࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-27', 'warsh', 89, 27, 'يَقُولُ يَٰلَيْتَنِے قَدَّمْتُ لِحَيَاتِے࣌', 'يقول يليتنے قدمت لحياتے࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-28', 'warsh', 89, 28, 'فَيَوْمَئِذࣲ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدࣱ', 'فيومئذ لا يعذب عذابه أحد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-29', 'warsh', 89, 29, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدࣱ࣌', 'ولا يوثق وثاقه أحد࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-30', 'warsh', 89, 30, 'يَٰٓأَيَّتُهَا ࡰ۬لنَّفْسُ ࡲ۬لْمُطْمَئِنَّةُ', 'يأيتها ࡰلنفس ࡲلمطمئنة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-31', 'warsh', 89, 31, 'ࡲٜرْجِعِےٓ إِلَىٰ رَبِّكِ رَاضِيَةࣰ مَّرْضِيَّةࣰ', 'ࡲرجعے إلى ربك راضية مرضية', NULL, 594, 'local:warsh-text.json'),
  ('warsh-89-32', 'warsh', 89, 32, 'فَادْخُلِے فِے عِبَٰدِے وَادْخُلِے جَنَّتِے࣌', 'فادخلے فے عبدے وادخلے جنتے࣌', NULL, 594, 'local:warsh-text.json')
insert into public.ayahs (id, riwayah, surah_number, ayah_number, text, simple_text, juz, page, source) values
  ('warsh-90-1', 'warsh', 90, 1, 'لَآ أُقْسِمُ بِهَٰذَا ࡰ۬لْبَلَدِ', 'لا أقسم بهذا ࡰلبلد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-2', 'warsh', 90, 2, 'وَأَنتَ حِلُّۢ بِهَٰذَا ࡰ۬لْبَلَدِ', 'وأنت حل بهذا ࡰلبلد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-3', 'warsh', 90, 3, 'وَوَالِدࣲ وَمَا وَلَدَ', 'ووالد وما ولد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-4', 'warsh', 90, 4, 'لَقَدْ خَلَقْنَا ࡰ۬لِانسَٰنَ فِے كَبَدٍ࣌', 'لقد خلقنا ࡰلانسن فے كبد࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-5', 'warsh', 90, 5, 'ࡰيَحْسِبُ أَن لَّنْ يَّقْدِرَ عَلَيْهِ أَحَدࣱ', 'ࡰيحسب أن لن يقدر عليه أحد', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-6', 'warsh', 90, 6, 'يَقُولُ أَهْلَكْتُ مَالاࣰ لُّبَداً࣌', 'يقول أهلكت مالا لبدا࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-7', 'warsh', 90, 7, 'ࡰيَحْسِبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ࣌', 'ࡰيحسب أن لم يره أحد࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-8', 'warsh', 90, 8, 'ࡰلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 'ࡰلم نجعل له عينين', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-9', 'warsh', 90, 9, 'وَلِسَاناࣰ وَشَفَتَيْنِ', 'ولسانا وشفتين', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-10', 'warsh', 90, 10, 'وَهَدَيْنَٰهُ ࡲ۬لنَّجْدَيْنِ࣌', 'وهدينه ࡲلنجدين࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-11', 'warsh', 90, 11, 'فَلَا ࡰٜقْتَحَمَ ࡰ۬لْعَقَبَةَ࣌', 'فلا ࡰقتحم ࡰلعقبة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-12', 'warsh', 90, 12, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْعَقَبَةُ࣌', 'وما أدريك ما ࡰلعقبة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-13', 'warsh', 90, 13, 'فَكُّ رَقَبَةٍ', 'فك رقبة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-14', 'warsh', 90, 14, 'ࡰوِ ࡴطْعَامࣱ فِے يَوْمࣲ ذِے مَسْغَبَةࣲ', 'ࡰو ࡴطعام فے يوم ذے مسغبة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-15', 'warsh', 90, 15, 'يَتِيماࣰ ذَا مَقْرَبَةٍ', 'يتيما ذا مقربة', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-16', 'warsh', 90, 16, 'ࡰوْ مِسْكِيناࣰ ذَا مَتْرَبَةࣲ࣌', 'ࡰو مسكينا ذا متربة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-17', 'warsh', 90, 17, 'ثُمَّ كَانَ مِنَ ࡰ۬لذِينَ ءَامَنُواْ وَتَوَاصَوْاْ بِالصَّبْرِ وَتَوَاصَوْاْ بِالْمَرْحَمَةِ࣌', 'ثم كان من ࡰلذين ءامنوا وتواصوا بالصبر وتواصوا بالمرحمة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-18', 'warsh', 90, 18, 'أُوْلَٰٓئِكَ أَصْحَٰبُ ࡲ۬لْمَيْمَنَةِ࣌', 'أولئك أصحب ࡲلميمنة࣌', NULL, 594, 'local:warsh-text.json'),
  ('warsh-90-19', 'warsh', 90, 19, 'وَالذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمُۥٓ أَصْحَٰبُ ࡲ۬لْمَشْـَٔمَةِ࣌', 'والذين كفروا بايتنا هم أصحب ࡲلمشمة࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-90-20', 'warsh', 90, 20, 'عَلَيْهِمْ نَارࣱ مُّوصَدَةࣱ࣌', 'عليهم نار موصدة࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-1', 'warsh', 91, 1, 'وَالشَّمْسِ وَضُحَيٰهَا', 'والشمس وضحيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-2', 'warsh', 91, 2, 'وَالْقَمَرِ إِذَا تَلَيٰهَا', 'والقمر إذا تليها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-3', 'warsh', 91, 3, 'وَالنَّهٜارِ إِذَا جَلَّيٰهَا', 'والنهار إذا جليها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-4', 'warsh', 91, 4, 'وَاليْلِ إِذَا يَغْشَيٰهَا', 'واليل إذا يغشيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-5', 'warsh', 91, 5, 'وَالسَّمَآءِ وَمَا بَنَيٰهَا', 'والسماء وما بنيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-6', 'warsh', 91, 6, 'وَالَارْضِ وَمَا طَحَيٰهَا', 'والارض وما طحيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-7', 'warsh', 91, 7, 'وَنَفْسࣲ وَمَا سَوَّيٰهَا', 'ونفس وما سويها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-8', 'warsh', 91, 8, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَيٰهَا', 'فألهمها فجورها وتقويها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-9', 'warsh', 91, 9, 'قَدَ ࡰفْلَحَ مَن زَكَّيٰهَا', 'قد ࡰفلح من زكيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-10', 'warsh', 91, 10, 'وَقَدْ خَابَ مَن دَسَّيٰهَا࣌', 'وقد خاب من دسيها࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-11', 'warsh', 91, 11, 'كَذَّبَتْ ثَمُودُ بِطَغْوَيٰهَآ', 'كذبت ثمود بطغويها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-12', 'warsh', 91, 12, 'إِذِ ࡴٜنۢبَعَثَ أَشْقَيٰهَا', 'إذ ࡴنبعث أشقيها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-13', 'warsh', 91, 13, 'فَقَالَ لَهُمْ رَسُولُ ࡲ۬للَّهِ نَاقَةَ ࡰ۬للَّهِ وَسُقْيَاهَا', 'فقال لهم رسول ࡲلله ناقة ࡰلله وسقياها', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-14', 'warsh', 91, 14, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّيٰهَا࣌', 'فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسويها࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-91-15', 'warsh', 91, 15, 'فَلَا يَخَافُ عُقْبَٰهَا࣌', 'فلا يخاف عقبها࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-1', 'warsh', 92, 1, 'وَاليْلِ إِذَا يَغْشٜىٰ', 'واليل إذا يغشى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-2', 'warsh', 92, 2, 'وَالنَّهٜارِ إِذَا تَجَلّٜىٰ', 'والنهار إذا تجلى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-3', 'warsh', 92, 3, 'وَمَا خَلَقَ ࡰ۬لذَّكَرَ وَالُانثٜىٰٓ', 'وما خلق ࡰلذكر والانثى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-4', 'warsh', 92, 4, 'إِنَّ سَعْيَكُمْ لَشَتّٜىٰ࣌', 'إن سعيكم لشتى࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-5', 'warsh', 92, 5, 'فَأَمَّا مَنَ ࡰعْطٜىٰ وَاتَّقٜىٰ', 'فأما من ࡰعطى واتقى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-6', 'warsh', 92, 6, 'وَصَدَّقَ بِالْحُسْنٜىٰ', 'وصدق بالحسنى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-7', 'warsh', 92, 7, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرٜىٰ࣌', 'فسنيسره لليسرى࣌', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-8', 'warsh', 92, 8, 'وَأَمَّا مَنۢ بَخِلَ وَاسْتَغْنٜىٰ', 'وأما من بخل واستغنى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-9', 'warsh', 92, 9, 'وَكَذَّبَ بِالْحُسْنٜىٰ', 'وكذب بالحسنى', NULL, 595, 'local:warsh-text.json'),
  ('warsh-92-10', 'warsh', 92, 10, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرٜىٰ࣌', 'فسنيسره للعسرى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-11', 'warsh', 92, 11, 'وَمَا يُغْنِے عَنْهُ مَالُهُۥٓ إِذَا تَرَدّٜىٰٓ࣌', 'وما يغنے عنه ماله إذا تردى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-12', 'warsh', 92, 12, 'إِنَّ عَلَيْنَا لَلْهُدٜىٰ', 'إن علينا للهدى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-13', 'warsh', 92, 13, 'وَإِنَّ لَنَا لَلَاخِرَةَ وَالُاولٜىٰ࣌', 'وإن لنا للاخرة والاولى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-14', 'warsh', 92, 14, 'فَأَنذَرْتُكُمْ نَاراࣰ تَلَظّٜىٰ', 'فأنذرتكم نارا تلظى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-15', 'warsh', 92, 15, 'لَا يَصْلَيٰهَآ إِلَّا ࡰ۬لَاشْقَي', 'لا يصليها إلا ࡰلاشقي', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-16', 'warsh', 92, 16, 'ࡰ۬لذِے كَذَّبَ وَتَوَلّٜىٰ࣌', 'ࡰلذے كذب وتولى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-17', 'warsh', 92, 17, 'وَسَيُجَنَّبُهَا ࡰ۬لَاتْقَي', 'وسيجنبها ࡰلاتقي', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-18', 'warsh', 92, 18, 'ࡰ۬لذِے يُوتِے مَالَهُۥ يَتَزَكّٜىٰ࣌', 'ࡰلذے يوتے ماله يتزكى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-19', 'warsh', 92, 19, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةࣲ تُجْزٜىٰٓ', 'وما لأحد عنده من نعمة تجزى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-20', 'warsh', 92, 20, 'إِلَّا ࡰٜبْتِغَآءَ وَجْهِ رَبِّهِ ࡴ۬لَاعْلٜىٰ࣌', 'إلا ࡰبتغاء وجه ربه ࡴلاعلى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-92-21', 'warsh', 92, 21, 'وَلَسَوْفَ يَرْضٜىٰ࣌', 'ولسوف يرضى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-1', 'warsh', 93, 1, 'وَالضُّحٜىٰ', 'والضحى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-2', 'warsh', 93, 2, 'وَاليْلِ إِذَا سَجٜىٰ', 'واليل إذا سجى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-3', 'warsh', 93, 3, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلٜىٰ࣌', 'ما ودعك ربك وما قلى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-4', 'warsh', 93, 4, 'وَلَلَاخِرَةُ خَيْرࣱ لَّكَ مِنَ ࡰ۬لُاولٜىٰ࣌', 'وللاخرة خير لك من ࡰلاولى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-5', 'warsh', 93, 5, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضٜىٰٓ࣌', 'ولسوف يعطيك ربك فترضى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-6', 'warsh', 93, 6, 'أَلَمْ يَجِدْكَ يَتِيماࣰ فَـَٔاوٜىٰ', 'ألم يجدك يتيما فاوى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-7', 'warsh', 93, 7, 'وَوَجَدَكَ ضَآلّاࣰ فَهَدٜىٰ', 'ووجدك ضالا فهدى', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-8', 'warsh', 93, 8, 'وَوَجَدَكَ عَآئِلاࣰ فَأَغْنٜىٰ࣌', 'ووجدك عائلا فأغنى࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-9', 'warsh', 93, 9, 'فَأَمَّا ࡰ۬لْيَتِيمَ فَلَا تَقْهَرْ࣌', 'فأما ࡰليتيم فلا تقهر࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-10', 'warsh', 93, 10, 'وَأَمَّا ࡰ۬لسَّآئِلَ فَلَا تَنْهَرْ࣌', 'وأما ࡰلسائل فلا تنهر࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-93-11', 'warsh', 93, 11, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثَ࣌', 'وأما بنعمة ربك فحدث࣌', NULL, 596, 'local:warsh-text.json'),
  ('warsh-94-1', 'warsh', 94, 1, 'ࡰلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 'ࡰلم نشرح لك صدرك', NULL, 596, 'local:warsh-text.json'),
  ('warsh-94-2', 'warsh', 94, 2, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 'ووضعنا عنك وزرك', NULL, 596, 'local:warsh-text.json'),
  ('warsh-94-3', 'warsh', 94, 3, 'ࡰ۬لذِےٓ أَنقَضَ ظَهْرَكَ', 'ࡰلذے أنقض ظهرك', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-4', 'warsh', 94, 4, 'وَرَفَعْنَا لَكَ ذِكْرَكَ࣌', 'ورفعنا لك ذكرك࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-5', 'warsh', 94, 5, 'فَإِنَّ مَعَ ࡰ۬لْعُسْرِ يُسْراً', 'فإن مع ࡰلعسر يسرا', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-6', 'warsh', 94, 6, 'ࡴنَّ مَعَ ࡰ۬لْعُسْرِ يُسْراࣰ࣌', 'ࡴن مع ࡰلعسر يسرا࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-7', 'warsh', 94, 7, 'فَإِذَا فَرَغْتَ فَانصَبْ', 'فإذا فرغت فانصب', NULL, 597, 'local:warsh-text.json'),
  ('warsh-94-8', 'warsh', 94, 8, 'وَإِلَىٰ رَبِّكَ فَارْغَبْ࣌', 'وإلى ربك فارغب࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-1', 'warsh', 95, 1, 'وَالتِّينِ وَالزَّيْتُونِ', 'والتين والزيتون', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-2', 'warsh', 95, 2, 'وَطُورِ سِينِينَ', 'وطور سينين', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-3', 'warsh', 95, 3, 'وَهَٰذَا ࡰ۬لْبَلَدِ ࡴ۬لَامِينِ', 'وهذا ࡰلبلد ࡴلامين', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-4', 'warsh', 95, 4, 'لَقَدْ خَلَقْنَا ࡰ۬لِانسَٰنَ فِےٓ أَحْسَنِ تَقْوِيمࣲ', 'لقد خلقنا ࡰلانسن فے أحسن تقويم', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-5', 'warsh', 95, 5, 'ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ', 'ثم رددنه أسفل سفلين', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-6', 'warsh', 95, 6, 'إِلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ فَلَهُمُۥٓ أَجْرٌ غَيْرُ مَمْنُونࣲ࣌', 'إلا ࡰلذين ءامنوا وعملوا ࡲلصلحت فلهم أجر غير ممنون࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-7', 'warsh', 95, 7, 'فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ࣌', 'فما يكذبك بعد بالدين࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-95-8', 'warsh', 95, 8, 'أَلَيْسَ ࡰ۬للَّهُ بِأَحْكَمِ ࡴ۬لْحَٰكِمِينَ࣌', 'أليس ࡰلله بأحكم ࡴلحكمين࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-1', 'warsh', 96, 1, 'ࡰٜقْرَأْ بِاسْمِ رَبِّكَ ࡰ۬لذِے خَلَقَ࣌', 'ࡰقرأ باسم ربك ࡰلذے خلق࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-2', 'warsh', 96, 2, 'خَلَقَ ࡰ۬لِانسَٰنَ مِنْ عَلَقٍ࣌', 'خلق ࡰلانسن من علق࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-3', 'warsh', 96, 3, 'ࡴٜقْرَأْ وَرَبُّكَ ࡰ۬لَاكْرَمُ', 'ࡴقرأ وربك ࡰلاكرم', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-4', 'warsh', 96, 4, 'ࡲ۬لذِے عَلَّمَ بِالْقَلَمِ', 'ࡲلذے علم بالقلم', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-5', 'warsh', 96, 5, 'عَلَّمَ ࡰ۬لِانسَٰنَ مَا لَمْ يَعْلَمْ࣌', 'علم ࡰلانسن ما لم يعلم࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-6', 'warsh', 96, 6, 'كَلَّآ إِنَّ ࡰ۬لِانسَٰنَ لَيَطْغٜىٰٓ', 'كلا إن ࡰلانسن ليطغى', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-7', 'warsh', 96, 7, 'أَن رّٜءٜاهُ ࡲٜسْتَغْنٜىٰٓ࣌', 'أن رءاه ࡲستغنى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-8', 'warsh', 96, 8, 'إِنَّ إِلَىٰ رَبِّكَ ࡰ۬لرُّجْعٜىٰٓ࣌', 'إن إلى ربك ࡰلرجعى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-9', 'warsh', 96, 9, 'أَرَٰٓيْتَ ࡰ۬لذِے يَنْهٜىٰ', 'أريت ࡰلذے ينهى', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-10', 'warsh', 96, 10, 'عَبْداً ࡴذَا صَلّٜىٰٓ࣌', 'عبدا ࡴذا صلى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-11', 'warsh', 96, 11, 'أَرَٰٓيْتَ إِن كَانَ عَلَى ࡰ۬لْهُدٜىٰٓ', 'أريت إن كان على ࡰلهدى', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-12', 'warsh', 96, 12, 'أَوَ ࡰمَرَ بِالتَّقْوٜىٰٓ࣌', 'أو ࡰمر بالتقوى࣌', NULL, 597, 'local:warsh-text.json'),
  ('warsh-96-13', 'warsh', 96, 13, 'أَرَٰٓيْتَ إِن كَذَّبَ وَتَوَلّٜىٰٓ', 'أريت إن كذب وتولى', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-14', 'warsh', 96, 14, 'أَلَمْ يَعْلَم بِأَنَّ ࡰ۬للَّهَ يَرٜىٰ࣌', 'ألم يعلم بأن ࡰلله يرى࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-15', 'warsh', 96, 15, 'كَلَّا لَئِن لَّمْ يَنتَهِ', 'كلا لئن لم ينته', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-16', 'warsh', 96, 16, 'لَنَسْفَعاَۢ بِالنَّاصِيَةِ', 'لنسفعا بالناصية', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-17', 'warsh', 96, 17, 'نَاصِيَةࣲ كَٰذِبَةٍ خَاطِئَةࣲ࣌', 'ناصية كذبة خاطئة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-18', 'warsh', 96, 18, 'فَلْيَدْعُ نَادِيَهُۥ', 'فليدع ناديه', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-19', 'warsh', 96, 19, 'سَنَدْعُ ࡲ۬لزَّبَانِيَةَ࣌', 'سندع ࡲلزبانية࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-96-20', 'warsh', 96, 20, 'كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبِ࣌۩', 'كلا لا تطعه واسجد واقترب࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-1', 'warsh', 97, 1, 'ࡴنَّآ أَنزَلْنَٰهُ فِے لَيْلَةِ ࡴ۬لْقَدْرِ࣌', 'ࡴنا أنزلنه فے ليلة ࡴلقدر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-2', 'warsh', 97, 2, 'وَمَآ أَدْرٜيٰكَ مَا لَيْلَةُ ࡲ۬لْقَدْرِ࣌', 'وما أدريك ما ليلة ࡲلقدر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-3', 'warsh', 97, 3, 'لَيْلَةُ ࡲ۬لْقَدْرِ خَيْرࣱ مِّنَ ࡰلْفِ شَهْرࣲ࣌', 'ليلة ࡲلقدر خير من ࡰلف شهر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-4', 'warsh', 97, 4, 'تَنَزَّلُ ࡲ۬لْمَلَٰٓئِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرࣲ࣌', 'تنزل ࡲلملئكة والروح فيها بإذن ربهم من كل أمر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-97-5', 'warsh', 97, 5, 'سَلَٰمٌ هِيَ حَتَّىٰ مَطْلَعِ ࡴ۬لْفَجْرِ࣌', 'سلم هي حتى مطلع ࡴلفجر࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-1', 'warsh', 98, 1, 'لَمْ يَكُنِ ࡴ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَاتِيَهُمُ ࡲ۬لْبَيِّنَةُ࣌', 'لم يكن ࡴلذين كفروا من ࡰهل ࡴلكتب والمشركين منفكين حتى تاتيهم ࡲلبينة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-2', 'warsh', 98, 2, 'رَسُولࣱ مِّنَ ࡰ۬للَّهِ يَتْلُواْ صُحُفاࣰ مُّطَهَّرَةࣰ', 'رسول من ࡰلله يتلوا صحفا مطهرة', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-3', 'warsh', 98, 3, 'فِيهَا كُتُبࣱ قَيِّمَةࣱ࣌', 'فيها كتب قيمة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-4', 'warsh', 98, 4, 'وَمَا تَفَرَّقَ ࡰ۬لذِينَ أُوتُواْ ࡲ۬لْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ࡲ۬لْبَيِّنَةُ࣌', 'وما تفرق ࡰلذين أوتوا ࡲلكتب إلا من بعد ما جاءتهم ࡲلبينة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-5', 'warsh', 98, 5, 'وَمَآ أُمِرُوٓاْ إِلَّا لِيَعْبُدُواْ ࡲ۬للَّهَ مُخْلِصِينَ لَهُ ࡲ۬لدِّينَ حُنَفَآءَ وَيُقِيمُواْ ࡲ۬لصَّلَوٰةَ وَيُوتُواْ ࡲ۬لزَّكَوٰةَ࣌ وَذَٰلِكَ دِينُ ࡲ۬لْقَيِّمَةِ࣌', 'وما أمروا إلا ليعبدوا ࡲلله مخلصين له ࡲلدين حنفاء ويقيموا ࡲلصلوة ويوتوا ࡲلزكوة࣌ وذلك دين ࡲلقيمة࣌', NULL, 598, 'local:warsh-text.json'),
  ('warsh-98-6', 'warsh', 98, 6, 'إِنَّ ࡰ۬لذِينَ كَفَرُواْ مِنَ ࡰهْلِ ࡴ۬لْكِتَٰبِ وَالْمُشْرِكِينَ فِے نٜارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ࣌ أُوْلَٰٓئِكَ هُمْ شَرُّ ࡲ۬لْبَرِيٓـَٔةِ࣌', 'إن ࡰلذين كفروا من ࡰهل ࡴلكتب والمشركين فے نار جهنم خلدين فيها࣌ أولئك هم شر ࡲلبرية࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-98-7', 'warsh', 98, 7, 'إِنَّ ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمْ خَيْرُ ࡲ۬لْبَرِيٓـَٔةِ࣌', 'إن ࡰلذين ءامنوا وعملوا ࡲلصلحت أولئك هم خير ࡲلبرية࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-98-8', 'warsh', 98, 8, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنࣲ تَجْرِے مِن تَحْتِهَا ࡰ۬لَانْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَداࣰ࣌ رَّضِيَ ࡰ۬للَّهُ عَنْهُمْ وَرَضُواْ عَنْهُ࣌ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُۥٓ࣌', 'جزاؤهم عند ربهم جنت عدن تجرے من تحتها ࡰلانهر خلدين فيها أبدا࣌ رضي ࡰلله عنهم ورضوا عنه࣌ ذلك لمن خشي ربه࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-1', 'warsh', 99, 1, 'إِذَا زُلْزِلَتِ ࡴ۬لَارْضُ زِلْزَالَهَا', 'إذا زلزلت ࡴلارض زلزالها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-2', 'warsh', 99, 2, 'وَأَخْرَجَتِ ࡴ۬لَارْضُ أَثْقَالَهَا', 'وأخرجت ࡴلارض أثقالها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-3', 'warsh', 99, 3, 'وَقَالَ ࡰ۬لِانسَٰنُ مَا لَهَا', 'وقال ࡰلانسن ما لها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-4', 'warsh', 99, 4, 'يَوْمَئِذࣲ تُحَدِّثُ أَخْبَارَهَا', 'يومئذ تحدث أخبارها', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-5', 'warsh', 99, 5, 'بِأَنَّ رَبَّكَ أَوْحٜىٰ لَهَا࣌', 'بأن ربك أوحى لها࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-6', 'warsh', 99, 6, 'يَوْمَئِذࣲ يَصْدُرُ ࡲ۬لنَّاسُ أَشْتَاتاࣰ', 'يومئذ يصدر ࡲلناس أشتاتا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-7', 'warsh', 99, 7, 'لِّيُرَوَاْ ࡰعْمَٰلَهُمْ࣌', 'ليروا ࡰعملهم࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-8', 'warsh', 99, 8, 'فَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراࣰ يَرَهُۥ࣌', 'فمن يعمل مثقال ذرة خيرا يره࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-99-9', 'warsh', 99, 9, 'وَمَنْ يَّعْمَلْ مِثْقَالَ ذَرَّةࣲ شَرّاࣰ يَرَهُۥ࣌', 'ومن يعمل مثقال ذرة شرا يره࣌', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-1', 'warsh', 100, 1, 'وَالْعَٰدِيَٰتِ ضَبْحاࣰ', 'والعديت ضبحا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-2', 'warsh', 100, 2, 'فَالْمُورِيَٰتِ قَدْحاࣰ', 'فالموريت قدحا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-3', 'warsh', 100, 3, 'فَالْمُغِيرَٰتِ صُبْحاࣰ', 'فالمغيرت صبحا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-4', 'warsh', 100, 4, 'فَأَثَرْنَ بِهِۦ نَقْعاࣰ', 'فأثرن به نقعا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-5', 'warsh', 100, 5, 'فَوَسَطْنَ بِهِۦ جَمْعاً', 'فوسطن به جمعا', NULL, 599, 'local:warsh-text.json'),
  ('warsh-100-6', 'warsh', 100, 6, 'ࡴنَّ ࡰ۬لِانسَٰنَ لِرَبِّهِۦ لَكَنُودࣱ', 'ࡴن ࡰلانسن لربه لكنود', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-7', 'warsh', 100, 7, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدࣱ', 'وإنه على ذلك لشهيد', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-8', 'warsh', 100, 8, 'وَإِنَّهُۥ لِحُبِّ ࡴ۬لْخَيْرِ لَشَدِيدٌ࣌', 'وإنه لحب ࡴلخير لشديد࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-9', 'warsh', 100, 9, '۞ ࡰفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِے ࡴ۬لْقُبُورِ', 'ࡰفلا يعلم إذا بعثر ما فے ࡴلقبور', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-10', 'warsh', 100, 10, 'وَحُصِّلَ مَا فِے ࡴ۬لصُّدُورِ', 'وحصل ما فے ࡴلصدور', NULL, 600, 'local:warsh-text.json'),
  ('warsh-100-11', 'warsh', 100, 11, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذࣲ لَّخَبِيرٌ࣌', 'إن ربهم بهم يومئذ لخبير࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-1', 'warsh', 101, 1, 'ࡴ۬لْقَارِعَةُ مَا ࡰ۬لْقَارِعَةُ࣌', 'ࡴلقارعة ما ࡰلقارعة࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-2', 'warsh', 101, 2, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْقَارِعَةُ࣌', 'وما أدريك ما ࡰلقارعة࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-3', 'warsh', 101, 3, 'يَوْمَ يَكُونُ ࡲ۬لنَّاسُ كَالْفَرَاشِ ࡴ۬لْمَبْثُوثِ', 'يوم يكون ࡲلناس كالفراش ࡴلمبثوث', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-4', 'warsh', 101, 4, 'وَتَكُونُ ࡲ۬لْجِبَالُ كَالْعِهْنِ ࡴ۬لْمَنفُوشِ࣌', 'وتكون ࡲلجبال كالعهن ࡴلمنفوش࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-5', 'warsh', 101, 5, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 'فأما من ثقلت موزينه', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-6', 'warsh', 101, 6, 'فَهُوَ فِے عِيشَةࣲ رَّاضِيَةࣲ࣌', 'فهو فے عيشة راضية࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-7', 'warsh', 101, 7, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 'وأما من خفت موزينه', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-8', 'warsh', 101, 8, 'فَأُمُّهُۥ هَاوِيَةࣱ࣌', 'فأمه هاوية࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-9', 'warsh', 101, 9, 'وَمَآ أَدْرٜيٰكَ مَا هِيَهْ࣌', 'وما أدريك ما هيه࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-101-10', 'warsh', 101, 10, 'نَارٌ حَامِيَةٌ࣌', 'نار حامية࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-1', 'warsh', 102, 1, 'ࡰلْهٜيٰكُمُ ࡲ۬لتَّكَاثُرُ', 'ࡰلهيكم ࡲلتكاثر', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-2', 'warsh', 102, 2, 'حَتَّىٰ زُرْتُمُ ࡲ۬لْمَقَابِرَ࣌', 'حتى زرتم ࡲلمقابر࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-3', 'warsh', 102, 3, 'كَلَّا سَوْفَ تَعْلَمُونَ', 'كلا سوف تعلمون', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-4', 'warsh', 102, 4, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ࣌', 'ثم كلا سوف تعلمون࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-5', 'warsh', 102, 5, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ࡰ۬لْيَقِينِ࣌', 'كلا لو تعلمون علم ࡰليقين࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-6', 'warsh', 102, 6, 'لَتَرَوُنَّ ࡰ۬لْجَحِيمَ', 'لترون ࡰلجحيم', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-7', 'warsh', 102, 7, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ࡰ۬لْيَقِينِ', 'ثم لترونها عين ࡰليقين', NULL, 600, 'local:warsh-text.json'),
  ('warsh-102-8', 'warsh', 102, 8, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ࡴ۬لنَّعِيمِ࣌', 'ثم لتسلن يومئذ عن ࡴلنعيم࣌', NULL, 600, 'local:warsh-text.json'),
  ('warsh-103-1', 'warsh', 103, 1, 'وَالْعَصْرِ إِنَّ ࡰ۬لِانسَٰنَ لَفِے خُسْرٍ', 'والعصر إن ࡰلانسن لفے خسر', NULL, 601, 'local:warsh-text.json'),
  ('warsh-103-2', 'warsh', 103, 2, 'ࡴلَّا ࡰ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ ࡲ۬لصَّٰلِحَٰتِ وَتَوَاصَوْاْ بِالْحَقِّ', 'ࡴلا ࡰلذين ءامنوا وعملوا ࡲلصلحت وتواصوا بالحق', NULL, 601, 'local:warsh-text.json'),
  ('warsh-103-3', 'warsh', 103, 3, 'وَتَوَاصَوْاْ بِالصَّبْرِ࣌', 'وتواصوا بالصبر࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-1', 'warsh', 104, 1, 'وَيْلࣱ لِّكُلِّ هُمَزَةࣲ لُّمَزَةٍ', 'ويل لكل همزة لمزة', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-2', 'warsh', 104, 2, 'ࡴ۬لذِے جَمَعَ مَالاࣰ وَعَدَّدَهُۥ', 'ࡴلذے جمع مالا وعدده', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-3', 'warsh', 104, 3, 'يَحْسِبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', 'يحسب أن ماله أخلده', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-4', 'warsh', 104, 4, 'كَلَّا࣌ لَيُنۢبَذَنَّ فِے ࡴ۬لْحُطَمَةِ࣌', 'كلا࣌ لينبذن فے ࡴلحطمة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-5', 'warsh', 104, 5, 'وَمَآ أَدْرٜيٰكَ مَا ࡰ۬لْحُطَمَةُ࣌', 'وما أدريك ما ࡰلحطمة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-6', 'warsh', 104, 6, 'نَارُ ࡲ۬للَّهِ ࡴ۬لْمُوقَدَةُ', 'نار ࡲلله ࡴلموقدة', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-7', 'warsh', 104, 7, 'ࡲ۬لتِے تَطَّلِعُ عَلَى ࡰ۬لَافْـِٕدَةِ࣌', 'ࡲلتے تطلع على ࡰلافدة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-8', 'warsh', 104, 8, 'إِنَّهَا عَلَيْهِم مُّوصَدَةࣱ', 'إنها عليهم موصدة', NULL, 601, 'local:warsh-text.json'),
  ('warsh-104-9', 'warsh', 104, 9, 'فِے عَمَدࣲ مُّمَدَّدَةٍ࣌', 'فے عمد ممددة࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-1', 'warsh', 105, 1, 'ࡰلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ࡴ۬لْفِيلِ࣌', 'ࡰلم تر كيف فعل ربك بأصحب ࡴلفيل࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-2', 'warsh', 105, 2, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِے تَضْلِيلࣲ', 'ألم يجعل كيدهم فے تضليل', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-3', 'warsh', 105, 3, 'وَأَرْسَلَ عَلَيْهِمْ طَيْراً ࡰبَابِيلَ', 'وأرسل عليهم طيرا ࡰبابيل', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-4', 'warsh', 105, 4, 'تَرْمِيهِم بِحِجَارَةࣲ مِّن سِجِّيلࣲ', 'ترميهم بحجارة من سجيل', NULL, 601, 'local:warsh-text.json'),
  ('warsh-105-5', 'warsh', 105, 5, 'فَجَعَلَهُمْ كَعَصْفࣲ مَّاكُولࣲ࣌', 'فجعلهم كعصف ماكول࣌', NULL, 601, 'local:warsh-text.json'),
  ('warsh-106-1', 'warsh', 106, 1, 'لِّإِيلَٰفِ قُرَيْشٍ', 'لإيلف قريش', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-2', 'warsh', 106, 2, 'ࡴيلَٰفِهِمْ رِحْلَةَ ࡰ۬لشِّتَآءِ وَالصَّيْفِ࣌', 'ࡴيلفهم رحلة ࡰلشتاء والصيف࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-3', 'warsh', 106, 3, 'فَلْيَعْبُدُواْ رَبَّ هَٰذَا ࡰ۬لْبَيْتِ', 'فليعبدوا رب هذا ࡰلبيت', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-4', 'warsh', 106, 4, 'ࡴ۬لذِےٓ أَطْعَمَهُم مِّن جُوعࣲ', 'ࡴلذے أطعمهم من جوع', NULL, 602, 'local:warsh-text.json'),
  ('warsh-106-5', 'warsh', 106, 5, 'وَءَامَنَهُم مِّنْ خَوْفٍ࣌', 'وءامنهم من خوف࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-1', 'warsh', 107, 1, 'ࡰرَٰٓيْتَ ࡰ۬لذِے يُكَذِّبُ بِالدِّينِ', 'ࡰريت ࡰلذے يكذب بالدين', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-2', 'warsh', 107, 2, 'فَذَٰلِكَ ࡰ۬لذِے يَدُعُّ ࡲ۬لْيَتِيمَ', 'فذلك ࡰلذے يدع ࡲليتيم', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-3', 'warsh', 107, 3, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ࡴ۬لْمِسْكِينِ࣌', 'ولا يحض على طعام ࡴلمسكين࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-4', 'warsh', 107, 4, 'فَوَيْلࣱ لِّلْمُصَلِّينَ', 'فويل للمصلين', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-5', 'warsh', 107, 5, 'ࡰ۬لذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 'ࡰلذين هم عن صلاتهم ساهون', NULL, 602, 'local:warsh-text.json'),
  ('warsh-107-6', 'warsh', 107, 6, 'ࡰ۬لذِينَ هُمْ يُرَآءُونَ وَيَمْنَعُونَ ࡰ۬لْمَاعُونَ࣌', 'ࡰلذين هم يراءون ويمنعون ࡰلماعون࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-108-1', 'warsh', 108, 1, 'إِنَّآ أَعْطَيْنَٰكَ ࡰ۬لْكَوْثَرَ', 'إنا أعطينك ࡰلكوثر', NULL, 602, 'local:warsh-text.json'),
  ('warsh-108-2', 'warsh', 108, 2, 'فَصَلِّ لِرَبِّكَ وَانْحَرِ࣌', 'فصل لربك وانحر࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-108-3', 'warsh', 108, 3, 'ࡴنَّ شَانِئَكَ هُوَ ࡰ۬لَابْتَرُ࣌', 'ࡴن شانئك هو ࡰلابتر࣌', NULL, 602, 'local:warsh-text.json'),
  ('warsh-109-1', 'warsh', 109, 1, 'قُلْ يَٰٓأَيُّهَا ࡰ۬لْكَٰفِرُونَ', 'قل يأيها ࡰلكفرون', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-2', 'warsh', 109, 2, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 'لا أعبد ما تعبدون', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-3', 'warsh', 109, 3, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ࣌', 'ولا أنتم عبدون ما أعبد࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-4', 'warsh', 109, 4, 'وَلَآ أَنَا عَابِدࣱ مَّا عَبَدتُّمْ', 'ولا أنا عابد ما عبدتم', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-5', 'warsh', 109, 5, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ࣌', 'ولا أنتم عبدون ما أعبد࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-109-6', 'warsh', 109, 6, 'لَكُمْ دِينُكُمْ وَلِيَ دِينِ࣌', 'لكم دينكم ولي دين࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-110-1', 'warsh', 110, 1, 'إِذَا جَآءَ نَصْرُ ࡲ۬للَّهِ وَالْفَتْحُ', 'إذا جاء نصر ࡲلله والفتح', NULL, 603, 'local:warsh-text.json'),
  ('warsh-110-2', 'warsh', 110, 2, 'وَرَأَيْتَ ࡰ۬لنَّاسَ يَدْخُلُونَ فِے دِينِ ࡴ۬للَّهِ أَفْوَاجاࣰ', 'ورأيت ࡰلناس يدخلون فے دين ࡴلله أفواجا', NULL, 603, 'local:warsh-text.json'),
  ('warsh-110-3', 'warsh', 110, 3, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ࣌ إِنَّهُۥ كَانَ تَوَّاباࣰ࣌', 'فسبح بحمد ربك واستغفره࣌ إنه كان توابا࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-1', 'warsh', 111, 1, 'تَبَّتْ يَدَآ أَبِے لَهَبࣲ وَتَبَّ࣌', 'تبت يدا أبے لهب وتب࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-2', 'warsh', 111, 2, 'مَآ أَغْنٜىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ࣌', 'ما أغنى عنه ماله وما كسب࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-3', 'warsh', 111, 3, 'سَيَصْلَىٰ نَاراࣰ ذَاتَ لَهَبࣲ', 'سيصلى نارا ذات لهب', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-4', 'warsh', 111, 4, 'وَامْرَأَتُهُۥ࣌ حَمَّالَةُ ࡲ۬لْحَطَبِ', 'وامرأته࣌ حمالة ࡲلحطب', NULL, 603, 'local:warsh-text.json'),
  ('warsh-111-5', 'warsh', 111, 5, 'فِے جِيدِهَا حَبْلࣱ مِّن مَّسَدࣲ࣌', 'فے جيدها حبل من مسد࣌', NULL, 603, 'local:warsh-text.json'),
  ('warsh-112-1', 'warsh', 112, 1, 'قُلْ هُوَ ࡰ۬للَّهُ أَحَدٌ࣌', 'قل هو ࡰلله أحد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-112-2', 'warsh', 112, 2, 'ࡴ۬للَّهُ ࡲ۬لصَّمَدُ࣌', 'ࡴلله ࡲلصمد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-112-3', 'warsh', 112, 3, 'لَمْ يَلِدْ وَلَمْ يُولَدْ࣌', 'لم يلد ولم يولد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-112-4', 'warsh', 112, 4, 'وَلَمْ يَكُن لَّهُۥ كُفُؤاً ࡰحَدࣱ࣌', 'ولم يكن له كفؤا ࡰحد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-1', 'warsh', 113, 1, 'قُلَ ࡰعُوذُ بِرَبِّ ࡴ۬لْفَلَقِ', 'قل ࡰعوذ برب ࡴلفلق', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-2', 'warsh', 113, 2, 'مِن شَرِّ مَا خَلَقَ', 'من شر ما خلق', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-3', 'warsh', 113, 3, 'وَمِن شَرِّ غَاسِقٍ ࡴذَا وَقَبَ', 'ومن شر غاسق ࡴذا وقب', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-4', 'warsh', 113, 4, 'وَمِن شَرِّ ࡴ۬لنَّفَّٰثَٰتِ فِے ࡴ۬لْعُقَدِ', 'ومن شر ࡴلنفثت فے ࡴلعقد', NULL, 604, 'local:warsh-text.json'),
  ('warsh-113-5', 'warsh', 113, 5, 'وَمِن شَرِّ حَاسِدٍ ࡴذَا حَسَدَ࣌', 'ومن شر حاسد ࡴذا حسد࣌', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-1', 'warsh', 114, 1, 'قُلَ ࡰعُوذُ بِرَبِّ ࡴ۬لنَّاسِ', 'قل ࡰعوذ برب ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-2', 'warsh', 114, 2, 'مَلِكِ ࡴ۬لنَّاسِ', 'ملك ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-3', 'warsh', 114, 3, 'إِلَٰهِ ࡴ۬لنَّاسِ', 'إله ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-4', 'warsh', 114, 4, 'مِن شَرِّ ࡴ۬لْوَسْوَاسِ ࡴ۬لْخَنَّاسِ', 'من شر ࡴلوسواس ࡴلخناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-5', 'warsh', 114, 5, 'ࡴ۬لذِے يُوَسْوِسُ فِے صُدُورِ ࡴ۬لنَّاسِ', 'ࡴلذے يوسوس فے صدور ࡴلناس', NULL, 604, 'local:warsh-text.json'),
  ('warsh-114-6', 'warsh', 114, 6, 'مِنَ ࡰ۬لْجِنَّةِ وَالنَّاسِ࣌', 'من ࡰلجنة والناس࣌', NULL, 604, 'local:warsh-text.json')
